// 地区間宅配依頼：期限切れチェック（受注から2〜3日で失効）。街区探索の主要な入口で毎回呼ぶ想定
function checkVillageDeliveryExpiry(){
 const dq = PC._villageBackalleyDelivery;
 if(!dq || !dq.active || dq.deadlineDay == null) return;
 if(GAME_TIME.totalDays > dq.deadlineDay){
  dq.active = false;
  showSaveToast(`${dq.recipient}への届け物の期限が過ぎてしまった…`);
 }
}

function getLocalWantedBoard(townId){
 if(!PC._localWantedBoards) PC._localWantedBoards = {};
 const board = PC._localWantedBoards[townId];
 const today = GAME_TIME.totalDays;
 if(!board || (today - board.generatedDay) >= 7){
  const count = 1 + Math.floor(Math.random()*3); // 1〜3名
  const targets = [];
  for(let i=0;i<count;i++){
   const npc = generateNPC(1);
   const c = LOCAL_WANTED_CRIMES[Math.floor(Math.random()*LOCAL_WANTED_CRIMES.length)];
   const reward = 10 + Math.floor(Math.random()*21); // 10〜30GP
   targets.push({ id: townId+'_'+today+'_'+i, name:npc.name, npc, crime:c.crime, desc:c.desc, reward, resolved:false });
  }
  // 依頼には繋がらない雑多な貼り紙も2〜4枚、週替わりで一緒に貼り出す（汎用プール＋その町固有の貼り紙を混ぜる）
  const noticeCount = 2 + Math.floor(Math.random()*3);
  const noticePool = [...TOWN_BOARD_NOTICES, ...(TOWN_BOARD_NOTICES_BY_TOWN[townId]||[]).map(t=>({text:t}))];
  const notices = [];
  for(let i=0; i<noticeCount && noticePool.length; i++){
   const idx = Math.floor(Math.random()*noticePool.length);
   notices.push(_finalizeBoardNotice(noticePool.splice(idx,1)[0]));
  }
  // 貼り紙の中に解決可能な種類（resolveType）が含まれていれば、街区探索側で対応する遭遇を有効にする
  const activeMiniTypes = [...new Set(notices.filter(n=>n.resolveType).map(n=>n.resolveType))];
  PC._localWantedBoards[townId] = { generatedDay: today, targets, notices, activeMiniTypes };
  return PC._localWantedBoards[townId];
 }
 if(!board.notices){
  // 既存セーブデータ互換：貼り紙情報が無ければこの機会に生成しておく
  const noticeCount = 2 + Math.floor(Math.random()*3);
  const noticePool = [...TOWN_BOARD_NOTICES, ...(TOWN_BOARD_NOTICES_BY_TOWN[townId]||[]).map(t=>({text:t}))];
  const notices = [];
  for(let i=0; i<noticeCount && noticePool.length; i++){
   const idx = Math.floor(Math.random()*noticePool.length);
   notices.push(_finalizeBoardNotice(noticePool.splice(idx,1)[0]));
  }
  board.notices = notices;
  board.activeMiniTypes = [...new Set(notices.filter(n=>n.resolveType).map(n=>n.resolveType))];
 }
 if(!board.activeMiniTypes){
  // 既存セーブデータ互換：旧バージョンのnotices（文字列配列）しかない場合は解決可能な種類なしとする
  board.activeMiniTypes = board.notices.length && typeof board.notices[0]==='object'
   ? [...new Set(board.notices.filter(n=>n.resolveType).map(n=>n.resolveType))] : [];
 }
 // 既存セーブデータ互換：名前を埋め込む前のバージョンで生成された「言付け」「商家の密輸」の貼り紙が残っていたら、
 // このタイミングで名前を補って直す（7日の更新を待たず、その場で修正する）
 if(Array.isArray(board.notices)){
  board.notices = board.notices.map(n=>{
   if(n && typeof n==='object' && n.resolveType==='message' && !n.npcName) return _finalizeBoardNotice(n);
   if(n && typeof n==='object' && n.resolveType==='rumor' && n.rumorId==='smuggling' && !n.merchantName) return _finalizeBoardNotice(n);
   return n;
  });
 }
 return board;
}

// ══════════════════════════════════════════
// 酒場の噂 × 町歩き連携
// ・掲示板（getLocalWantedBoard）の「井戸端の噂」と同じ内容を、酒場の主人との会話でも聞ける
// ・聞いた噂（notice.heardAtTavern）は町歩きで優先して出現し、専用イベントでは最初の聞き込みを省略できる
// ・解決すると、町の人からのお礼として酒場の主人が10〜30GPをくれる（PC._tavernThanks[townId]）
// ══════════════════════════════════════════
// 酒場の主人が語る噂。最後に「調べに行ってみないか」と水を向け、該当の街区へ遷移できる（districts は向かう地区の優先順）
const TAVERN_RUMOR_LINES = {
 strange_light:  { intro:'主人はグラスを磨く手を止め、声を潜めた。',
  text:'「最近、町外れで妙な光を見たってやつが何人か来てな。七色にゆらゆら変わるらしい。気味が悪くて、誰も近づきたがらねえんだ。……あんた、腕に覚えがあるんだろう？　ちょいと調べに行ってみちゃくれないか」',
  districts:['oldtown','harbor','garrison','admin','market'] },
 smuggling:      { intro:'主人はカウンター越しに身を乗り出し、周りを気にしながら言った。',
  text:'「ここだけの話だがな、どこぞの商家が裏で御禁制の品を扱ってるって噂だ。羽振りが良すぎると思ってたんだよ。……あんた、顔が利きそうだ。ちょいと探りを入れに行ってみないか」',
  districts:['market','harbor','admin','oldtown','garrison'] },
 graveyard_moan: { intro:'主人は空いた杯を拭きながら、ため息まじりに言った。',
  text:'「夜中に墓地の前を通ると、唸り声が聞こえるって客が増えててな。風の音じゃねえと皆言ってる。放っておくのも気味が悪い。……あんた、ちょっと見てきちゃくれねえか」',
  districts:['oldtown','admin','market','harbor','garrison'] },
 hero_treasure:  { intro:'主人は昔を懐かしむように、遠い目をして言った。',
  text:'「この町のどこかに、昔の英雄が遺した宝が眠ってるって言い伝えがあるのは知ってるか？　墓地のあたりだって話もある。ただの昔話かもしれねえが……気になるなら、調べに行ってみるといい」',
  districts:['oldtown','admin','market','harbor','garrison'] },
};
const TAVERN_DISTRICT_LABELS = {admin:'行政地区', oldtown:'旧市街地区', harbor:'港湾地区', market:'大市場・隊商地区', garrison:'軍営・練兵地区'};
const TAVERN_THANKS_LINES = {
 strange_light:  { solved:'「町外れの光の件、片づけてくれたそうだな。町の連中からだ、受け取ってくれ」', debunked:'「町外れの光の件、ガセだと突き止めてくれたそうだな。おかげで皆が安心した。町の連中からだ、受け取ってくれ」' },
 smuggling:      { solved:'「あの商家の件、おかげで町の空気がよくなった。町の連中からの礼だ、受け取ってくれ」', debunked:'「商家の噂はガセだったそうだな。無実の商人を疑わずに済んだよ。町の連中からの礼だ、受け取ってくれ」' },
 graveyard_moan: { solved:'「墓地の件、聞いたぞ。夜も安心して歩けるようになったと町の者たちが礼を言っていた。皆からの気持ちだ、受け取ってくれ」', debunked:'「墓地の唸り声はただの噂だったそうだな。おかげで皆が安心した。町の者たちからの礼だ、受け取ってくれ」' },
 hero_treasure:  { solved:'「塚の件、聞いたぞ。墓荒らしどもを追い払ってくれて助かった。町の者たちからの礼だ、受け取ってくれ」', debunked:'「英雄の宝の話はガセだったそうだな。無駄な探し物をする者が減るだろう。町の者たちからの礼だ、受け取ってくれ」' },
};

// その町の掲示板に貼られている噂の貼り紙（未解決のものだけ）
function _tavernBoardRumorNotices(townId){
 if(!SMALL_TOWN_HUB_LIST.includes(townId)) return [];
 const board = getLocalWantedBoard(townId);
 if((board.resolvedMiniTypes||[]).includes('rumor')) return []; // 解決済みの種類は、次の掲示板更新まで出さない
 return (board.notices||[]).filter(n=>n && typeof n==='object' && n.resolveType==='rumor' && n.rumorId);
}

// 酒場で聞かせる噂を1つ選ぶ（まだ聞いていない噂を優先。全て聞き終えていれば null）
function _pickTavernRumor(townId){
 const unheard = _tavernBoardRumorNotices(townId).filter(n=>!n.heardAtTavern && TAVERN_RUMOR_LINES[n.rumorId]);
 if(!unheard.length) return null;
 return unheard[Math.floor(Math.random()*unheard.length)];
}

// 噂ノード（rumorId）に対応する貼り紙が、酒場で聞いた噂かどうか
function _rumorHeardAtTavern(node, dung){
 if(!node || !node.rumorId || !dung || !dung.villageId) return false;
 const board = getLocalWantedBoard(dung.villageId);
 const n = (board.notices||[]).find(x=>x && typeof x==='object' && x.resolveType==='rumor' && x.rumorId===node.rumorId);
 return !!(n && n.heardAtTavern);
}

// 噂を解決した（または、ガセだと突き止めた）ので、酒場の主人からのお礼を受け取り待ちにする
// kind: 'solved'（事態を解決した）／'debunked'（ガセだと突き止めた）
function _queueTavernThanks(node, dung, kind){
 if(!node || !node.rumorId || !dung || !dung.villageId) return;
 if(!SMALL_TOWN_HUB_LIST.includes(dung.villageId)) return;
 if(!PC._tavernThanks) PC._tavernThanks = {};
 const list = PC._tavernThanks[dung.villageId] || (PC._tavernThanks[dung.villageId] = []);
 const key = node.miniResolveKey || node.id;
 if(list.some(t=>t.key===key)) return; // 同じ遭遇での二重登録を防ぐ
 list.push({ rumorId:node.rumorId, kind: kind||'solved', key, day:GAME_TIME.totalDays });
}

// 酒場の会話の最初に、受け取り待ちのお礼があれば出す（出したら true）
function _showTavernThanks(townId){
 const list = PC._tavernThanks && PC._tavernThanks[townId];
 if(!list || !list.length) return false;
 const t = list.shift();
 const amount = 10 + Math.floor(Math.random()*21); // 10〜30GP
 gainGP(amount);
 updateHUD();
 const lines = TAVERN_THANKS_LINES[t.rumorId] || {};
 const text = lines[t.kind] || lines.solved || '「町の者たちからの礼だ、受け取ってくれ」';
 const header = `<div style="font-size:calc(var(--font-sm) + 1px);color:#f0ece0;margin-bottom:8px"> 酒場の主人</div>
  <div style="font-size:var(--font-sm);color:#c8b8a0;line-height:1.8;margin-bottom:10px">主人が声をかけてきた。</div>`;
 const msgBox = `<div style="font-size:var(--font-sm);color:#e0d8cc;line-height:1.8;padding:8px;background:#0a0804;border-radius:3px;border-left:2px solid var(--border)">${text}</div>
  <div style="font-size:var(--font-sm);color:#ffcc88;line-height:1.8;margin-top:8px">町の人たちからのお礼として${amount}GPを受け取った。</div>`;
 _showPatronPanel(header + msgBox, ()=>{ updateHUD(); });
 return true;
}

// 噂に対応する街区（その町にある地区のうち、優先順の先頭）。向かえる地区がなければ null
function _tavernRumorDistrict(townId, rumorId){
 const def = TAVERN_RUMOR_LINES[rumorId];
 const towns = SMALL_TOWN_DISTRICTS[townId];
 if(!def || !towns) return null;
 const keys = Object.keys(towns);
 return def.districts.find(k=>keys.includes(k)) || keys[0] || null;
}

// 酒場の主人の誘いに乗って、噂の街区へ向かう
function _tavernRumorGo(townId, districtType){
 closePatronPanel();
 updateHUD();
 enterVillageBackAlley(townId, districtType);
 // 酒場の主人の誘いで向かった今回の町歩きだけ、聞いた噂の遭遇率を倍にする（この町歩きの間だけ有効。入り直すと消える）
 if(PC._yeldunDungeon) PC._yeldunDungeon.tavernRumorBoost = true;
}

// 酒場の主人が噂を語り、「調べに行ってみないか」と誘う（語ったら true）
function _showTavernRumor(townId){
 const n = _pickTavernRumor(townId);
 if(!n) return false;
 const def = TAVERN_RUMOR_LINES[n.rumorId];
 n.heardAtTavern = true;
 const district = _tavernRumorDistrict(townId, n.rumorId);
 const header = `<div style="font-size:calc(var(--font-sm) + 1px);color:#f0ece0;margin-bottom:8px"> 酒場の主人</div>
  <div style="font-size:var(--font-sm);color:#c8b8a0;line-height:1.8;margin-bottom:10px">${def.intro}</div>`;
 const msgBox = `<div style="font-size:var(--font-sm);color:#e0d8cc;line-height:1.8;padding:8px;background:#0a0804;border-radius:3px;border-left:2px solid #553300">${def.text}</div>`;
 const btnStyle = 'display:block;width:100%;margin-top:8px;font-size:calc(var(--font-sm) - 1px);padding:10px;background:var(--panel);border:1px solid #a08848;color:#f0ece0;font-family:system-ui,sans-serif;cursor:pointer;border-radius:3px';
 const buttons = district
  ? `<button style="${btnStyle}" onclick="_tavernRumorGo('${townId}','${district}')"> 調べに行く（${TAVERN_DISTRICT_LABELS[district]||district}へ）</button>
     <button style="${btnStyle};border-color:#554433;color:#e0d0c0" onclick="closePatronPanel();updateHUD()"> 今は遠慮しておく</button>`
  : '';
 _showPatronPanel(header + msgBox + buttons, ()=>{ updateHUD(); });
 return true;
}

