function villageCfg(dung){
 // 小規模拠点（中央広場→行政地区／旧市街地区）は、地区タイプ共通データ＋拠点固有フレーバーを合成する
 if(dung?.districtType && SMALL_TOWN_DISTRICTS[dung.villageId]){
  const townDistrict = SMALL_TOWN_DISTRICTS[dung.villageId][dung.districtType];
  const typeCfg = DISTRICT_TYPE_CONFIGS[dung.districtType];
  if(townDistrict && typeCfg){
   // 拠点固有の追加イベント（extraIncidents）があれば、共通イベントプールに合成する
   const incidents = townDistrict.extraIncidents
    ? [...typeCfg.incidents, ...townDistrict.extraIncidents]
    : typeCfg.incidents;
   return { ...typeCfg, incidents, flavor: townDistrict.flavor, label: townDistrict.label || typeCfg.defaultLabel };
  }
 }
 return VILLAGE_BACKALLEY_CONFIGS[dung?.villageId] || VILLAGE_BACKALLEY_CONFIGS.verda;
}

