function ydStyleAtm(design){
 const style = design?.dungeonStyle || 'mine';
 const arr = YD_STYLE_ATM[style] || YD_STYLE_ATM.mine;
 return arr[Math.floor(Math.random()*arr.length)];
}

function ydNodeTxt(node, floor){
 const dung   = PC._yeldunDungeon;
 const design = dung.design;
 // ヴェルダ裏路地では明るい時間帯（朝・昼・午後）は松明インジケータを表示しない
 const tBar   = (dung.isHideoutDungeon || (dung.isVillageBackAlley && design.isNaturalLight)) ? '' : (torchIndicator ? torchIndicator() : '');
 const style  = design?.dungeonStyle || 'mine';
 const fLabel = dung.isHideoutDungeon
  ? `<span style="color:#e0d8c8;font-size:calc(var(--font-sm) - 1px)">賞金首のアジト　${floor}F</span>`
  : dung.isVillageBackAlley
  ? `<span style="color:#e0d8c8;font-size:calc(var(--font-sm) - 1px)">${villageCfg(dung).label}　── ${villagePhase(getGameHour()).label} ──</span>`
  : `<span style="color:#e0d8c8;font-size:calc(var(--font-sm) - 1px)">B${floor}F ${YD_STYLE_DATA[style]?.name||'ダンジョン'}</span>`;

 const isLit = design.isNaturalLight;
 const darkWarn = !isLit && (PC._torchTurns||0)<=0
  ? '<br><span style="color:#e0d0d0"> 松明が切れた！暗闇の中を手探りで進む。</span>' : '';

 switch(node.type){
  case 'entrance':{
   const huntDone = dung.isHuntDungeon && dung.huntCompleted;
   const killed = dung.isHuntDungeon ? (dung.killedKeys?.filter(k=>PC[k]).length||0) : 0;
   const total  = dung.targetCount || 0;
   // 入口テキストをダンジョンに固定（初回のみ生成）
   if(!dung._entranceTxt) dung._entranceTxt = {};
   if(!dung._entranceTxt[floor]){
    dung._entranceTxt[floor] = floor===1
     ? (dung.isHideoutDungeon ? _rdungPick(HIDEOUT_FLAVOR.entrances[dung.design.messy ? 'messy' : 'neat'])
        : dung.isVillageBackAlley ? _rdungPick(villageCfg(dung).flavor.entrances) : ydEntranceTxt(design))
     : dung.isHideoutDungeon ? _rdungPick(HIDEOUT_FLAVOR.entrances[dung.design.messy ? 'messy' : 'neat'])
     : `B${floor}Fへ続く階段の降り口付近だ。足元の石段は磨り減っており、これまで幾度となく踏まれてきたことが分かる。`;
   }
   const entrTxt = dung._entranceTxt[floor];
   return `${tBar}${fLabel}<br><br>
    <span style="color:#d0c8b8">${entrTxt}</span>
    ${dung.isHuntDungeon ? `<br><br><span style="color:${huntDone?'var(--nature2)':'var(--amber)'}">討伐：${killed}/${total}体${huntDone?'  全滅させた！':''}</span>` : ''}`;
  }

  case 'passage':
   return `${tBar}${fLabel}<br><br>
    <span style="color:#b8a890">${node.atm || ydStyleAtm(design)}</span>
    ${node.dist && !dung.isVillageBackAlley ? `<br><span style="color:#d0c8b8;font-size:calc(var(--font-sm) - 1px)"> 通路の幅：${node.dist}</span>` : ''}
    ${node.lootKey && !PC[node.lootKey] ? `<br><br><span style="color:#f0ece0">${dung.isVillageBackAlley ? villageCfg(dung).lootText : ' 壁際に何か光るものが落ちている。'}</span>` : ''}
    ${node.lootKey && PC[node.lootKey]  ? `<br><br><span style="color:#d0c8b8">（拾い済み）</span>` : ''}
    ${darkWarn}`;

  case 'turn':{
   const td = node.turnDir==='right'?'右':'左';
   const turnAtms = dung.isHideoutDungeon
    ? HIDEOUT_FLAVOR.turn[dung.design.messy ? 'messy' : 'neat']
    : dung.isVillageBackAlley
    ? villageCfg(dung).flavor.turn.map(t=>t.replace(/{td}/g, td))
    : [
    `通路が${td}手に直角に曲がっている。曲がり角の壁に手をつくと、石が思いのほか冷たい。その先の暗闇から、微かな気配が漂ってくる。`,
    `${td}に折れた通路の角に、何かが壁を引っ掻いた跡が残っている。大型の爪痕で、かなり深く刻まれている。`,
    `${td}へ曲がる通路の角に古い標識の残骸がある。文字は消えて読めないが、矢印の形だけが辛うじて分かる。`,
    `通路が${td}手へ緩やかに弧を描くように曲がっている。曲がった先から風が吹いてきており、その先に広い空間がある証拠だ。`,
    `${td}に折れた角の天井が一部崩れており、小石が散乱している。足音を立てると崩れが広がりそうだ。`,
    `${td}への曲がり角の床に、誰かが刻んだ矢印がある。方向は${td}を指しており、誰かがここで道を記録した。`,
    `通路が${td}へ曲がった先で、一瞬だけ何かが光った気がした。振り返っても何もない——松明の見せた錯覚か。`,
    `${td}に曲がる角の床が他より磨り減っている。多くの者がここを通り、その角を踏んでいった証だ。`,
    `通路が${td}手に折れている。曲がり角の直前で足音が止まる——耳を澄ませると、その先から微かな呼吸音がした。`,
    `${td}への曲がり角に古い血痕がある。茶色く変色しているが、かなりの量がここに流れた痕跡だ。`,
   ];
   return `${tBar}${fLabel}<br><br>
    <span style="color:#b8a890">${turnAtms[Math.floor(Math.random()*turnAtms.length)]}</span>${darkWarn}`;
  }

  case 'side':{
   const sideAtms = dung.isVillageBackAlley ? villageCfg(dung).flavor.side : {
    left90:[
     '左手の壁が一部切れて、暗い支通路が口を開けている。主通路より狭く、奥が見えない。',
     '左に分岐する通路がある。入口の縁に引っ掻き傷が集中しており、何かがここを定期的に通っている。',
     '左手の岩に人工的な開口部がある。加工の仕方が主通路と異なり、後から掘り抜いたものらしい。',
     '左手の通路の入口に古い松明ホルダーがある。使われた跡があり、誰かがここを定期的に訪れていた。',
     '左に伸びる通路から冷たい風が吹いてくる。その先に空間があることは確かだ。',
     '左手の通路の床に引きずった跡がある。重いものを運んだ痕で、この先に何かが持ち込まれた。',
     '左に折れる通路の入口に、崩れた木戸の残骸が転がっている。かつてここを塞ぐ扉があったようだ。',
     '左手に開いた通路の壁際に、古い足跡が乾いた泥となって残っている。かなり大きな足だ。',
     '左へ続く道の天井から、細い根が幾筋も垂れ下がっている。地上がそう遠くない証拠かもしれない。',
     '左に分かれる通路の奥から、規則的な滴りの音が聞こえてくる。何か液体が絶えず落ちているようだ。',
    ],
    right90:[
     '右手に支通路が続いている。こちらは主通路よりも古く、壁の石組みの様式が違う。',
     '右手の壁に細い隙間がある。人一人がやっと通れる幅で、その先に空間がある気配がする。',
     '右に分岐する通路の入口に干からびた血痕がある。かなり古いものだが、量は多い。',
     '右手の通路から獣の臭いがする。何かがこちらを縄張りにしているらしく、その気配が漂っている。',
     '右に伸びる通路の壁に誰かが書き残した記号がある。意味は分からないが、警告のようにも見える。',
     '右手の通路の奥で水の滴る音がする。地下水が近いか、別の空洞と繋がっているのかもしれない。',
     '右へ分かれる道の入口に、朽ちた縄の切れ端が結び付けられている。かつて何かの目印だったようだ。',
     '右手に開く通路の床だけが妙に平らに均されている。何度も往来があったことを物語っている。',
     '右に続く通路から、乾いた砂がさらさらと流れ落ちる音が聞こえる。',
     '右手の分岐の壁一面に、古い手形が幾つも押し付けられている。同じ手のものか、複数のものかは分からない。',
    ],
    tee:[
     'T字路に出た。左右どちらの通路も等しく暗く、どちらから臭いが来るかも判別できない。',
     'T字路の中央に古い道標の残骸が転がっている。文字は読めないが、指差す方向はまだ分かる——右だ。',
     '三方向に通路が延びるT字路だ。足元の泥を観察すると、足跡は左右の通路から来てそれぞれ別方向へ消えている。',
     'T字路の天井に古い滑車の跡がある。ここで何かを引き上げるか下ろすかしていたらしい。',
     '三叉路の中央の床だけが他より磨り減っている。多くの者がここで立ち止まり、どちらへ行くか迷ったのだろう。',
     'T字路の壁に三方向を指す矢印が刻まれている。それぞれの方向に記号があるが、意味は分からない。',
     'T字路の分岐点に小さな祠が据えられている。旅の安全を祈るためのものか、風化して原形が分からない。',
     '三方向に分かれる地点の壁に、それぞれ異なる色の顔料で印がつけられている。誰かの独自の目印らしい。',
     'T字路の中心に、崩れた石柱の根元だけが残っている。かつては何か目印になる柱があったのだろう。',
    ],
    cross:[
     '十字路に出た。四方向すべてから微かな気配がする。どれが正しい道かは分からない。',
     '十字路の天井に古い滑車の残骸が付いている。かつてここで重いものを吊り上げていたのだろう。',
     '四方に通路が延びる十字路だ。中央の床だけが他と色が違い、長年ここに何かが置かれていた跡がある。',
     '十字路の中心に古い井戸のような穴が開いている。覗き込んでも底は見えず、冷たい風だけが吹き上がる。',
     '四方向へ道が分かれる地点に、朽ちた道標が四本まとめて倒れている。それぞれ違う方角を指していたようだ。',
     '十字路の壁四面すべてに、同じ記号が繰り返し刻まれている。何かへの警告か、あるいは道しるべか。',
    ],
   };
   const arr = sideAtms[node.sideDir] || ['通路が分岐している。'];
   return `${tBar}${fLabel}<br><br>
    <span style="color:#b8a890">${arr[Math.floor(Math.random()*arr.length)]}</span>${darkWarn}`;
  }

  case 'alcove':{
   const posDesc = {left:'左手',right:'右手',ahead:'正面'};
   const contDescs = {
    empty:[
     `${posDesc[node.alcovePos]||''}の壁龕は空だ。内側に何かを置いていた痕跡が残るが、今は何もない。`,
     `${posDesc[node.alcovePos]||''}の小さな窪みには何もない。それでも、この窪みが作られた理由があるはずだ。`,
     `${posDesc[node.alcovePos]||''}の壁龕の底に、うっすらと四角い跡が残っている。かつて何かが置かれ、後に持ち去られたらしい。`,
     `${posDesc[node.alcovePos]||''}に彫り込まれた窪みがあるが、中は空っぽだ。表面には無数の細かい傷がついている。`,
     `${posDesc[node.alcovePos]||''}の壁龕を覗き込むが、埃が薄く積もっているだけだ。誰かが先にここを空にしたのだろう。`,
    ],
    statue:[
     `${posDesc[node.alcovePos]||''}の壁龕に石像が安置されている。どの神の像かは判然としないが、顔の部分だけが意図的に削られている。`,
     `${posDesc[node.alcovePos]||''}に石像がある。表面が黒く変色しており、長年にわたって油か血のようなものが塗られてきた跡がある。`,
     `${posDesc[node.alcovePos]||''}の窪みに小さな木像が立てられている。虫食いだらけだが、両手を組んだ姿だけは分かる。`,
     `${posDesc[node.alcovePos]||''}に佇む像は、片腕が根本から折れて足元に転がっている。誰が、いつ折ったのかは分からない。`,
     `${posDesc[node.alcovePos]||''}の壁龕に据えられた像の目に、小さな宝石がはめ込まれている。片方だけ、すでに抉り取られていた。`,
    ],
    fountain:[
     `${posDesc[node.alcovePos]||''}の岩から清水が染み出し、小さな水盤に溜まっている。水は透明だが、底が妙に深い。`,
     `${posDesc[node.alcovePos]||''}に石造りの泉がある。水面が静止しているのに、底から規則的に気泡が上がってくる。`,
     `${posDesc[node.alcovePos]||''}の窪みに水を湛えた石鉢がある。触れた指先がわずかにひりつくが、毒かどうかは分からない。`,
     `${posDesc[node.alcovePos]||''}から滴る水が石を穿ち、小さな水たまりを作っている。長い年月をかけて刻まれた溝が美しい。`,
     `${posDesc[node.alcovePos]||''}の泉の水面に、自分以外の何かが映り込んだ気がした。振り返っても誰もいない。`,
    ],
    chest:[
     `${posDesc[node.alcovePos]||''}の壁龕に木箱が押し込まれている。蓋の上に埃が積もっているが、鍵穴だけが新しく磨かれている。`,
     `${posDesc[node.alcovePos]||''}の窪みに古い箱がある。金具は錆びているが、箱自体は頑丈そうだ。何かが中で動いた気がした。`,
     `${posDesc[node.alcovePos]||''}に鉄帯で補強された小箱がある。持ち上げてみると、見た目より軽い——中身は少ないのかもしれない。`,
     `${posDesc[node.alcovePos]||''}の壁龕に木箱が隠すように置かれている。表面に爪で引っ掻いたような跡が幾筋も残っている。`,
     `${posDesc[node.alcovePos]||''}の窪みに古い革袋と木箱が並んでいる。革袋はすでに朽ちて、中身が床にこぼれ出していた。`,
    ],
    device:[
     `${posDesc[node.alcovePos]||''}に金属製の仕掛けがある。用途は分からないが、どこかに繋がっているらしく、細い鎖が壁に消えている。`,
     `${posDesc[node.alcovePos]||''}の壁龕に奇妙な機械仕掛けがある。歯車と棒で構成されており、動かすと何かが起きそうだ。`,
     `${posDesc[node.alcovePos]||''}に錘と滑車を組み合わせた装置がある。錆びついているが、まだ動く余地は残っていそうだ。`,
     `${posDesc[node.alcovePos]||''}の窪みに、ぜんまい仕掛けらしき小さな箱がある。耳を近づけると微かに歯車の音がする。`,
     `${posDesc[node.alcovePos]||''}に据えられた仕掛けから、細い真鍮の管が壁の奥へと伸びている。何かを送るための管かもしれない。`,
    ],
    clothing:[
     `${posDesc[node.alcovePos]||''}に衣類が丸めて押し込まれている。布は変色しているが形はある程度保たれており、防護目的の何かだったらしい。`,
     `${posDesc[node.alcovePos]||''}の窪みに革製の装備品が畳んで置かれている。主が置いて行ったのか、誰かがここに隠したのか。`,
     `${posDesc[node.alcovePos]||''}にマントのようなものが掛けられている。裾がぼろぼろに擦り切れ、色も判別できないほど褪せている。`,
     `${posDesc[node.alcovePos]||''}の壁龕に古い外套が丁寧に畳まれている。誰かがここへ戻ってくるつもりだったのかもしれない。`,
    ],
    paper:[
     `${posDesc[node.alcovePos]||''}の壁龕に羊皮紙の束がある。湿気でかなり傷んでおり、文字の判読は難しい。`,
     `${posDesc[node.alcovePos]||''}に折り畳んだ紙が挟まっている。文字は読めるが、何かの暗号か略語で意味が分からない。`,
     `${posDesc[node.alcovePos]||''}の窪みに巻物が数本立てかけられている。封蝋は既に割れており、中身は誰かが先に読んだ後らしい。`,
     `${posDesc[node.alcovePos]||''}に古びた手紙が一通残されている。宛名の部分だけが虫に食われて読めなくなっていた。`,
    ],
    food:[
     `${posDesc[node.alcovePos]||''}に食べ物の残骸がある。腐りかけており、ここに誰かがいたのはさほど昔のことではない。`,
     `${posDesc[node.alcovePos]||''}の窪みに干し肉と思しき固形物がある。乾燥しているので保存状態はいいが、誰のものかは分からない。`,
     `${posDesc[node.alcovePos]||''}に硬く干からびたパンの塊が置かれている。かじった跡が残っているが、歯型は人のものではなさそうだ。`,
     `${posDesc[node.alcovePos]||''}の壁龕に木の実の殻が山積みになっている。誰か、あるいは何かがここで長く食事を続けていたようだ。`,
    ],
    trash:[
     `${posDesc[node.alcovePos]||''}にガラクタが詰め込まれている。骨、布切れ、壊れた道具——誰かがここを物置として使っていたようだ。`,
     `${posDesc[node.alcovePos]||''}の窪みにがらくたが積まれている。よく見ると、一見ゴミに見えるものの中に意図的に配置された何かがある気がする。`,
     `${posDesc[node.alcovePos]||''}に壊れた武具の破片が捨てられている。折れた刃、ひしゃげた兜——ここで何かが決着したらしい。`,
     `${posDesc[node.alcovePos]||''}の壁龕に動物の骨が乱雑に積まれている。かじった跡から見て、大型の生き物の仕業だろう。`,
    ],
   };
   const descArr = contDescs[node.alcoveType] || [`${posDesc[node.alcovePos]||''}に小さな壁龕がある。`];
   return `${tBar}${fLabel}<br><br>
    <span style="color:#b8a890">${descArr[Math.floor(Math.random()*descArr.length)]}</span>
    ${node.alcoveType==='chest'&&node.treasureFloor&&!PC[node.alcoveKey]?`<br><span style="color:#f0ece0"> 鍵はかかっていない。</span>`:''}
    ${PC[node.alcoveKey]?`<br><span style="color:#d0c8b8">（探索済み）</span>`:''}
    ${darkWarn}`;
  }

  case 'room':{
   const monsterCleared = !node.monster || PC[node.monsterKey];
   const roomWidthLabel = node.roomWidth === 'unusual' ? '広大な' : node.roomWidth;
   const roomAtm = dung.isHideoutDungeon
    ? _rdungPick(HIDEOUT_FLAVOR.room[dung.design.messy ? 'messy' : 'neat'])
    : dung.isVillageBackAlley ? _rdungPick(villageCfg(dung).flavor.room) : ydStyleAtm(design);
   const roomHeader = dung.isHideoutDungeon
    ? HIDEOUT_FLAVOR.roomHeader[dung.design.messy ? 'messy' : 'neat']
    : dung.isVillageBackAlley ? villageCfg(dung).flavor.roomHeader : ` ${roomWidthLabel}部屋に出た`;
   return `${tBar}${fLabel}<br><br>
    <span style="color:#e0d8c8">${roomHeader}</span><br><br>
    <span style="color:#b8a890">${roomAtm}</span><br><br>
    ${ydRoomContentTxt(node)}
    ${node.treasureFloor&&monsterCleared&&node.roomContent!=='chest'&&!PC[node.roomKey+'_loot']?`<br><span style="color:#f0ece0">${dung.isVillageBackAlley?' 何か落ちている。':' 宝物がある。'}</span>`:''}
    ${darkWarn}`;
  }

  case 'stairs':{
   const up = node.stairsDelta<0;
   const visited = PC[node.stairsKey];
   const stairAtms = {
    staircase: up
     ? ['石段が上へ続いている。踏み面は磨り減り、手すりの金具だけが辛うじて残っている。','上り石段の壁に、かつてここを通った者たちが残した刻み印がある。何人が通り、何人が戻ったのか。','石段を見上げると、上方からわずかに光が差し込んでいるのが分かる。地上が近いのかもしれない。','摩耗した石段の端に、滑り止めの溝が刻まれている。かなり急な角度だったことがうかがえる。']
     : ['下り石段が続いている。深くなるにつれて空気が冷たく重くなる。','石段の向こうに暗闇が広がっている。一段降りるごとに、外の世界が遠ざかっていく感覚がある。','下りの石段の縁に、滑り落ちた跡のような擦り傷が残っている。慎重に降りる必要がありそうだ。','石段を降りるたび、足音の反響が変わっていく。かなり広い空間が下に控えているようだ。'],
    chimney: up
     ? ['岩壁に足場が打ち込まれた縦穴が上へ続いている。上端は暗くて見えないが、風が吹き降りてくる。','鉄製の梯子が垂直に伸びている。錆びているが体重を支えられそうだ——たぶん。','縦穴の岩肌に手がかりとなる窪みが連続して彫られている。誰かがここを何度も昇り降りした跡だ。','上へ続く縦穴から、かすかに鳥の声のようなものが聞こえてくる。地上が近い証だろうか。']
     : ['足場を使って降りる縦穴だ。底までどれくらいあるのか、投げた小石の音でおよその深さを測る。','縦穴の縁から覗くと深い暗闇が広がっている。下から冷たい空気が吹き上がってくる。','縦穴の壁に打ち込まれた杭が所々朽ちている。体重をかける前に確かめた方がよさそうだ。','縦穴の底からかすかな水音が聞こえる。かなりの深さまで続いているようだ。'],
    magic_stair:[
     '空中に浮かぶ光の踏み板が一列に続いている。踏み板は透明で、下が透けて見えそうだが実際には見えない。',
     '石段の形をした光の残像が階段状に並んでいる。魔法の階段だ。踏むと足元が固まるが、踏まなければ何もない空間だ。',
     '虚空に淡く光る紋様が階段状に浮かんでいる。触れると指先がぴりりと痺れ、確かな力の存在を感じさせる。',
     '床から浮き上がるように、半透明の光の段差が連なっている。一歩ごとに周囲の空気がわずかに震える。',
     '古い魔法陣の残光が階段の形を保ったまま宙に留まっている。今も術が生きている証拠だ。',
    ],
    magic_room:[
     '部屋全体が魔法の移動装置になっているようだ。床に刻まれた複雑な魔法陣が微かに光っている。',
     '壁から壁まで魔法陣が広がっている。その中心に立つと、奇妙な浮遊感と共に別の場所へ移動しそうな気配がある。',
     '部屋の四隅に埋め込まれた宝石が呼応するように明滅している。中央の床にも同じ紋様が描かれている。',
     '天井から床まで、金色の線で幾何学模様が描かれている。歩くたびに線がわずかに輝きを増していく。',
     '空気そのものが薄く発光しているような部屋だ。ここに立つだけで、体がどこかへ引かれる感覚がある。',
    ],
   };
   const stairArr = stairAtms[node.stairsType] || (up ? ['上へ続く道がある。'] : ['下へ続く道がある。']);
   const stairTxt = dung.isHideoutDungeon
    ? HIDEOUT_FLAVOR.stairs[dung.design.messy ? 'messy' : 'neat']
    : stairArr[Math.floor(Math.random()*stairArr.length)];
   return `${tBar}${fLabel}<br><br>
    <span style="color:#b8a890">${stairTxt}</span>
    <br><br><span style="color:#d0c8b8">${up?'▲ 上層':'▼ 下層'} B${node.targetFloor}Fへ続く${visited?' <span style="color:#d0c8b8">（通過済み）</span>':''}</span>
    ${darkWarn}`;
  }

  case 'trap':{
   const done = PC[node.trapKey];
   return `${tBar}${fLabel}<br><br>
    <span style="color:#b8a890">${dung.isVillageBackAlley ? _rdungPick(villageCfg(dung).flavor.passage) : ydStyleAtm(design)}</span>
    ${!done
     ? `<br><br><span style="color:#e8e0d0"> ${node.trapDesc || '何か怪しい気配がする。'} 注意が必要だ。</span>`
     : `<br><br><span style="color:#b0a080">（罠は処理済みだ）</span>`}
    ${darkWarn}`;
  }

  case 'encounter':{
   const tenseAtms = dung.isHideoutDungeon
    ? (dung.design.messy
       ? ['奥の部屋から、何かが動く物音がする。','足音を忍ばせる気配が、扉の向こうから伝わってくる。','散らかった荷物の陰に、何かが潜んでいるようだ。']
       : ['静まり返った廊下の先で、かすかに衣擦れの音がした。','整えられた部屋の奥から、緊張した気配が伝わってくる。','几帳面に並んだ調度品の陰に、誰かが息を潜めている。'])
    : dung.isVillageBackAlley
    ? villageCfg(dung).tenseAtms
    : [
    '空気が急に張り詰めた。何かがこちらの気配を察知したように、先の暗闇が静まり返っている。',
    '奥から低いうなり声のようなものが聞こえてくる。足を止めて耳を澄ますと、それは規則的な呼吸音だと分かった。',
    '床に新しい足跡が残っている。まだ乾ききっていない——ついさっきまで、何かがここにいた証拠だ。',
    '壁に引っ掻いたような新しい傷が走っている。爪の間隔からして、かなりの大きさの生き物のものだ。',
    '先の暗がりから、獣とも人ともつかない臭いが漂ってくる。近づくほどにその臭いは強くなる。',
    '前方の闇の中で、何かがこちらをじっと見ているような気配がする。目を凝らしても輪郭は見えない。',
    '静寂の中に、かすかな金属音が混じっている。何かが武装しているのかもしれない。',
   ];
   return `${tBar}${fLabel}<br><br>
    <span style="color:#b8a890">${!PC[node.monsterKey] ? tenseAtms[Math.floor(Math.random()*tenseAtms.length)] : (dung.isVillageBackAlley ? _rdungPick(villageCfg(dung).flavor.passage) : ydStyleAtm(design))}</span>
    ${!PC[node.monsterKey]
     ? `<br><br><span style="color:var(--white)"> <b>${node.monster.name}</b>が<b>${node.monster.count}体</b>、この先にいる！</span>`
     : `<br><br><span style="color:#b0a080">ここは静寂が戻っている。</span>`}
    ${darkWarn}`;
  }

  case 'dead_end':{
   const deadEndAtms = [
    '通路が行き止まりになっている。壁は固く、崩せるような隙間もない。引き返すしかないようだ。',
    '通路の突き当たりだ。壁をよく見ると、表面の石の色が一部だけ違う。何かを塗り固めた痕のようにも見える。',
    '行き止まりの壁に文字が刻まれている。「ここで終わり」という意味の古語だ——あるいはそれは警告だったのかもしれない。',
    '通路が袋小路になっている。天井の一か所だけ他より黒く煤けており、かつてここで長時間松明が焚かれていたことを示している。',
    '行き止まりだ。壁際に古い荷物の残骸がある。ここを最後の場所として選んだ者がいたらしい。',
    '通路の終端に、崩れかけた石積みがある。人為的に塞がれたようで、向こう側から音がするような気がした。',
    '行き止まりの床に、爪で引っ掻いたような跡が壁際まで続いている。何かがここまで這って来て、力尽きたようだ。',
    '突き当たりの壁一面に煤がこびりついている。何かを燃やした跡だが、灰の量からして一度ではなさそうだ。',
    '通路が唐突に途切れている。壁の継ぎ目が不自然に真っ直ぐで、後から人の手で塞がれた壁だと分かる。',
    '行き止まりに小さな祭壇の残骸がある。捧げ物らしき骨片が散らばっており、長らく誰も訪れていない。',
    '突き当たりの壁に無数の爪痕が交差している。焦って何かを掘ろうとした跡のようにも見える。',
    '通路の終わりに、崩れた天井からの土砂が積もっている。掘り返せば先に進めそうだが、時間がかかりそうだ。',
   ];
   const deadEndTxt = node.atm || deadEndAtms[Math.floor(Math.random()*deadEndAtms.length)];
   return `${tBar}${fLabel}<br><br>
    <span style="color:#b8a890">${deadEndTxt}</span>
    ${node.hiddenDoor&&!PC[node.hiddenDoorKey]?'<br><br><span style="color:#d0c8b8"> 壁をよく調べると……何かありそうだ。</span>':''}
    ${darkWarn}`;
  }

  case 'event':{
   const ev = DUNGEON_EVENTS[node.eventIdx] || DUNGEON_EVENTS[0];
   const done = PC[node.eventKey];
   return `${tBar}${fLabel}<br><br>
    <span style="color:#b8a890">${node.atm||ydStyleAtm(design)}</span><br><br>
    ${!done
     ? `<div style="border-top:1px solid var(--info-border);margin-top:8px;padding-top:8px"><span style="color:#ece8e0">${ev.icon} <b>${ev.title}</b></span><br><span style="color:var(--white2);font-size:var(--font-sm)">${ev.desc}</span></div>`
     : '<span style="color:#b0a080">（このイベントは終了した）</span>'}
    ${darkWarn}`;
  }

  case 'village_forage':{
   const done = PC[node.forageKey];
   return `${tBar}${fLabel}<br><br>
    <span style="color:#b8a890">${node.atm || _rdungPick(villageCfg(dung).flavor.forage)}</span>
    ${!done ? '<br><br><span style="color:#ece8e0"> 何か見つかりそうだ。</span>' : '<br><br><span style="color:#b0a080">（探索済み）</span>'}
    ${darkWarn}`;
  }

  case 'village_delivery':{
   const dq = PC._villageBackalleyDelivery;
   const done = PC[node.deliveryKey];
   const dqText = dq
    ? `路地の奥に、それらしき人影がある。<b>${dq.recipient}</b>だろうか。預かった<b>${dq.item}</b>を届けられそうだ。`
    : '特に何もない、静かな路地だ。';
   return `${tBar}${fLabel}<br><br>
    <span style="color:#b8a890">${!done ? dqText : '（届け物はもう済ませた）'}</span>
    ${darkWarn}`;
  }

  case 'bounty_hideout':{
   const bq = (PC.quests||[]).find(qq=>qq.id===node.bountyQuestId);
   const done = PC[node.hideoutKey];
   const bhText = bq
    ? `住民への聞き込みの末、目立たない扉に行き着いた。<b>${bq.targetNPC?.name||bq.targetName}</b>（${bq.targetTitle||'賞金首'}）のアジトはここだろうか。扉の向こうに気配がある。`
    : '特に何もない、静かな路地だ。';
   return `${tBar}${fLabel}<br><br>
    <span style="color:#f0ddd8">${!done ? bhText : '（アジトはもぬけの殻だった）'}</span>
    ${darkWarn}`;
  }

  case 'hideout_boss':{
   const bq = (PC.quests||[]).find(qq=>qq.id===node.bountyQuestId);
   const done = PC[node.bossKey];
   const bossText = bq
    ? `奥まった部屋に辿り着いた。<b>${bq.targetNPC?.name||bq.targetName}</b>（${bq.targetTitle||'賞金首'}）がこちらに気づき、身構えている。手下たちも周囲を固めていた。`
    : '奥まった部屋には、もう誰もいないようだ。';
   return `${tBar}${fLabel}<br><br>
    <span style="color:#f0ddd8">${!done ? bossText : '（この部屋はもう片付けた）'}</span>`;
  }

  case 'local_wanted':{
   const board = getLocalWantedBoard(dung.villageId);
   const target = board.targets.find(t=>t.id===node.wantedTargetId);
   const done = PC[node.wantedKey];
   const wtText = target
    ? `路地の奥に、手配書と似た人相の男が潜んでいる。<b>${target.name}</b>——${target.desc}だろうか。手配書の顔とよく似ている。`
    : '特に何もない、静かな路地だ。';
   return `${tBar}${fLabel}<br><br>
    <span style="color:#b8a890">${!done ? wtText : '（この場所はもう調べた）'}</span>
    ${darkWarn}`;
  }

  case 'town_mini_resolve':{
   const mdef = TOWN_MINI_QUEST_TYPES.find(d=>d.subtype===node.miniSubtype);
   const done = PC[node.miniResolveKey];
   // 既にノードが生成済みでnpcNameを持っていない場合（機能追加前に生成されたノード等）は、
   // 表示のタイミングで掲示板から名前を補う。それでも見つからなければ汎用の呼び方に逃がす
   if(mdef && !node.npcName && node.miniSubtype==='message' && dung?.villageId){
    const miniBoard = getLocalWantedBoard(dung.villageId);
    const notice = (miniBoard?.notices||[]).find(n=>n.resolveType==='message' && n.npcName);
    if(notice) node.npcName = notice.npcName;
   }
   // 「噂の真偽を確かめてほしい」は、掲示板に貼られている実際の噂の内容を併記する
   // （node.rumorIdで、今週複数の噂が同時に貼られていても対応する1件を正しく特定する。
   //   rumorIdを持たない旧ノード（機能追加前に生成されたもの）は、従来通り先頭の噂で代用する）
   let rumorText = '';
   if(mdef && node.miniSubtype==='rumor' && dung?.villageId){
    const miniBoard = getLocalWantedBoard(dung.villageId);
    const notice = node.rumorId
     ? (miniBoard?.notices||[]).find(n=>n.resolveType==='rumor' && n.rumorId===node.rumorId)
     : (miniBoard?.notices||[]).find(n=>n.resolveType==='rumor');
    if(notice) rumorText = notice.heardAtTavern
     ? `<br><br><span style="color:#c8b8a0;font-size:calc(var(--font-sm) - 1px)">（酒場で聞いた、あの噂だ──${notice.text}）</span>`
     : `<br><br><span style="color:#c8b8a0;font-size:calc(var(--font-sm) - 1px)">（掲示板の貼り紙にあった、あの噂だ──${notice.text}）</span>`;
   }
   const mtText = mdef ? mdef.findFlavor.replace(/\{name\}/g, node.npcName || 'その人物') : '特に何もない、静かな場所だ。';
   return `${tBar}${fLabel}<br><br>
    <span style="color:#b8a890">${!done ? mtText + rumorText : '（もう解決した）'}</span>
    ${darkWarn}`;
  }

  case 'village_incident':{
   const ev = villageCfg(dung).incidents.find(e=>e.id===node.incidentId) || villageCfg(dung).incidents[0];
   const done = PC[node.eventKey];
   const flavorTxt = (node.npcName ? ev.flavor.replace(/\{name\}/g, node.npcName) : ev.flavor).replace(/\{hero\}/g, PC.name);
   const titleTxt = node.npcName ? `${ev.title}「${node.npcName}」` : ev.title;
   return `${tBar}${fLabel}<br><br>
    <span style="color:#e0d8c8">${titleTxt}</span><br><br>
    <span style="color:#e8e0d0">${!done ? flavorTxt : '（この出来事は解決した）'}</span>
    ${darkWarn}`;
  }

  case 'stair_landing':{
   const landingAtms = [
    '階段を降りてきた踊り場だ。天井が低く、壁の石組みが一段深くなったことを示している。',
    '階段の踊り場に出た。ここから先は別の層だ。空気の質が変わり、臭いも少し違う。',
    '段を降りた先の踊り場だ。床の石が上の層と色が違う。より古い時代に作られた部分に入ったらしい。',
    '踊り場の壁に、層の境目を示すような溝が一周ぐるりと刻まれている。',
    '狭い踊り場に立つと、上からも下からも等しく冷たい風が吹いてくる。',
    '踊り場の床に、ここより先へ進んだ者たちの靴跡が幾重にも重なっている。',
   ];
   const txt = node.landingDesc || landingAtms[Math.floor(Math.random()*landingAtms.length)];
   return `${tBar}${fLabel}<br><br>
    <span style="color:#b8a890">${txt}</span>
    ${darkWarn}`;
  }

  default:
   return `${tBar}${fLabel}<br><br><span style="color:#d0c8b8">（不明なノード: ${node.type}）</span>`;
 }
}

// 部屋の内容テキスト
function ydRoomContentTxt(node){
 const monsterDefeated = node.monsterKey && PC[node.monsterKey];
 const dung = PC._yeldunDungeon;
 const isVillage = dung?.isVillageBackAlley;
 const cfg = isVillage ? villageCfg(dung) : null;
 switch(node.roomContent){
  case 'empty': return isVillage ? '<span style="color:#d0c8b8">特に何もない、静かな場所だ。</span>' : '<span style="color:#d0c8b8">空の部屋だ。</span>';
  case 'monster':
   if(monsterDefeated) return isVillage ? '<span style="color:#b0a080">静寂が戻ったこの場所は今は静かだ。</span>' : '<span style="color:#b0a080">静寂が戻った部屋だ。</span>';
   return `<span style="color:#f0ddd8"> <b>${node.monster?.name}</b>が<b>${node.monster?.count}体</b>いる！</span>`;
  case 'monster_treasure':
   if(monsterDefeated) return isVillage ? '<span style="color:#b0a080">何かを倒した後の静かな場所だ。</span>' : '<span style="color:#b0a080">モンスターを倒した後の部屋だ。</span>';
   return `<span style="color:#f0ddd8"> <b>${node.monster?.name}</b>が<b>${node.monster?.count}体</b>いる！何かも落ちている。</span>`;

  case 'statue': return `<span style="color:#c8b8a0">${cfg?.flavor?.roomText?.statue || (isVillage ? '苔むした古い石の祠がある。触れると何か起きるかもしれない。' : '不思議な石像がある。触れると何か起きるかもしれない。')}</span>`;
  case 'fountain': return `<span style="color:#ece8e0">${cfg?.flavor?.roomText?.fountain || (isVillage ? '澄んだ湧き水が湧き出ている。飲むと何か起きるかもしれない。' : '魔法の泉がある。飲むと何か起きるかもしれない。')}</span>`;
  case 'chest':
   if(node.roomKey && PC[node.roomKey+'_loot']) return `<span style="color:#d0c8b8">${isVillage ? '中身を取り出した後の、空の木箱がある。' : '開けた後の、空の宝箱がある。'}</span>`;
   return `<span style="color:#f0ece0">${cfg?.flavor?.roomText?.chest || (isVillage ? '誰かが隠したらしい木箱がある。' : '宝箱がある。')}</span>`;
  case 'wandering_party': return '<span style="color:#ffcc88">人の気配がする……</span>';
  default: return '';
 }
}

