   holders:'壁の燭台は空だ。かつてここで弔いの炎を灯した者たちは、今はここに眠っている。',
   torches:'腐りかけた松明がまだ燃えている。この墓所に最近も誰かが訪れた証拠だ——あるいは、中の者たちが灯したのかもしれない。',
   braziers:'霊廟を照らすために設えられた永遠の炎が、今も揺れている。その炎は温かくなく、むしろ骨の芯まで冷える光だ。',
   luminous:'骨に宿った死者の魂が青白い光となって滲み出し、通路を照らしている。美しいとすら言えるが、それが死の光だと気づいたとき、足がすくんだ。',
