// 討伐クエスト生成
// ══════════════════════════════════════════
//  賞金首討伐依頼システム
// ══════════════════════════════════════════

// 賞金首依頼生成
// ── 裏依頼：暗殺・誘拐・密売の対象一覧（賞金首と同じ町プールを使う） ──
const _CRIME_QUEST_TOWNS = ['khazan','port_argon','stonehiem','elsia','verda','rimholm','marakai',
 'al_rashid','oasis_fort','saroon','duna','yeldun','frostpeak','ashveil',
 'valdheim','nifurvik','iskald','neria','dorua','sarpe','nebra','kalvo'];

// ① 暗殺依頼：賞金首と同じ生成方式・同じ報酬額。完了で対象の町の手配度+5（信頼度は変化なし）、混沌/悪よりに
function generateAssassinationQuest(fromTownId){
 const level = 3 + Math.floor(Math.random()*8); // 3〜10
 const npc = generateNPC(level);
 const titles = ['豪商','町の名士','引退した傭兵隊長','神殿の高位聖職者','裏社会の顔役','地方領主の縁者','ギルドの幹部','旅の学者'];
 const title = titles[Math.floor(Math.random()*titles.length)];
 npc.bountyTitle = title;
 const otherTowns = _CRIME_QUEST_TOWNS.filter(t=>t!==fromTownId);
 const targetTownId = Math.random()<0.5
  ? otherTowns[Math.floor(Math.random()*otherTowns.length)]
  : fromTownId;
 const isCrossRegion = getRegionKey(targetTownId) !== getRegionKey(fromTownId);
 const rewardBase = isCrossRegion
  ? level * (70 + Math.floor(Math.random()*31))
  : level * (40 + Math.floor(Math.random()*21));
 const deadline = isCrossRegion ? 360 : 20 + level * 3;
 const targetTownName = (TOWNS[targetTownId]||{name:targetTownId}).name;
 return {
  id: Date.now() + Math.random(),
  type: 'assassination',
  status: 'active',
  fromTownId,
  targetTownId,
  targetTownName,
  isCrossRegion,
  targetName: npc.name,
  targetTitle: title,
  targetLevel: level,
  targetNPC: npc,
  reward: rewardBase,
  deadlineDays: deadline,
  issuedDay: GAME_TIME.totalDays,
  clientName: '裏の仲介人',
  _defeated: false,
 };
}

// ② 誘拐依頼：対象は民間人・戦闘なし（STテスト）。完了で対象の町の手配度+3（信頼度は変化なし）、混沌/悪よりに
function generateKidnappingQuest(fromTownId){
 const level = 2 + Math.floor(Math.random()*6); // 2〜7（民間人なのでやや低め）
 const npc = generateNPC(level);
 const titles = ['商家の子女','裕福な商人の妻','町の有力者の息子','旅の貴族令嬢','資産家の跡取り'];
 const title = titles[Math.floor(Math.random()*titles.length)];
 npc.bountyTitle = title;
 const otherTowns = _CRIME_QUEST_TOWNS.filter(t=>t!==fromTownId);
 const targetTownId = Math.random()<0.5
  ? otherTowns[Math.floor(Math.random()*otherTowns.length)]
  : fromTownId;
 const isCrossRegion = getRegionKey(targetTownId) !== getRegionKey(fromTownId);
 const rewardBase = isCrossRegion
  ? level * (60 + Math.floor(Math.random()*21))
  : level * (35 + Math.floor(Math.random()*16));
 const deadline = isCrossRegion ? 360 : 20 + level * 3;
 const targetTownName = (TOWNS[targetTownId]||{name:targetTownId}).name;
 return {
  id: Date.now() + Math.random(),
  type: 'kidnapping',
  status: 'active',
  fromTownId,
  targetTownId,
  targetTownName,
  isCrossRegion,
  targetName: npc.name,
  targetTitle: title,
  targetLevel: level,
  targetNPC: npc,
  reward: rewardBase,
  deadlineDays: deadline,
  issuedDay: GAME_TIME.totalDays,
  clientName: '正体不明の依頼人',
  _defeated: false,
 };
}

// ③ 麻薬・盗品の配達：宅配と同じロジック、報酬1.5倍。完了で届け先の町の手配度+0.5（信頼度は変化なし）、混沌/悪よりに
const CONTRABAND_ITEMS = ['怪しげな薬包','出所不明の宝飾品','封蝋された小箱','盗品と思しき壺','違法な秘薬','闇市場の粉薬'];
function generateContrabandQuest(fromTownId){
 const regionTowns = getRegionTowns(fromTownId);
 const otherTowns = regionTowns.filter(id=>id!==fromTownId);
 const reachable = otherTowns.filter(id=>calcMinTravelDays(fromTownId,id)!=null);
 const candidates = reachable.length > 0 ? reachable : Object.keys(TOWNS).filter(id=>id!==fromTownId && getRegionKey(id)===getRegionKey(fromTownId));
 const toTownId = candidates[Math.floor(Math.random()*candidates.length)];
 const item = CONTRABAND_ITEMS[Math.floor(Math.random()*CONTRABAND_ITEMS.length)];
 const clientName = pickNPC();
 const receiverName = pickNPC([clientName]);
 const reward = Math.round(calcQuestReward(fromTownId, toTownId) * 2);
 const deadlineDays = calcQuestDeadline(fromTownId, toTownId);
 return {
  id: Date.now() + Math.random(),
  type: 'contraband',
  fromTownId, toTownId,
  item, clientName, receiverName,
  reward, deadlineDays,
  issuedDay: GAME_TIME.totalDays,
  status: 'active',
  crossRegion: false,
 };
}

