// ══════════════════════════════════════════
// 「噂の真偽」の一部は、汎用の成功処理の代わりに専用イベントへ接続する（rumorId → ハンドラ関数）
// ここに無いrumorId（strange_light／smuggling／hero_treasure）は、従来通りTOWN_MINI_QUEST_TYPESの
// 汎用フローで解決される。
// ハンドラは (node, floor, dung, reward) を受け取り、{label, fn}の配列を返すこと（ch.push(...)で展開される）。
// ══════════════════════════════════════════

// 「墓地の唸り声」：探索を終える（達成扱い・謝礼SPと信頼度あり）
function _finishGraveyardMoanRumor(node, floor, dung, reward, resultText){
 PC[node.miniResolveKey] = true;
 gainSP(reward);
 changeTrust(dung.villageId, 0.1);
 const miniBoard = getLocalWantedBoard(dung.villageId);
 if(miniBoard){
  miniBoard.resolvedMiniTypes = miniBoard.resolvedMiniTypes || [];
  if(!miniBoard.resolvedMiniTypes.includes(node.miniSubtype)) miniBoard.resolvedMiniTypes.push(node.miniSubtype);
 }
 updateHUD();
 const s = document.getElementById('story');
 if(s) s.innerHTML = `<span style="color:#e0d0d0">${(TOWNS[dung.villageId]||{}).name || dung.villageId}</span><br><br><span style="color:#e8e0d0">${resultText}（謝礼${reward}SP／信頼度+0.1）</span>`;
 renderChoices([{label:'▶ OK', fn:()=>ydGoNode(node.id, floor)}]);
}

// 「墓地の唸り声」：何も得られずに探索を終える（達成扱いのみ・報酬なし）
function _failGraveyardMoanRumor(node, floor, failMsg){
 PC[node.miniResolveKey] = true;
 const s = document.getElementById('story');
 if(s) s.innerHTML += `<br><br><span style="color:#c8b8a0">${failMsg}</span>`;
 renderChoices([{label:'▶ OK', fn:()=>ydGoNode(node.id, floor)}]);
}

// 「墓地の唸り声」：深夜の墓地で、封印の解かれた塚を発見する
function _graveyardMoanScene(node, floor, dung, reward){
 const s = document.getElementById('story');
 const townName = (TOWNS[dung.villageId]||{}).name || dung.villageId;
 if(s) s.innerHTML = `<span style="color:#e0d0d0">${townName}　墓地（深夜）</span><br><br><span style="color:#e8e0d0">月明かりだけを頼りに、静まり返った墓地を見回る。すると、墓地の外れにある古い塚の入口の封印が解かれているのに気づいた。中からは、奇妙な赤い光が漏れている。</span>`;
 renderChoices([
  {label:' 中を調べる', fn:()=>_graveyardMoanEnterTomb(node, floor, dung, reward)},
  {label:' 放っておく', fn:()=>_finishGraveyardMoanRumor(node, floor, dung, reward, '得体の知れない気配に、これ以上は関わらない方がいいと判断した。夜が明ける頃、中央広場へと戻った。')},
 ]);
}

// 「墓地の唸り声」の塚に出現するゾンビ（NPC能力値型）
// 能力値は「通常の人間を1」とした係数で算出する：ST×2 IQ×0 LK×0 CON×3 DEX×1/2 CHR×0（SPDは等倍）
function _generateZombieNpc(){
 const base = {
  st:  rollNPCStat(8), iq: rollNPCStat(8), lk:  rollNPCStat(8),
  con: rollNPCStat(8), dex:rollNPCStat(8), chr: rollNPCStat(8), spd: rollNPCStat(8),
 };
 const mods = { st:2, iq:0, lk:0, con:3, dex:0.5, chr:0, spd:1 };
 const st  = Math.round(base.st  * mods.st);
 const iq  = Math.round(base.iq  * mods.iq);
 const lk  = Math.round(base.lk  * mods.lk);
 const con = Math.round(base.con * mods.con);
 const dex = Math.round(base.dex * mods.dex);
 const chr = Math.round(base.chr * mods.chr);
 const spd = Math.round(base.spd * mods.spd);
 return {
  name:'ゾンビ', race:'zombie', type:'undead',
  st, iq, lk, con, maxCon:con, curCon:con, dex, chr, spd,
  equippedWeapons:[{name:'腐った爪', dice:3, adds:2, twoHand:false}],
  equippedArmors:[],
 };
}

// 「墓地の唸り声」：塚の中に踏み込む（描写ノード。ここではまだ戦闘は始まらない）
function _graveyardMoanEnterTomb(node, floor, dung, reward){
 const s = document.getElementById('story');
 if(s) s.innerHTML = `<span style="color:#e0d0d0">塚の中</span><br><br><span style="color:#e8e0d0">封印を越えて中に踏み込むと、そこは直径10mほどの石室だった。禍々しい魔法使いが、操られたゾンビをはべらせてこちらを見据えている。逃げ場はない――戦うしかなさそうだ。</span>`;
 renderChoices([
  {label:'▶ 進む', fn:()=>_graveyardMoanTombCombat(node, floor, dung, reward)},
 ]);
}

// 「墓地の唸り声」：塚の描写ノードの後、LV3魔法使い（NPC能力値型）とゾンビ（NPC能力値型）との戦闘になる
function _graveyardMoanTombCombat(node, floor, dung, reward){
 renderChoices([]);
 scrollToTop();
 const mage = generateNPC(3);
 mage.type = 'wizard';
 mage.name = '怪しげな魔法使い';
 let spells = SPELLS_L1.map(sp=>({...sp}));
 for(let lv=2; lv<=3; lv++){ const table=SPELL_LEVEL_TABLES[lv]; if(table) spells = spells.concat(table.map(sp=>({...sp}))); }
 mage.spells = spells;
 mage.equippedWeapons = [];
 mage.invWeapons = [];
 mage.curCon = mage.con;
 const zombie = _generateZombieNpc();
 startCombatNPC({
  enemies:[mage, zombie],
  canFlee:false,
  win:'__noop__', lose:'DEAD',
  autoTreasure:true,
  onWin:()=>{
   PC[node.miniResolveKey] = true;
   changeTrust(dung.villageId, 5);
   _queueTavernThanks(node, dung, 'solved');
   const miniBoard = getLocalWantedBoard(dung.villageId);
   if(miniBoard){
    miniBoard.resolvedMiniTypes = miniBoard.resolvedMiniTypes || [];
    if(!miniBoard.resolvedMiniTypes.includes(node.miniSubtype)) miniBoard.resolvedMiniTypes.push(node.miniSubtype);
   }
   updateHUD();
   const s2 = document.getElementById('story');
   if(s2) s2.innerHTML = `<span style="color:#f0ece0">塚の主を討伐した</span><br><br><span style="color:#e8e4d8">魔法使いとゾンビを倒し、石室を調べ終えた。（信頼度+5）</span>`;
   renderChoices([{label:'▶ OK', fn:()=>ydGoNode(node.id, floor)}]);
  },
 });
}

// 「墓地の唸り声」：3択（CHR／IQ／LK）の入口
function _graveyardMoanInvestigateChoices(node, floor, dung, reward){
 return [
  {label:' 世間話のふりで聞き出す', fn:()=>{
   setupSavingRoll({attr:'chr', level:1,
    onSuccess:()=>{
     const s = document.getElementById('story');
     if(s) s.innerHTML += `<br><br><span style="color:#e8e0d0">世間話のふりをして、墓地のどのあたりで唸り声を聞いたのか、詳細をうまく聞き出せた。</span>`;
     renderChoices([
      {label:' 夜まで待って墓地を調べる', fn:()=>{
       const cur = getGameHour();
       const target = 20;
       const delta = ((target - cur) % 24 + 24) % 24 || 24;
       if(advanceVillageTime(delta*60)) return;
       _graveyardMoanScene(node, floor, dung, reward);
      }},
      {label:' 放っておく', fn:()=>_finishGraveyardMoanRumor(node, floor, dung, reward, '気にはなったが、深追いはせずそのままにしておくことにした。')},
     ]);
    },
    onFail:()=>_failGraveyardMoanRumor(node, floor, '口が堅く、何も聞き出せなかった。'),
   });
  }},
  {label:' 話に怪しいところがないか確認する', fn:()=>{
   setupSavingRoll({attr:'iq', level:1,
    onSuccess:()=>{ _queueTavernThanks(node, dung, 'debunked'); _finishGraveyardMoanRumor(node, floor, dung, reward, '話の矛盾点を突くと、噂は嘘の情報であることが分かった。'); },
    onFail:()=>_failGraveyardMoanRumor(node, floor, '話術で丸め込まれてしまった。'),
   });
  }},
  {label:' 現場に直接乗り込む', fn:()=>{
   setupSavingRoll({attr:'lk', level:1,
    onSuccess:()=>_graveyardMoanScene(node, floor, dung, reward),
    onFail:()=>{
     if(advanceVillageTime(24*60)) return;
     _failGraveyardMoanRumor(node, floor, '一晩中墓地を見張ることにしたが、何も起こらなかった。');
    },
   });
  }},
 ];
}

