// 「商家の密輸」：商家ノード（商人を脅す／密輸品を買う）
function _smugglingMerchantNode(node, floor, dung, reward, merchantName){
 const s = document.getElementById('story');
 if(s) s.innerHTML = `<span style="color:#e0d0d0">商家</span><br><br><span style="color:#e8e0d0">商人${merchantName}が密かに密輸品を扱っていることが分かった。訪ねてみると、そこは壁一面に異国の調度品が並ぶ、裕福な商家だった。${merchantName}は愛想笑いを浮かべながらも、どこか値踏みするような目でこちらを見ている。</span>`;
 renderChoices([
  {label:' 商人を脅す', fn:()=>_smugglingThreatenMerchant(node, floor, dung, merchantName)},
  {label:' 商人から密輸品を買う', fn:()=>_smugglingBuyGoods(node, floor, dung, merchantName)},
 ]);
}

// 「商家の密輸」：商人を脅す（CHR Lv2）。失敗すると用心棒（LV3 NPC戦士×3）との戦闘になる
function _smugglingThreatenMerchant(node, floor, dung, merchantName){
 setupSavingRoll({attr:'chr', level:2,
  onSuccess:()=>{
   gainGP(100);
   updateHUD();
   _finishSmugglingResolved(node, floor, dung, `${merchantName}を脅し、口止め料として100GPを受け取った。`);
  },
  onFail:()=>{
   const s = document.getElementById('story');
   if(s) s.innerHTML += `<br><br><span style="color:#c8b8a0">${merchantName}は顔色一つ変えず、代わりに用心棒たちを呼び寄せた。</span>`;
   renderChoices([]);
   scrollToTop();
   const bodyguards = Array.from({length:3}, ()=>{
    const g = generateNPC(3);
    g.type = 'warrior';
    g.name = '用心棒';
    g.equippedWeapons = [{name:'ブロードソード',dice:3,adds:4,twoHand:false,weight:120,stReq:15,dexReq:10}];
    g.invWeapons = [];
    g.spells = [];
    g.curCon = g.con;
    return g;
   });
   startCombatNPC({
    enemies:bodyguards,
    canFlee:false,
    win:'__noop__', lose:'DEAD',
    onWin:()=>{
     gainGP(100);
     updateHUD();
     _finishSmugglingResolved(node, floor, dung, `用心棒たちを退けると、${merchantName}は観念して口止め料として100GPを差し出した。`);
    },
   });
  },
 });
}

// 「商家の密輸」：商人から密輸品を買う（他地方の特産品を産地価格で購入できる）
function _smugglingBuyGoods(node, floor, dung, merchantName){
 const ownRegion = getRegionKey(dung.villageId);
 const regionKeys = Object.keys(REGION_SPECIALTIES).filter(k=>k!==ownRegion);
 const pickRegion = regionKeys[Math.floor(Math.random()*regionKeys.length)] || Object.keys(REGION_SPECIALTIES)[0];
 const pool = (REGION_SPECIALTIES[pickRegion]||[]).slice();
 const count = Math.min(pool.length, 1+Math.floor(Math.random()*3));
 const items = pool.sort(()=>Math.random()-0.5).slice(0, count);
 const s = document.getElementById('story');
 if(s) s.innerHTML += `<br><br><span style="color:#e8e0d0">${merchantName}は声を潜め、奥から他地方の品をいくつか取り出して見せた。「産地と変わらない値でいいですよ」</span>`;
 const choices = items.map(it=>{
  const price = calcSpecialtyBuyPrice(it);
  return {label:`${it.icon} ${it.name}（${price}GP）`, fn:()=>{
   if(totalCP() < price*100){ showSaveToast('所持金が足りない'); return; }
   payPrice(price);
   PC.invSpecialties = PC.invSpecialties||[];
   PC.invSpecialties.push({name:it.name, icon:it.icon, regionKey:pickRegion, baseCost:it.baseCost, weight:it.weight, boughtAt:price});
   updateHUD();
   _finishSmugglingResolved(node, floor, dung, `${it.icon}${it.name}を産地と変わらぬ値、${price}GPで手に入れた。`);
  }};
 });
 choices.push({label:' 何も買わずに帰る', fn:()=>_finishSmugglingResolved(node, floor, dung, '結局、何も買わずに商家を後にした。')});
 renderChoices(choices);
}

// 「商家の密輸」：この噂（掲示板の貼り紙）に紐づく商人名を取得する。
// 貼り紙生成時にnotice.merchantNameとして確定済みのものを使い、聞き込みの手段や遭遇のたびに
// 名前がバラバラにならないようにする（掲示板が見つからない場合のみ、その場限りの名前を振る）
function _smugglingGetMerchantName(node, dung){
 const miniBoard = getLocalWantedBoard(dung.villageId);
 const notice = (miniBoard?.notices||[]).find(n=>n && typeof n==='object' && n.resolveType==='rumor' && n.rumorId===node.rumorId);
 return (notice && notice.merchantName) || NPC_NAMES[Math.floor(Math.random()*NPC_NAMES.length)];
}

// 「商家の密輸」：3択（CHR／IQ／LK）の入口
function _smugglingInvestigateChoices(node, floor, dung, reward){
 return [
  {label:' 世間話のふりで聞き出す', fn:()=>{
   setupSavingRoll({attr:'chr', level:1,
    onSuccess:()=>{
     const merchantName = _smugglingGetMerchantName(node, dung);
     const s = document.getElementById('story');
     if(s) s.innerHTML += `<br><br><span style="color:#e8e0d0">世間話のふりをして、詳細な情報をうまく聞き出せた。商人の${merchantName}が裏で密輸品を扱っているようだ。</span>`;
     renderChoices([
      {label:' 衛兵に密告する', fn:()=>{ _queueTavernThanks(node, dung, 'solved'); _finishSmugglingRumor(node, floor, dung, reward, `衛兵に密告すると、後日${merchantName}は取り調べを受け、捕らえられたという知らせが届いた。`); }},
      {label:' 商家に行く', fn:()=>_smugglingMerchantNode(node, floor, dung, reward, merchantName)},
      {label:' 放っておく', fn:()=>_finishSmugglingRumor(node, floor, dung, reward, '気にはなったが、深追いはせずそのままにしておくことにした。')},
     ]);
    },
    onFail:()=>_failSmugglingRumor(node, floor, '口が堅く、何も聞き出せなかった。'),
   });
  }},
  {label:' 話に怪しいところがないか確認する', fn:()=>{
   setupSavingRoll({attr:'iq', level:1,
    onSuccess:()=>{ _queueTavernThanks(node, dung, 'debunked'); _finishSmugglingRumor(node, floor, dung, reward, '話の矛盾点を突くと、噂は嘘の情報であることが分かった。'); },
    onFail:()=>_failSmugglingRumor(node, floor, '話術で丸め込まれてしまった。'),
   });
  }},
  {label:' 商人街を見張る', fn:()=>{
   setupSavingRoll({attr:'lk', level:3,
    onSuccess:()=>{
     const merchantName = _smugglingGetMerchantName(node, dung);
     _smugglingMerchantNode(node, floor, dung, reward, merchantName);
    },
    onFail:()=>{
     if(advanceVillageTime(24*60)) return;
     _failSmugglingRumor(node, floor, '一日中商人街を見張ることにしたが、何も起こらなかった。');
    },
   });
  }},
 ];
}

