// 「先代の英雄のお宝」：墓地で正体不明の人物の塚を発見する
function _heroTreasureTombScene(node, floor, dung, reward){
 const s = document.getElementById('story');
 const townName = (TOWNS[dung.villageId]||{}).name || dung.villageId;
 if(s) s.innerHTML = `<span style="color:#e0d0d0">${townName}　墓地</span><br><br><span style="color:#e8e0d0">静まり返った墓地を歩き回ると、中央寄りに、由来の分からない古い塚があるのに気づいた。噂通り、この下に先代の英雄が遺したお宝が眠っているのかもしれない。塚の封印は既に解かれており、内部からは松明の光が漏れている。</span>`;
 renderChoices([
  {label:' 中を調べる', fn:()=>_heroTreasureEnterTomb(node, floor, dung, reward)},
  {label:' 放っておく', fn:()=>_finishHeroTreasureRumor(node, floor, dung, reward, '気にはなったが、深追いはせず、中央広場へと戻った。')},
 ]);
}

// 「先代の英雄のお宝」：塚の中に踏み込む（描写ノード。ここではまだ戦闘は始まらない）
function _heroTreasureEnterTomb(node, floor, dung, reward){
 const s = document.getElementById('story');
 if(s) s.innerHTML = `<span style="color:#e0d0d0">塚の中</span><br><br><span style="color:#e8e0d0">封印を越えて中に踏み込むと、そこは直径10mほどの石室だった。先客と思しき一団が、ちょうど宝箱を開けようとしているところだ。こちらに気づくと、一斉に武器を構えた。</span>`;
 renderChoices([
  {label:'▶ 進む', fn:()=>_heroTreasureTombCombat(node, floor, dung, reward)},
 ]);
}

// 「先代の英雄のお宝」：塚の描写ノードの後、LV3NPCパーティ（×4）との戦闘になる。勝利すれば標準の宝物作成表×2を入手
function _heroTreasureTombCombat(node, floor, dung, reward){
 renderChoices([]);
 scrollToTop();
 const party = Array.from({length:4}, ()=>{
  const p = generateNPC(3);
  p.type = 'warrior';
  p.name = '墓荒らし';
  p.curCon = p.con;
  return p;
 });
 const totalPower = party.reduce((s,e)=>s+((e.st||10)+(e.lk||10)+(e.dex||10)),0);
 startCombatNPC({
  enemies:party,
  canFlee:false,
  win:'__noop__', lose:'DEAD',
  onWin:()=>{
   PC[node.miniResolveKey] = true;
   _queueTavernThanks(node, dung, 'solved');
   const miniBoard = getLocalWantedBoard(dung.villageId);
   if(miniBoard){
    miniBoard.resolvedMiniTypes = miniBoard.resolvedMiniTypes || [];
    if(!miniBoard.resolvedMiniTypes.includes(node.miniSubtype)) miniBoard.resolvedMiniTypes.push(node.miniSubtype);
   }
   const loot1 = generateTreasure(totalPower);
   const loot2 = generateTreasure(totalPower);
   updateHUD();
   const s2 = document.getElementById('story');
   if(s2) s2.innerHTML = `<span style="color:#f0ece0">塚の先客を退けた</span><br><br><span style="color:#e8e4d8">墓荒らしたちを倒し、宝箱の中身を手に入れた。（${loot1}／${loot2}）</span>`;
   renderChoices([{label:'▶ OK', fn:()=>ydGoNode(node.id, floor)}]);
  },
 });
}

