// 「町外れの奇妙な光」：探索を終える（達成扱い・謝礼SPと信頼度あり）
function _finishStrangeLightRumor(node, floor, dung, reward, resultText){
 PC[node.miniResolveKey] = true;
 gainSP(reward);
 changeTrust(dung.villageId, 0.1);
 const miniBoard = getLocalWantedBoard(dung.villageId);
 if(miniBoard){
  miniBoard.resolvedMiniTypes = miniBoard.resolvedMiniTypes || [];
  if(!miniBoard.resolvedMiniTypes.includes(node.miniSubtype)) miniBoard.resolvedMiniTypes.push(node.miniSubtype);
 }
 updateHUD();
 const s = document.getElementById('story');
 if(s) s.innerHTML = `<span style="color:#e0d0d0">${(TOWNS[dung.villageId]||{}).name || dung.villageId}</span><br><br><span style="color:#e8e0d0">${resultText}（謝礼${reward}SP／信頼度+0.1）</span>`;
 renderChoices([{label:'▶ OK', fn:()=>ydGoNode(node.id, floor)}]);
}

