// 「町外れの奇妙な光」：廃屋の描写ノードの後、LV5魔法使い（NPC能力値型・LV5魔法まで使用可能）との戦闘になる
// 勝利すれば生贄になりかけたNPC（victimName、描写ノードと同一人物）を助け出し、街へ連れ帰って報奨金300GPを得る
function _strangeLightCombat(node, floor, dung, reward, victimName){
 renderChoices([]);
 scrollToTop();
 const rescuedName = victimName || NPC_NAMES[Math.floor(Math.random()*NPC_NAMES.length)];
 const wizard = generateNPC(5);
 wizard.type = 'wizard';
 wizard.name = '正気を失った魔法使い';
 let spells = SPELLS_L1.map(sp=>({...sp}));
 for(let lv=2; lv<=5; lv++){ const table=SPELL_LEVEL_TABLES[lv]; if(table) spells = spells.concat(table.map(sp=>({...sp}))); }
 wizard.spells = spells;
 wizard.equippedWeapons = [];
 wizard.invWeapons = [];
 wizard.st = Math.max(wizard.st, 30); // Lv5魔法（強さ-10）を安定して唱えられるだけの強さを保証
 wizard.curCon = wizard.con;
 startCombatNPC({
  enemies:[wizard],
  canFlee:false,
  win:'__noop__', lose:'DEAD',
  onWin:()=>{
   PC[node.miniResolveKey] = true;
   changeTrust(dung.villageId, 5);
   _queueTavernThanks(node, dung, 'solved');
   const miniBoard = getLocalWantedBoard(dung.villageId);
   if(miniBoard){
    miniBoard.resolvedMiniTypes = miniBoard.resolvedMiniTypes || [];
    if(!miniBoard.resolvedMiniTypes.includes(node.miniSubtype)) miniBoard.resolvedMiniTypes.push(node.miniSubtype);
   }
   gainGP(300);
   updateHUD();
   const s2 = document.getElementById('story');
   if(s2) s2.innerHTML = `<span style="color:#f0ece0">魔法使いを討伐した</span><br><br><span style="color:#e8e4d8">魔法使いを倒し、生贄になりかけていた${rescuedName}を助け出した。街へと連れ帰ると、報奨金として300GPを受け取った。（信頼度+5）</span>`;
   renderChoices([{label:'▶ OK', fn:()=>ydGoNode(node.id, floor)}]);
  },
 });
}

