// 酒場で聞いた噂：最初の聞き込み（CHR判定）を省略し、現場へ向かう選択肢から始める
// 3択の先頭（聞き込み）を、聞き込み成功後の選択肢に置き換える。2・3番目（矛盾点を突く／乗り込む等）は従来どおり
function _tavernHeardEntryChoices(node, floor, dung, reward, original){
 const rest = original.slice(1);
 let head;
 switch(node.rumorId){
  case 'graveyard_moan':
   head = [
    {label:' 夜まで待って墓地を調べる', fn:()=>{
     const cur = getGameHour();
     const delta = ((20 - cur) % 24 + 24) % 24 || 24;
     if(advanceVillageTime(delta*60)) return;
     _graveyardMoanScene(node, floor, dung, reward);
    }},
    {label:' 放っておく', fn:()=>_finishGraveyardMoanRumor(node, floor, dung, reward, '気にはなったが、深追いはせずそのままにしておくことにした。')},
   ];
   break;
  case 'hero_treasure':
   head = [
    {label:' 墓地にある塚へ行く', fn:()=>_heroTreasureTombScene(node, floor, dung, reward)},
    {label:' 放っておく', fn:()=>_finishHeroTreasureRumor(node, floor, dung, reward, '気にはなったが、深追いはせずそのままにしておくことにした。')},
   ];
   break;
  case 'strange_light':
   head = [
    {label:' 町外れの廃屋へ行く', fn:()=>_strangeLightHouseScene(node, floor, dung, reward)},
    {label:' 放っておく', fn:()=>_finishStrangeLightRumor(node, floor, dung, reward, '気にはなったが、深追いはせずそのままにしておくことにした。')},
   ];
   break;
  case 'smuggling': {
   const merchantName = _smugglingGetMerchantName(node, dung);
   head = [
    {label:' 衛兵に密告する', fn:()=>{ _queueTavernThanks(node, dung, 'solved'); _finishSmugglingRumor(node, floor, dung, reward, `衛兵に密告すると、後日${merchantName}は取り調べを受け、捕らえられたという知らせが届いた。`); }},
    {label:' 商家に行く', fn:()=>_smugglingMerchantNode(node, floor, dung, reward, merchantName)},
    {label:' 放っておく', fn:()=>_finishSmugglingRumor(node, floor, dung, reward, '気にはなったが、深追いはせずそのままにしておくことにした。')},
   ];
   break;
  }
  default: return original;
 }
 return [...head, ...rest];
}

const TOWN_RUMOR_DEDICATED_EVENTS_BASE = {
 graveyard_moan: (node, floor, dung, reward) => _graveyardMoanInvestigateChoices(node, floor, dung, reward),
 smuggling: (node, floor, dung, reward) => _smugglingInvestigateChoices(node, floor, dung, reward),
 hero_treasure: (node, floor, dung, reward) => _heroTreasureInvestigateChoices(node, floor, dung, reward),
 strange_light: (node, floor, dung, reward) => _strangeLightInvestigateChoices(node, floor, dung, reward),
};
const TOWN_RUMOR_DEDICATED_EVENTS = {};
Object.keys(TOWN_RUMOR_DEDICATED_EVENTS_BASE).forEach(id=>{
 TOWN_RUMOR_DEDICATED_EVENTS[id] = (node, floor, dung, reward)=>{
  const original = TOWN_RUMOR_DEDICATED_EVENTS_BASE[id](node, floor, dung, reward);
  return _rumorHeardAtTavern(node, dung) ? _tavernHeardEntryChoices(node, floor, dung, reward, original) : original;
 };
});

function generateBountyQuest(fromTownId){
 // Lv3〜10の敵をランダム生成
 const level = 3 + Math.floor(Math.random()*8); // 3〜10
 const npc = generateNPC(level);
 // 賞金首らしい肩書き
 const titles = ['山賊の頭目','元傭兵の凶賊','砂漠の略奪者','暗殺者','逃亡犯','密輸団の首領',
  '賞金首の剣士','指名手配の魔法使い','盗賊ギルドの裏切り者','悪名高き殺し屋','反乱軍の残党'];
 const title = titles[Math.floor(Math.random()*titles.length)];
 npc.bountyTitle = title;
 // 出没場所：50%で同地方内の別の町、50%で他地方の町
 const allTowns = ['khazan','port_argon','stonehiem','elsia','verda','rimholm','marakai',
  'al_rashid','oasis_fort','saroon','duna','yeldun','frostpeak','ashveil',
  'valdheim','nifurvik','iskald','neria','dorua','sarpe','nebra'];
 const otherTowns = allTowns.filter(t=>t!==fromTownId);
 const targetTownId = Math.random()<0.5
  ? otherTowns[Math.floor(Math.random()*otherTowns.length)] // 他の町（他地方含む）
  : fromTownId; // 同じ町
 const isCrossRegion = getRegionKey(targetTownId) !== getRegionKey(fromTownId);
 // 報酬：同地方=レベル×40〜60GP、他地方=レベル×70〜100GP
 let rewardBase = isCrossRegion
  ? level * (70 + Math.floor(Math.random()*31))
  : level * (40 + Math.floor(Math.random()*21));
 // 地方状態システム：対象の出没地（targetTownId）の治安悪化度に応じた割増（最大1.3倍）
 rewardBase = Math.floor(rewardBase * regionConditionRewardMult(getRegionKey(targetTownId), 'unrest'));
 // 期限：他地方は1年（360日）、同地方は余裕を持たせる
 const deadline = isCrossRegion ? 360 : 20 + level * 3;
 const targetTownName = (TOWNS[targetTownId]||{name:targetTownId}).name;
 return {
  id: Date.now() + Math.random(),
  type: 'bounty',
  status: 'active',
  fromTownId,
  targetTownId,
  targetTownName,
  isCrossRegion,
  targetName: npc.name,
  targetTitle: title,
  targetLevel: level,
  targetNPC: npc,
  reward: rewardBase,
  deadlineDays: deadline,
  issuedDay: GAME_TIME.totalDays,
  clientName: '衛兵隊長',
  _defeated: false,
 };
}

// 賞金首を探す
// 暗殺対象を追う
function searchAssassinationTarget(townId){
 const q = (PC.quests||[]).find(q=>q.type==='assassination' && q.status==='active'
  && (q.targetTownId===townId || (!q.targetTownId && q.fromTownId===townId)));
 if(!q){ showSaveToast('暗殺対象の情報が見つからない'); return; }
 const npc = q.targetNPC;
 const backNode = 'TOWN_'+townId.toUpperCase();
 const story = document.getElementById('story');
 story.innerHTML = ` <span style="color:#f0ece0">暗殺対象を追う</span><br><br>`
  +`<span style="color:#c0b098">${npc.name}（${q.targetTitle}）の足取りを追い、人気のない路地で追いついた。</span><br><br>`
  +`<span style="color:#f0ddd8">今なら誰にも見られていない。</span>`;
 renderChoices([
  {label:' 襲撃する', fn:()=>{
   renderChoices([]);
   drawScene('combat');
   document.getElementById('dice-area').classList.add('hidden');
   hideMagicArea();
   const minions = [1,2].map(()=>{
    const m = generateNPC(1+Math.floor(Math.random()*2));
    return {...m, curCon:m.con};
   });
   startCombatNPC({
    enemies:[{...npc, curCon:npc.con}, ...minions],
    canFlee:true,
    win:'__noop__',
    lose:'DEAD',
    onWin:()=>{
     PC.quests = (PC.quests||[]).filter(qq=>qq.id!==q.id);
     gainGPAll(q.reward);
     changeWanted(q.targetTownId||townId, 5);
     recordRegionQuest(q.targetTownId||townId, 'assassination');
     changeAlignment(-8, -8);
     updateHUD();
     const s = document.getElementById('story');
     s.innerHTML = ` <span style="color:#f0ece0">暗殺完了</span><br><br>`
      +`<span style="color:#e8e4d8"> ${npc.name}を仕留めた。</span>`;
     const _aPartyCount = 1 + (PC.party||[]).filter(n=>n.con>0).length;
     const _aShare = Math.floor(q.reward / _aPartyCount);
     const _aShareTxt = _aPartyCount > 1 ? `　<span style="color:#c8b8a0;font-size:calc(var(--font-sm) - 1px)">${_aPartyCount}人で山分け：${_aShare}GP/人</span>` : '';
     s.innerHTML += `<div style="margin-top:12px;padding:10px;background:#1a0a06;border:1px solid #6a3020;border-radius:4px">
      <div style="color:#f0ece0;font-size:var(--font-base)"> 暗殺完了</div>
      <div style="color:#f0ece0;font-size:calc(var(--font-sm) + 1px);margin-top:4px">+${q.reward}GP${_aShareTxt}　${(TOWNS[q.targetTownId||townId]||{name:''}).name}の手配度+5</div>
     </div>`;
     addLifeEvent('',`${npc.name}を暗殺。報酬${q.reward}GP。`);
     showSaveToast(` 暗殺完了！+${q.reward}GP　手配度+5`);
     renderChoices([{label:'← 街に戻る', go: backNode}]);
    },
   });
  }},
 ]);
}

// 誘拐対象を追う（戦闘なし・STテスト）
function searchKidnappingTarget(townId){
 const q = (PC.quests||[]).find(q=>q.type==='kidnapping' && q.status==='active'
  && (q.targetTownId===townId || (!q.targetTownId && q.fromTownId===townId)));
 if(!q){ showSaveToast('誘拐対象の情報が見つからない'); return; }
 const npc = q.targetNPC;
 const backNode = 'TOWN_'+townId.toUpperCase();
 const story = document.getElementById('story');
 if(story) story.innerHTML = ` <span style="color:#f0ece0">誘拐対象を追う</span><br><br>`
  +`<span style="color:#c0b098">${npc.name}（${q.targetTitle}）が一人になる瞬間を待ち、物陰から近づいた。</span>`;
 const srLevel = Math.max(1, Math.ceil((q.targetLevel||2)/2));
 setupSavingRoll({
  attr:'st', level:srLevel,
  onSuccess:()=>{
   PC.quests = (PC.quests||[]).filter(qq=>qq.id!==q.id);
   gainGPAll(q.reward);
   changeWanted(q.targetTownId||townId, 3);
   recordRegionQuest(q.targetTownId||townId, 'kidnapping');
   changeAlignment(-8, -8);
   updateHUD();
   const s = document.getElementById('story');
   if(s) s.innerHTML = ` <span style="color:#f0ece0">誘拐成功</span><br><br><span style="color:#e8e4d8">抵抗する隙を与えず、${npc.name}を連れ去った。</span>`;
   const _kPartyCount = 1 + (PC.party||[]).filter(n=>n.con>0).length;
   const _kShare = Math.floor(q.reward / _kPartyCount);
   const _kShareTxt = _kPartyCount > 1 ? `　<span style="color:#c8b8a0;font-size:calc(var(--font-sm) - 1px)">${_kPartyCount}人で山分け：${_kShare}GP/人</span>` : '';
   s.innerHTML += `<div style="margin-top:12px;padding:10px;background:#1a0a06;border:1px solid #6a3020;border-radius:4px">
    <div style="color:#f0ece0;font-size:var(--font-base)"> 誘拐成功</div>
    <div style="color:#f0ece0;font-size:calc(var(--font-sm) + 1px);margin-top:4px">+${q.reward}GP${_kShareTxt}　${(TOWNS[q.targetTownId||townId]||{name:''}).name}の手配度+3</div>
   </div>`;
   addLifeEvent('',`${npc.name}を誘拐。報酬${q.reward}GP。`);
   showSaveToast(` 誘拐成功！+${q.reward}GP　手配度+3`);
   renderChoices([{label:'← 街に戻る', go: backNode}]);
  },
  onFail:()=>{
   const dmg = Nd6(1);
   PC.con = Math.max(0, PC.con - dmg);
   updateHUD();
   const s = document.getElementById('story');
   if(s) s.innerHTML = ` <span style="color:#f0ece0">誘拐失敗</span><br><br><span style="color:#e8e4d8">${npc.name}に抵抗され、反撃を受けた。体力-${dmg}。</span>`;
   if(PC.con<=0){ renderChoices([{label:'…（力尽きた）', go:'DEAD'}]); return; }
   renderChoices([{label:'← 街に戻る', go: backNode}]);
  },
 });
 renderChoices([]);
 scrollToTop();
}

function searchBountyTarget(townId){
 const q = (PC.quests||[]).find(q=>q.type==='bounty' && q.status==='active'
  && (q.targetTownId===townId || (!q.targetTownId && q.fromTownId===townId)));
 if(!q){ showSaveToast('賞金首の情報が見つからない'); return; }
 const npc = q.targetNPC;
 const townNodeMap = {
  khazan:'TOWN_KHAZAN',port_argon:'TOWN_PORT_ARGON',stonehiem:'TOWN_STONEHIEM',
  elsia:'TOWN_ELSIA',verda:'TOWN_VERDA',rimholm:'TOWN_RIMHOLM',marakai:'TOWN_MARAKAI',
  al_rashid:'TOWN_AL_RASHID',oasis_fort:'TOWN_OASIS_FORT',saroon:'TOWN_SAROON',
  duna:'TOWN_DUNA',yeldun:'TOWN_YELDUN',frostpeak:'TOWN_FROSTPEAK',ashveil:'TOWN_ASHVEIL',
  valdheim:'TOWN_VALDHEIM',nifurvik:'TOWN_NIFURVIK',iskald:'TOWN_ISKALD',
  neria:'TOWN_NERIA',dorua:'TOWN_DORUA',sarpe:'TOWN_SARPE',nebra:'TOWN_NEBRA',kalvo:'TOWN_KALVO',
 };
 const backNode = townNodeMap[townId] || 'TOWN_KHAZAN';
 const story = document.getElementById('story');
 story.innerHTML = ` <span style="color:#f0ece0">賞金首を追う</span><br><br>`
  +`<span style="color:#c0b098">住民への聞き込みの末、${npc.name}（${q.targetTitle}）のアジトを突き止めた。</span><br><br>`
  +`<span style="color:#f0ddd8">扉の向こうに気配がある。</span>`;
 renderChoices([
  {label:' アジトに突入する', fn:()=>{
   renderChoices([]); // 全選択肢をクリア
   drawScene('combat');
   document.getElementById('dice-area').classList.add('hidden');
   hideMagicArea();
   // CON型（NPC型）で戦闘
   // 手下3人をランダム生成（Lv1〜2）
   const minions = [1,2,3].map(()=>{
    const m = generateNPC(1+Math.floor(Math.random()*2));
    return {...m, curCon:m.con};
   });
   startCombatNPC({
    enemies:[{...npc, curCon:npc.con}, ...minions],
    canFlee:false,
    win:'__noop__',
    lose:'DEAD',
    onWin:()=>{
     PC.quests = (PC.quests||[]).filter(qq=>qq.id!==q.id);
     gainGPAll(q.reward);
     changeTrust(q.fromTownId, 5);
     // 翌月まで同じ町の賞金首依頼を封じる
     if(!PC._bountyCooldown) PC._bountyCooldown = {};
     const _bd = getCurrentDate();
     PC._bountyCooldown[q.fromTownId] = _bd.year * 12 + _bd.month;
     clearTavernBoard(q.fromTownId);
     updateHUD();
     const trustNow = getTrust(q.fromTownId);
     const s = document.getElementById('story');
     s.innerHTML = ` <span style="color:#f0ece0">賞金首討伐完了</span><br><br>`
      +`<span style="color:#e8e4d8"> ${npc.name}を討伐した！</span>`;
     const _bPartyCount = 1 + (PC.party||[]).filter(n=>n.con>0).length;
     const _bShare = Math.floor(q.reward / _bPartyCount);
     const _bShareTxt = _bPartyCount > 1 ? `　<span style="color:#c8b8a0;font-size:calc(var(--font-sm) - 1px)">${_bPartyCount}人で山分け：${_bShare}GP/人</span>` : '';
     s.innerHTML += `<div style="margin-top:12px;padding:10px;background:var(--nature-bg);border:1px solid var(--rust);border-radius:4px">
      <div style="color:#f0ece0;font-size:var(--font-base)"> 賞金首討伐完了！</div>
      <div style="color:#f0ece0;font-size:calc(var(--font-sm) + 1px);margin-top:4px">+${q.reward}GP${_bShareTxt}　${(TOWNS[q.fromTownId]||{name:''}).name}の信頼度+5（→${trustNow}）</div>
     </div>`;
     addLifeEvent('',`賞金首${npc.name}を討伐。報酬${q.reward}GP。`);
     showSaveToast(` 賞金首討伐完了！+${q.reward}GP　信頼度+5`);
     renderChoices([{label:'← 街に戻る', go: backNode}]);
    },
   });
  }},
 ]);
}
// 賞金首討伐の報告（酒場で）
function reportBountyQuest(townId){
 // _defeatedかつfromTownIdが一致する依頼を探す（デバッグ用に条件を確認）
 const allBounty = (PC.quests||[]).filter(q=>q.type==='bounty' && q.status==='active');
 const q = allBounty.find(q=>q._defeated && q.fromTownId===townId)
        || allBounty.find(q=>q._defeated); // フォールバック：townId不問で討伐済みを検索
 if(!q){ return false; }
 q.status = 'completed';
 changeAlignment(5, 5); // 賞金首討伐：善+5/秩序+5
 recordRegionQuest(q.targetTownId||q.fromTownId, 'bounty');
 // PC.questsから除去
 const idx = PC.quests.indexOf(q);
 if(idx !== -1) PC.quests.splice(idx, 1);
 gainGPAll(q.reward); updateHUD();
 addLifeEvent('',`賞金首${q.targetName}を討伐。報酬${q.reward}GP。`);
 changeTrust(townId, 5);
 clearTavernBoard(townId);
 showSaveToast(` 賞金首討伐完了！報酬${q.reward}GP・信頼度+5`);
 return true;
}

