// 同行者募集クエストを生成する（既存のgenerateHuntQuestと同じ抽選ロジックを使い、リーダー情報を付加する）
// 同行者募集NPCのレベル抽選（Lv1:25% Lv2:25% Lv3:20% Lv4:20% Lv5:10%）
function _rollCompanionNPCLevel(){
 const r = Math.random()*100;
 if(r < 25) return 1;
 if(r < 50) return 2;
 if(r < 70) return 3;
 if(r < 90) return 4;
 return 5;
}

function generateCompanionHuntQuest(fromTownId){
 const q = generateHuntQuest(fromTownId);
 q.isCompanionHunt = true;
 const leaderLevel = _rollCompanionNPCLevel();
 const leaderType = ['warrior','rogue','wizard'][Math.floor(Math.random()*3)];
 const leader = generateNPC(leaderLevel);
 leader.type = leaderType;
 if(leaderType==='wizard'){ leader.equippedWeapons=[]; }
 const personality = COMPANION_HUNT_LEADER_PERSONALITIES[Math.floor(Math.random()*COMPANION_HUNT_LEADER_PERSONALITIES.length)];
 leader.name = pickNPC();
 q.leader = leader;
 q.leaderPersonality = personality;
 // もう1名、同行するメンバー
 const otherLevel = _rollCompanionNPCLevel();
 const other = generateNPC(otherLevel);
 other.name = pickNPC();
 q.companion = other;
 return q;
}

// 同行配達依頼を生成する（出発町と異なる地方の町をランダムに目的地とし、ROUTESグラフで経路を求める）
function generateCompanionDeliveryQuest(fromTownId){
 const fromRegion = getRegionKey(fromTownId);
 const candidates = Object.keys(TOWNS).filter(t => t!==fromTownId && getRegionKey(t)!==fromRegion);
 if(!candidates.length) return null;
 const toTownId = candidates[Math.floor(Math.random()*candidates.length)];
 const route = findTownRoute(fromTownId, toTownId);
 if(!route || route.length < 2) return null; // 到達不能な組み合わせは諦める

 const leaderLevel = _rollCompanionNPCLevel();
 const leaderType = ['warrior','rogue','wizard'][Math.floor(Math.random()*3)];
 const leader = generateNPC(leaderLevel);
 leader.type = leaderType;
 if(leaderType==='wizard'){ leader.equippedWeapons=[]; }
 const personality = COMPANION_HUNT_LEADER_PERSONALITIES[Math.floor(Math.random()*COMPANION_HUNT_LEADER_PERSONALITIES.length)];
 leader.name = pickNPC();
 const otherLevel = _rollCompanionNPCLevel();
 const other = generateNPC(otherLevel);
 other.name = pickNPC();

 // 報酬は通常の討伐依頼と同じ算出式を流用（総距離感を反映するため、経由町数×レベル帯で簡易計算）
 const totalLegs = route.length - 1;
 const reward = Math.floor((20 + totalLegs*15) * (1 + leaderLevel*0.3));

 return {
  id: Date.now()+Math.random(), type:'companionDelivery', status:'active',
  isCompanionDelivery: true,
  fromTownId, toTownId, route,
  legIndex: 0, // 現在、route[legIndex] → route[legIndex+1] の区間を担当中
  isPausedAt: null, // 経由町で一泊・自由行動中なら、その町IDが入る
  leader, leaderPersonality: personality, companion: other,
  reward, issuedDay: GAME_TIME.totalDays,
 };
}

function generateHuntQuest(fromTownId){
 const region = getRegionKey(fromTownId) || 'khazan_region';
 const table = HUNT_MONSTER_TABLE[region] || HUNT_MONSTER_TABLE.khazan_region;

 // 低確率（8%）でCR型ではなく、人型・亜人系のNPC型精鋭種族に切り替える（通常のCR型より出現率を下げる）
 const isElite = Math.random() < 0.05;
 let m, eliteSpecies=null, eliteLevel=null, eliteRank=null;
 if(isElite){
  const speciesList = Object.keys(ELITE_MONSTER_INFO);
  eliteSpecies = speciesList[Math.floor(Math.random()*speciesList.length)];
  const tiers = ELITE_MONSTER_INFO[eliteSpecies].tiers;
  const tier = tiers[Math.floor(Math.random()*tiers.length)];
  eliteLevel = tier.level; eliteRank = tier.rank;
  const equivMR = ELITE_MONSTER_EQUIV_MR[eliteSpecies][eliteLevel];
  m = { name: eliteMonsterDisplayName(eliteSpecies, eliteRank), mr: equivMR, armor:0, minApp:1, maxApp:2 };
 } else {
  // weight指定があれば重み付き抽選（未指定は重み1として扱う）
  const totalWeight = table.reduce((s,e)=>s+(e.weight!=null?e.weight:1), 0);
  let r = Math.random() * totalWeight;
  m = table[table.length-1];
  for(const e of table){
   const w = e.weight!=null ? e.weight : 1;
   if(r < w){ m = e; break; }
   r -= w;
  }
 }
 // 部屋数 1〜3
 const roomCount = 1 + Math.floor(Math.random() * 3);
 // 各部屋のモンスター数
 const rooms = [];
 let totalMR = 0;
 for(let r = 0; r < roomCount; r++){
  const count = m.minApp + Math.floor(Math.random() * (m.maxApp - m.minApp + 1));
  const roomMR = count * m.mr;
  rooms.push({ count, mr: m.mr, roomMR });
  totalMR += roomMR;
 }
 // 報酬：総MRの0.8〜1.2倍 (GP)。精鋭種族は稀少性を鑑みてさらに1.3倍のボーナスを乗せる
 const reward = Math.floor(totalMR * (0.8 + Math.random() * 0.4) * (isElite ? 1.3 : 1));
 const clientName = pickNPC();
 const caveNames = ['北の洞穴','南の岩窟','東の廃坑','西の竪穴','郊外の洞穴','古い砦跡','廃坑の奥','荒れ地の岩穴'];
 const caveName = caveNames[Math.floor(Math.random() * caveNames.length)];
 const quest = {
  id: Date.now() + Math.random(),
  type: 'hunt',
  fromTownId,
  monsterName: m.name,
  monsterMR: m.mr,
  monsterArmor: m.armor||0,
  isEliteHunt: isElite,
  eliteSpecies, eliteLevel, eliteRank,
  rooms,
  totalMR,
  caveName,
  clientName,
  reward,
  deadlineDays: 30,
  issuedDay: GAME_TIME.totalDays,
  status: 'active',
  crossRegion: false,
 };
 // ダンジョンを事前生成
 quest.dungeon = generateHuntDungeon(quest);
 return quest;
}

// 討伐クエスト実行（洞穴戦闘を連鎖させる）
// グローバルに現在の討伐状態を保持（onWinから参照するため）
let _huntState = null;

function startHuntQuest(questId){
 const q = (PC.quests||[]).find(q=>q.id===questId && q.status==='active');
 if(!q){ showSaveToast('依頼が見つかりません'); return; }

 // 酒場パネルを開いたまま出発しようとした場合に備え、確実に閉じる
 const _pp = document.getElementById('patron-panel');
 if(_pp && !_pp.classList.contains('hidden')) _pp.classList.add('hidden');

 // YDシステムでダンジョン生成（未生成なら生成）
 if(!q.ydDungeon){
  q.ydDungeon = ydInitDungeonForHunt(q);
 }

 const torches = countTorches();
 const storyEl = document.getElementById('story');
 const torchMsg = torches > 0
  ? `<span style="color:#f0ece0"> 松明を ${torches}本 持っている。</span>`
  : `<span style="color:#e0d0d0"> 松明を持っていない！暗闇の中を進むことになる。</span>`;

 // 討伐進捗
 const total = q.ydDungeon.targetCount || 0;
 const killed = q.ydDungeon.killedKeys
  ? q.ydDungeon.killedKeys.filter(k=>PC[k]).length : 0;

 storyEl.innerHTML = `
  <div style="border:1px solid #484848;border-radius:4px;padding:12px;background:#0c0900">
   <div style="color:#f0ece0;font-size:var(--font-base);margin-bottom:8px"> 討伐出撃：${q.caveName}</div>
   <div style="color:#c8b8a0;font-size:var(--font-sm);margin-bottom:4px">依頼主：<span style="color:#f0ece0">${q.clientName}</span></div>
   <div style="color:#c8b8a0;font-size:calc(var(--font-sm) - 1px);margin-bottom:6px">目標：<span style="color:#f4ede0">${q.monsterName}</span>
    　討伐：<span style="color:${killed>=total?'var(--gold2)':'var(--dim)'}">${killed}/${total}体</span></div>
   <div style="font-size:var(--font-sm)">${torchMsg}</div>
  </div>`;

 renderChoices([
  { label:' 出発する', fn:()=>{
   // YDダンジョンに切り替え
   PC._yeldunDungeon = q.ydDungeon;
   initTorch();
   ydGoNode(q.ydDungeon.floors[1].entryNodeId, 1);
  }},
  { label:'← 酒場に戻る', fn:()=>{ go(currentNodeId); } },
 ]);
 scrollToTop();
}

// 討伐依頼用YDダンジョン初期化
function ydInitDungeonForHunt(quest){
 const dung = ydInitDungeon();
 dung.isHuntDungeon = true;
 dung.huntQuestId   = quest.id;
 dung.huntTownId    = quest.fromTownId;
 // 討伐対象の配置計画（ノード生成時に埋め込む）
 const total = quest.rooms.reduce((s,r)=>s+r.count, 0);
 dung.targetCount   = total;
 dung.targetName    = quest.monsterName;
 dung.targetMR      = quest.monsterMR;
 dung.targetArmor   = quest.monsterArmor||0;
 // NPC型精鋭種族の討伐依頼なら、種族・階級を引き継ぐ
 dung.isEliteHunt   = quest.isEliteHunt||false;
 dung.eliteSpecies  = quest.eliteSpecies||null;
 dung.eliteLevel    = quest.eliteLevel||null;
 dung.killedKeys    = []; // 配置した討伐対象のflagKey一覧
 dung.huntReward    = quest.reward;
 // PCに残っている古いyd_ht_フラグをクリア（前回討伐の残留を防ぐ）
 Object.keys(PC).filter(k=>k.startsWith('yd_ht_')||k.startsWith('yd_enc_')||k.startsWith('yd_m_')||k.startsWith('yd_l_')||k.startsWith('yd_a_')||k.startsWith('yd_r_')||k.startsWith('yd_tr_')||k.startsWith('yd_st_')||k.startsWith('yd_ev_')||k.startsWith('yd_fn_')||k.startsWith('yd_s_')||k.startsWith('yd_d_')||k.startsWith('yd_hd_')).forEach(k=>delete PC[k]);
 // 入口ノードを生成
 const f = dung.floors[1];
 const entryNode = {
  id: f.entryNodeId, type:'entrance', floor:1,
  exits:{}, pending:['forward'], _facingIdx: Math.floor(Math.random()*4),
 };
 f.nodeMap[f.entryNodeId] = entryNode;
 return dung;
}

// ── 領地の砦跡：討伐依頼と同じランダムダンジョン形式で、住み着いた山賊・モンスターを排除する ──
function ydInitDungeonForFief(){
 const dung = ydInitDungeon();
 dung.design.dungeonStyle = 'fortress'; // 廃砦として表現するため様式を固定する
 dung.isFiefClearing = true;
 dung.targetCount = (4 + Math.floor(Math.random()*3)) * 2; // 4〜6体の2倍＝8〜12体
 dung.targetName  = '砦に住み着いた者たち';
 dung.killedKeys  = [];
 Object.keys(PC).filter(k=>k.startsWith('yd_ht_')||k.startsWith('yd_enc_')||k.startsWith('yd_m_')||k.startsWith('yd_l_')||k.startsWith('yd_a_')||k.startsWith('yd_r_')||k.startsWith('yd_tr_')||k.startsWith('yd_st_')||k.startsWith('yd_ev_')||k.startsWith('yd_fn_')||k.startsWith('yd_s_')||k.startsWith('yd_d_')||k.startsWith('yd_hd_')).forEach(k=>delete PC[k]);
 const f = dung.floors[1];
 const entryNode = {
  id: f.entryNodeId, type:'entrance', floor:1,
  exits:{}, pending:['forward'], _facingIdx: Math.floor(Math.random()*4),
 };
 f.nodeMap[f.entryNodeId] = entryNode;
 return dung;
}

// 領地の砦跡へ出発する（townIdは免状の基点となった町＝現在地）
// 町から領地へ向かう（免状の基点からの日数分、実際に旅をする）
// 領地への旅：通常の町間移動と同じ画面（進捗バー・旅の情景・道中イベント）を経由する
function _fiefTravelAnimated(townId, onArrive){
 const charter = getFiefCharterByAnchor(townId);
 const days = charter?.anchorDays || 0;
 const from = TOWNS[townId] || {name:townId};
 const fiefLabel = (charter && PC.properties?.[charter.fiefId]?.fiefName) || '領地';

 if(days <= 0){ onArrive(); return; }

 drawScene('travel');
 showTravelImage('walk', townId, townId); // 目的地は実在の町ではないため、出発地の地方の雰囲気を流用する
 const storyEl = document.getElementById('story');
 if(storyEl) storyEl.innerHTML = '';
 const tpw = document.getElementById('travel-progress-wrap');
 if(tpw){
  tpw.style.display = '';
  document.getElementById('travel-progress-bar').style.width = '0%';
  document.getElementById('travel-progress-dot').style.left = '0%';
  document.getElementById('travel-latest').textContent = '';
  document.getElementById('travel-progress-label').innerHTML =
   ` 徒歩　<span style="color:#f0ece0">${from.name}</span> → <span style="color:#f0ece0">${fiefLabel}</span>　<span id="travel-day-count" style="color:#e0d8c8">0/${days}日</span>`;
 }
 renderChoices([]);

 advanceDaysAnimated(days, onArrive);
 if(travelState){ travelState.method = 'walk'; travelState.crossRegion = false; travelState.destLabel = fiefLabel; }
 travelLog(`<span style="color:#b8a890">徒歩で <span style="color:#f0ece0">${from.name}</span> → <span style="color:#f0ece0">${fiefLabel}</span> へ出発。所要: ${days}日　費用: 0GP</span>`);
}

function travelToFief(townId){
 _fiefTravelAnimated(townId, ()=>enterFiefClearing(townId));
}

// 整備に向かう場合も同様に、町から領地までの日数分を旅する
function travelToFiefImprove(townId){
 _fiefTravelAnimated(townId, ()=>showFiefImprove(townId));
}

// 免状の状態に応じて、討伐・整備・拠点管理のいずれかへ自動的に振り分ける（旅の選択肢から使う）
function travelToFiefAny(townId){
 _fiefTravelAnimated(townId, ()=>{
  const charter = getFiefCharterByAnchor(townId);
  if(!charter) return;
  if(!charter.cleared) enterFiefClearing(townId);
  else if(!charter.improved) showFiefImprove(townId);
  else showFiefPlaza(townId);
 });
}

// 領地のメインメニュー（通常の町の中央広場に相当）
function showFiefPlaza(townId){
 _migrateFiefDataIfNeeded();
 const charter = getFiefCharterByAnchor(townId);
 const fiefId = charter?.fiefId;
 currentNodeId = fiefId ? 'FIEF_PLAZA_'+fiefId.toUpperCase() : 'FIEF_PLAZA'; // セーブ/ロードで広場から正しく再開できるようにする
 autoSave(); // 領地の広場への到着時にも自動セーブする
 const prop = fiefId ? PC.properties?.[fiefId] : null;
 const story = document.getElementById('story');
 const plazaLabel = prop?.fiefName ? `${prop.fiefName}の広場` : '広場';
 story.innerHTML = ` <span style="color:#f0ece0">${plazaLabel}</span><br><br>`
  +`<span style="color:#c8b8a0">かつての砦跡は、今では小さいながらも自分の領地となっている。広場には静けさが漂う。</span><br>`
  +(prop?.population != null ? `<span style="color:#c8b8a0;font-size:calc(var(--font-sm) - 1px)">領民：${prop.population}人（${Math.floor(prop.population/5)}家族）</span>` : '');
 const built = (prop?.facilities||[]).map(id=>FIEF_FACILITIES.find(f=>f.id===id)).filter(Boolean);
 renderChoices([
  {label:' 拠点を確認する', fn:()=>goPropertyNode(fiefId)},
  ...(built.length ? [{label:' 施設を見る', fn:()=>showFiefFacilityList(townId, fiefId)}] : []),
  {label:'← 町へ戻る', fn:()=>travelBackFromFief(townId)},
 ]);
 scrollToTop();
}

// 建設済みの施設一覧を1つのメニューにまとめて表示する
function showFiefFacilityList(townId, fiefId){
 const prop = PC.properties?.[fiefId];
 const built = (prop?.facilities||[]).map(id=>FIEF_FACILITIES.find(f=>f.id===id)).filter(Boolean);
 const story = document.getElementById('story');
 const plazaLabel = prop?.fiefName ? `${prop.fiefName}の施設` : '施設を見る';
 story.innerHTML = ` <span style="color:#f0ece0">${plazaLabel}</span><br><br>`
  +`<span style="color:#c8b8a0">どこに行きますか？</span>`;
 renderChoices([
  ...built.map(f=>({label:` ${f.name}に行く`, fn:()=>showFiefFacilityVisit(fiefId, f.id)})),
  {label:'← 広場に戻る', fn:()=>showFiefPlaza(townId)},
 ]);
 scrollToTop();
}

// 広場から、建設済みの施設の様子を見に行く（フレーバーのみ）
// 施設ごとの、領民の数に応じた接点フレーバー（4段階：閑散／ちらほら／賑わい／活況）
const FIEF_FACILITY_POP_FLAVOR = {
 well: [
  '井戸の周りには誰もいない。桶だけが静かに置かれている。',
  '井戸端で、領民が一人、桶に水を汲んでいる。目が合うと軽く会釈された。',
  '井戸端に数人の領民が集まり、水を汲みながら世間話に花を咲かせている。',
  '井戸の周りは領民でごった返し、水汲みの行列ができている。笑い声が絶えない。',
 ],
 rampart: [
  '防壁の上に人影はない。風の音だけが吹き抜けている。',
  '防壁の一角で、領民が一人、崩れた箇所を黙々と補修している。',
  '防壁の上を数人の領民が行き来し、点検や修繕にあたっている。',
  '防壁沿いには大勢の領民が働いており、活気ある槌音があちこちから響いている。',
 ],
 watchtower: [
  '見張り塔には誰もいない。がらんとした静けさが漂う。',
  '見張り塔の上に、一人の見張りが退屈そうに遠くを眺めている。',
  '見張り塔の周りには数人が集まり、交代の順番を待っている。',
  '見張り塔の下は多くの領民で賑わい、遠方の噂話に花が咲いている。',
 ],
 guardpost: [
  '詰め所はひっそりとして、人の気配がない。',
  '詰め所の前で、一人の警備が退屈そうに槍にもたれている。',
  '詰め所には数人の警備が集まり、巡回の打ち合わせをしている。',
  '詰め所の周りは大勢の領民と警備でごった返し、安心感に満ちた喧騒がある。',
 ],
 tavern: [
  '酒場の扉を開けても、客の姿はまばらだ。',
  '酒場の隅で、領民が一人、静かに杯を傾けている。',
  '酒場には数人の領民が集まり、笑い声混じりに酒を酌み交わしている。',
  '酒場は領民でぎっしりと埋まり、歌声と笑い声が絶え間なく響いている。',
 ],
 temple: [
  '寺院の中はしんと静まり返り、誰の姿もない。',
  '寺院の片隅で、領民が一人、静かに祈りを捧げている。',
  '寺院には数人の領民が集まり、それぞれの祈りを捧げている。',
  '寺院は大勢の領民で埋め尽くされ、祈りの声が堂内に満ちている。',
 ],
 market: [
  '市場には商人の姿も客の姿もなく、閑散としている。',
  '市場の一角に、一人の行商人が退屈そうに品物を並べている。',
  '市場には数軒の露店が並び、領民が品定めをしている。',
  '市場は多くの露店と領民でひしめき、活気ある呼び込みの声が飛び交っている。',
 ],
};
function _fiefFacilityPopFlavor(facilityId, population){
 const arr = FIEF_FACILITY_POP_FLAVOR[facilityId];
 if(!arr) return '';
 const tier = population < 20 ? 0 : population < 100 ? 1 : population < 300 ? 2 : 3;
 return arr[tier];
}

function showFiefFacilityVisit(fiefId, facilityId){
 const f = FIEF_FACILITIES.find(x=>x.id===facilityId);
 const prop = PC.properties?.[fiefId];
 const population = prop?.population||0;
 const popFlavor = _fiefFacilityPopFlavor(facilityId, population);
 const story = document.getElementById('story');
 story.innerHTML = ` <span style="color:#f0ece0">${f?.name||'施設'}</span><br><br>`
  +`<span style="color:#c8b8a0">${f?.desc||''}</span>`
  +(popFlavor ? `<br><br><span style="color:#b8a888">${popFlavor}</span>` : '');
 renderChoices([
  {label:'← 施設一覧に戻る', fn:()=>{
   const charter = getFiefCharter(fiefId);
   showFiefFacilityList(charter?.anchorTownId, fiefId);
  }},
 ]);
 scrollToTop();
}

// 領地から基点の町への帰路。行きと同じ日数をかけて旅する（切り離された遠隔地という位置づけを保つ）
function travelBackFromFief(anchorTownId){
 const townId = anchorTownId || getFiefCharter(PC._fiefCharters?.[0]?.fiefId)?.anchorTownId;
 if(!townId){ go('TOWN_KHAZAN'); return; }
 const charter = getFiefCharterByAnchor(townId);
 const days = charter?.anchorDays || 0;
 const to = TOWNS[townId] || {name:townId};
 const fiefLabel = (charter && PC.properties?.[charter.fiefId]?.fiefName) || '領地';

 if(days <= 0){ go('TOWN_'+townId.toUpperCase()); return; }

 drawScene('travel');
 showTravelImage('walk', townId, townId);
 const storyEl = document.getElementById('story');
 if(storyEl) storyEl.innerHTML = '';
 const tpw = document.getElementById('travel-progress-wrap');
 if(tpw){
  tpw.style.display = '';
  document.getElementById('travel-progress-bar').style.width = '0%';
  document.getElementById('travel-progress-dot').style.left = '0%';
  document.getElementById('travel-latest').textContent = '';
  document.getElementById('travel-progress-label').innerHTML =
   ` 徒歩　<span style="color:#f0ece0">${fiefLabel}</span> → <span style="color:#f0ece0">${to.name}</span>　<span id="travel-day-count" style="color:#e0d8c8">0/${days}日</span>`;
 }
 renderChoices([]);

 advanceDaysAnimated(days, ()=>go('TOWN_'+townId.toUpperCase()));
 if(travelState){ travelState.method = 'walk'; travelState.crossRegion = false; }
 travelLog(`<span style="color:#b8a890">徒歩で <span style="color:#f0ece0">${fiefLabel}</span> → <span style="color:#f0ece0">${to.name}</span> へ出発。所要: ${days}日　費用: 0GP</span>`);
}

function enterFiefClearing(townId){
 const _pp = document.getElementById('patron-panel');
 if(_pp && !_pp.classList.contains('hidden')) _pp.classList.add('hidden');

 const charter = getFiefCharterByAnchor(townId);
 if(!charter) return;
 if(!charter._clearingDungeon){
  charter._clearingDungeon = ydInitDungeonForFief();
  charter._clearingDungeon.fiefId = charter.fiefId;
  charter._clearingDungeon.fiefAnchorTownId = townId;
 }
 const dung = charter._clearingDungeon;

 const torches = countTorches();
 const storyEl = document.getElementById('story');
 const torchMsg = torches > 0
  ? `<span style="color:#f0ece0"> 松明を ${torches}本 持っている。</span>`
  : `<span style="color:#e0d0d0"> 松明を持っていない！暗闇の中を進むことになる。</span>`;
 const killed = dung.killedKeys.filter(k=>PC[k]).length;

 storyEl.innerHTML = `
  <div style="border:1px solid #484848;border-radius:4px;padding:12px;background:#0c0900">
   <div style="color:#f0ece0;font-size:var(--font-base);margin-bottom:8px"> 領地の砦跡</div>
   <div style="color:#c8b8a0;font-size:var(--font-sm);margin-bottom:4px">かつて主を失った石造りの砦。今は山賊や獣が住み着いている。ここを排除できれば、あなた自身の拠点として整備できる。</div>
   <div style="color:#c8b8a0;font-size:calc(var(--font-sm) - 1px);margin-bottom:6px">排除：<span style="color:${killed>=dung.targetCount?'var(--gold2)':'var(--dim)'}">${killed}/${dung.targetCount}体</span></div>
   <div style="font-size:var(--font-sm)">${torchMsg}</div>
  </div>`;

 renderChoices([
  { label:' 出発する', fn:()=>{
   PC._yeldunDungeon = dung;
   initTorch();
   ydGoNode(dung.floors[1].entryNodeId, 1);
  }},
  { label:'← 町に戻る', fn:()=>travelBackFromFief(townId) },
 ]);
 scrollToTop();
}

// 領地の砦跡を1000GPで最低限の拠点として整備する
function showFiefImprove(townId){
 const story = document.getElementById('story');
 const price = 1000;
 story.innerHTML = ` <span style="color:#e0d8c8">領地の砦跡</span><br><br>`
  +`<span style="color:#c8b8a0">敵は排除したが、このままではとても人が住める状態ではない。崩れた壁を直し、最低限の設備を整えれば、拠点として使えるようになるだろう。</span><br><br>`
  +`<span style="color:#ffcc88">整備費用：${price}GP</span>`;
 renderChoices([
  {label:` 整備する（${price}GP）`, fn:()=>{
   if((PC.gold||0) < price){
    showSaveToast('所持金が足りない');
    return;
   }
   const charter = getFiefCharterByAnchor(townId);
   if(!charter) return;
   PC.gold -= price;
   PC.properties = PC.properties||{};
   const startFamilies = d6(); // D6家族
   const startPop = startFamilies * 5;
   let fiefName = (prompt('あなたの領地に名前を付けてください。', '') || '').trim();
   if(!fiefName) fiefName = '無名の領地';
   PC.properties[charter.fiefId] = { boughtAt:price, day:GAME_TIME.totalDays, tier:0, storage:{ gold:0, sp:0, cp:0, weapons:[], armors:[], jewels:[], torches:0 },
    population: startPop, lastPopQuarterKey: _fiefQuarterKey(GAME_TIME.totalDays), lastTaxMonthKey: _fiefMonthKey(GAME_TIME.totalDays), facilities: [], ledger: [], fiefName };
   charter.improved = true;
   delete charter._clearingDungeon;
   updateHUD();
   addLifeEvent('', `領地の砦跡を整備し、「${fiefName}」と名付けて自身の拠点とした（領民${startFamilies}家族・${startPop}人が住み着いた）。`);
   showSaveToast(`「${fiefName}」を整備した！領民${startFamilies}家族（${startPop}人）が住み着いた`);
   showFiefPlaza(townId);
  }},
  {label:'← 町に戻る', fn:()=>travelBackFromFief(townId)},
 ]);
}

// 討伐ダンジョン：指定ノードIDへ移動
function _huntGoNode(nodeIdOrIdx, opts){
 opts = opts||{};
 if(!_huntState) return;
 // 酒場パネルが開いたままダンジョンへ移動した場合に備え、確実に閉じる
 const _pp = document.getElementById('patron-panel');
 if(_pp && !_pp.classList.contains('hidden')) _pp.classList.add('hidden');
 const {q} = _huntState;
 const dung = q.dungeon;
 if(!dung) return;

 // IDまたはインデックスでノードを検索
 let node, nodeIdx;
 if(typeof nodeIdOrIdx === 'number'){
  nodeIdx = nodeIdOrIdx;
  node = dung.nodes[nodeIdx];
 } else {
  nodeIdx = dung.nodes.findIndex(n=>n.id===nodeIdOrIdx);
  node = dung.nodes[nodeIdx];
 }
 if(!node) return;

 _huntState.nodeId = node.id;
 _huntState.nodeIdx = nodeIdx;
 window._currentHuntDung = dung;
 window._currentHuntNode = { id:node.id, _idx:nodeIdx };

 // ── ダンジョン画像制御 ──
 if(node.type === 'entrance'){
  _huntState._imgStep = 0;
  hideDungeonImage();
 } else {
  // 通路移動：5ステップごとにランダム切り替え
  _huntState._imgStep = (_huntState._imgStep || 0) + 1;
  if(_huntState._imgStep % 5 === 0) rotateDungeonImage();
  else if(_huntState._imgStep === 1) showDungeonImage(node.id); // 初回
 }

 // 松明消費（入口以外・灯り復活時はスキップ）重量オーバーなら2倍消費
 if(node.type !== 'entrance'){
  // Enchant Weapon/Fortify Armorの残りターンは、松明消費の有無に関わらずノード移動1回につき1回だけ減らす
  _decrementWizardBuffTurns();
  _decrementChainedTurns();
  if(!opts.skipTorch){
   const _hdConsume = checkWeightPenalty().over ? 2 : 1;
   for(let _tc=0; _tc<_hdConsume; _tc++){
    if(PC._torchTurns > 0){
     PC._torchTurns--;
     if(PC._torchTurns <= 0 && PC._torchStock > 0){
      PC._torchStock--;
      PC._torchTurns = 10;
     }
    } else break;
   }
  }
 }

 // ── 松明切れチェック ──
 if(node.type !== 'entrance' && (PC._torchTurns||0) <= 0){
  const storyEl2 = document.getElementById('story');
  storyEl2.innerHTML = `<div style="color:#e0d0d0;font-size:calc(var(--font-sm) + 1px);margin-bottom:8px"> 松明が切れた！</div>
   <span style="color:var(--white2)">完全な暗闇の中、壁を手探りで進む。出口まで帰り着けるか……</span>`;
  document.getElementById('cbt-area').classList.add('hidden');
  document.getElementById('scroll-area').classList.remove('in-combat');
  document.getElementById('text-win').style.display = '';

  const huntDarkChoices = [{
   label:' 暗闇の中を出口へ向かう（運 Lv3 能力値テスト）',
   fn:()=>{
    const entranceNode = dung.nodes.find(n=>n.type==='entrance');
    setupSavingRoll({
     attr:'lk', level:3,
     onSuccess:()=>{
      const stEl = document.getElementById('story');
      stEl.innerHTML = `<span style="color:#f0ece0"> 脱出成功！</span><br><br>
       壁を伝いながら必死に出口を探した。なんとか入口へたどり着いた！`;
      renderChoices([{label:' 入口へ戻る', fn:()=>{ if(entranceNode) _huntGoNode(entranceNode.id); }}]);
      scrollToTop();
     },
     onFail:()=>{
      const dmg = 5;
      PC.con = Math.max(0, PC.con - dmg); updateHUD();
      const stEl = document.getElementById('story');
      if(PC.con <= 0){
       stEl.innerHTML = `<span style="color:#e0d0d0"> 力尽きた……</span><br><br>
        闇の中で足を踏み外し、石の床に叩きつけられた。`;
       renderChoices([{label:'…（力尽きた）', go:'DEAD'}]);
      } else {
       stEl.innerHTML = `<span style="color:#e0d0d0"> 脱出失敗</span><br><br>
        出口を探して歩いていると、段差に気づかず転倒した。<br><br>
        体力-${dmg}（残り ${PC.con}）`;
       renderChoices([{label:' もう一度出口を探す（運 Lv3 能力値テスト）', fn:()=>{ _huntGoNode(nodeIdOrIdx); }}]);
      }
      scrollToTop();
     },
    });
    scrollToTop();
   }
  }];

  // 灯り魔法があれば使えるようにする
  if(_partyHasSpellFn('wisp') || _partyHasSpellFn('blindSpot')){
   const hasWisp = _partyHasSpellFn('wisp');
   const hasBlindSpot = _partyHasSpellFn('blindSpot');
   const lightOpts = {};
   if(hasWisp) lightOpts.wisp = { desc:'指先を1ターン照らす', fn:()=>{ PC._torchTurns=Math.max(PC._torchTurns||0,2); _huntGoNode(nodeIdOrIdx); return true; }};
   if(hasBlindSpot) lightOpts.blindSpot = { desc:'Blind Spotで4ターン安全に進む', fn:()=>{ PC._torchTurns=Math.max(PC._torchTurns||0,4); _huntGoNode(nodeIdOrIdx); return true; }};
   huntDarkChoices.push({ label:' 明かりの魔法を使う', fn:()=>openSpellModal('暗闇の中で明かりを灯す', lightOpts)});
  }

  renderChoices(huntDarkChoices);
  scrollToTop();
  updateHUD();
  return;
 }

 // UI復元
 document.getElementById('cbt-area').classList.add('hidden'); document.getElementById('scroll-area').classList.remove('in-combat');
 document.getElementById('text-win').style.display = '';
 document.getElementById('dice-area').classList.add('hidden');
 hideMagicArea();
 const _okArea = document.getElementById('cbt-ok-area');
 if(_okArea){ _okArea.innerHTML=''; _okArea.style.display='none'; }

 // テキスト描画
 const storyEl = document.getElementById('story');
 let nodeTxt = typeof node.txt==='function' ? node.txt() : (node.txt||'');
 // 分岐点の場合は追加描写（固定テキストを使用）
 if(node.isBranch){
  if(!node._branchDesc){
   const side = node.branchSide==='right' ? '右手' : '左手';
   const branchDescs = [
    `${side}に暗い通路が分かれている。`,
    `進む先で通路が二手に分かれている。${side}の道は奥が見えない。`,
    `ここで道が分岐している。${side}手の通路から冷たい風が吹いている。`,
    `壁の角に${side}へ続く通路の入口がある。`,
   ];
   node._branchDesc = _rdungPick(branchDescs);
  }
  nodeTxt += `<br><br><span style="color:#c8b8a0">${node._branchDesc}</span>`;
 }
 storyEl.innerHTML = nodeTxt;

 // 選択肢を組み立て
 // 1. ノード固有の行動選択肢（戦闘・罠・扉など）
 const actionChoices = _rdungGetActionChoices(node);
 // 2. exitsからの移動選択肢
 const canMove = _rdungCanMove(node);
 let moveChoices;
 if(canMove){
  const exits = node.exits||[];
  if(q.isCompanionHunt && exits.length>0){
   // 同行者募集：分岐があってもリーダーが道を決めた体にし、一本道の選択肢だけを見せる
   const chosen = exits[Math.floor(Math.random()*exits.length)];
   const leaderName = q.leader ? q.leader.name : 'リーダー';
   moveChoices = [{label:`▶ ${leaderName}について進む`, fn:()=>_huntGoNode(chosen.targetId)}];
  } else {
   moveChoices = exits.map(exit=>({label:exit.label, fn:()=>_huntGoNode(exit.targetId)}));
  }
 } else if(node.type==='encounter' && node.flagKey && !PC[node.flagKey]){
  // 未撃破：「戻る」のみ表示
  const back = (node.exits||[]).find(e=>e.label.includes('戻る'));
  moveChoices = back ? [{label:'◀ 来た道へ戻る', fn:()=>_huntGoNode(back.targetId)}] : [];
 } else {
  moveChoices = [];
 }

 // 魔法ボタンを追加（魔法使い・盗賊）
 const allChoices = [...actionChoices, ...moveChoices];
 if(_eligibleOutOfCombatCasters(node.id).length && !cbtState){
  allChoices.push({ label:' 魔法を使う', fn:()=>openSpellModal('', null, node.id), _isMagicBtn:true });
 }
 renderChoices(allChoices);
 scrollToTop();
 updateHUD();
}

// ノードの行動選択肢を返す
function _rdungGetActionChoices(node){
 const ch = [];
 if(node.combatChoices)  ch.push(...node.combatChoices());
 if(node.doorChoices)    ch.push(...node.doorChoices());
 if(node.trapChoices)    ch.push(...node.trapChoices());
 if(node.alcoveChoices)  ch.push(...node.alcoveChoices());
 if(node.passageChoices) ch.push(...node.passageChoices());
 if(node.extraChoices)   ch.push(...node.extraChoices());
 if(node.bossChoices)    ch.push(...node.bossChoices());
 return ch;
}

// 移動可能かどうか
function _rdungCanMove(node){
 if(node.type==='boss') return false;
 if(node.type==='encounter' && node.flagKey && !PC[node.flagKey]) return false;
 return true;
}

// 討伐ダンジョン用renderChoices：go:ノードIDを_huntGoNodeに変換
function _huntRenderChoices(choices){
 const dung = window._currentHuntDung;
 if(!dung){ renderChoices(choices); return; }
 const wrapped = (choices||[]).map(ch=>{
  const dest = typeof ch.go==='function' ? ch.go() : ch.go;
  if(dest && typeof dest==='string' && dest.startsWith(dung.dungId)){
   const idx = dung.nodes.findIndex(n=>n.id===dest);
   if(idx>=0) return {label:ch.label, fn:()=>{ if(ch.fn)ch.fn(); _huntGoNode(idx); }};
  }
  return ch;
 });
 renderChoices(wrapped);
}

function _huntShowRoom(){
 // onWin後の処理：現在ノードを再描画（フラグが立った後なのでUIが更新される）
 if(!_huntState) return;
 _huntGoNode(_huntState.nodeId || _huntState.nodeIdx || 0);
}
// 討伐完了処理
function huntQuestComplete(q){
 q.status = 'completed';
 changeAlignment(3, 3); // 討伐完了：善+3/秩序+3
 recordRegionQuest(q.fromTownId, 'hunt');
 PC.quests = (PC.quests||[]).filter(qq=>qq.id !== q.id);
 hideDungeonImage();
 // 討伐同行者募集は、通常の頭数山分けの、さらに半分をPCの取り分とする
 const _huntPartyCountForPay = 1 + (PC.party||[]).filter(n=>n.con>0).length;
 const _companionPay = q.isCompanionHunt ? Math.floor(Math.floor(q.reward / _huntPartyCountForPay) / 2) : 0;
 if(q.isCompanionHunt){
  gainGP(_companionPay, PC);
 } else {
  gainGPAll(q.reward);
 }
 // 信頼度+2（上限100・討伐は上限なし）。ただし同行者募集はリーダーの依頼であり、PC自身の信頼にはならない
 if(!q.isCompanionHunt){
  changeTrust(q.fromTownId, 2, 'hunt');
 }
 // 翌月まで同じ町の討伐依頼を封じる
 if(!PC._huntCooldown) PC._huntCooldown = {};
 const d = getCurrentDate();
 const monthKey = d.year * 12 + d.month; // 年月を一意なキーに
 PC._huntCooldown[q.fromTownId] = monthKey;
 // キャッシュを無効化して掲示板を更新
 delete _tavernBoard[q.fromTownId];
 updateHUD();
 const story = document.getElementById('story');
 const trustNow = getTrust(q.fromTownId);
 const _rewardDisplay = q.isCompanionHunt ? _companionPay : q.reward;
 const _huntShareTxt = (()=>{
  if(q.isCompanionHunt){
   const _normalShare = Math.floor(q.reward / _huntPartyCountForPay);
   return `　<span style="color:#c8b8a0;font-size:calc(var(--font-sm) - 1px)">${_huntPartyCountForPay}人で山分け${_normalShare}GP/人のさらに半分（同行者募集のため）</span>`;
  }
  const _huntPartyCount = 1 + (PC.party||[]).filter(n=>n.con>0).length;
  const _huntShare = Math.floor(q.reward / _huntPartyCount);
  return _huntPartyCount > 1 ? `　<span style="color:#c8b8a0;font-size:calc(var(--font-sm) - 1px)">${_huntPartyCount}人で山分け：${_huntShare}GP/人</span>` : '';
 })();
 const _trustTxt = q.isCompanionHunt ? '' : `　${q.fromTownId ? (TOWNS[q.fromTownId]||{}).name||'' : ''}の信頼度 +2（→${trustNow}）`;
 story.innerHTML += `<div style="margin-top:12px;padding:10px;background:var(--nature-bg);border:1px solid var(--rust);border-radius:4px">
  <div style="color:#f0ece0;font-size:var(--font-base)"> 討伐完了！</div>
  <div style="color:#f0ece0;font-size:calc(var(--font-sm) + 1px);margin-top:4px">+${_rewardDisplay}GP${_huntShareTxt}${_trustTxt}</div>
 </div>`;
 const townNode = Object.entries({
  khazan:'TOWN_KHAZAN', port_argon:'TOWN_PORT_ARGON', stonehiem:'TOWN_STONEHIEM',
  elsia:'TOWN_ELSIA', verda:'TOWN_VERDA', rimholm:'TOWN_RIMHOLM', marakai:'TOWN_MARAKAI',
  al_rashid:'TOWN_AL_RASHID', oasis_fort:'TOWN_OASIS_FORT', saroon:'TOWN_SAROON',
  duna:'TOWN_DUNA', yeldun:'TOWN_YELDUN', frostpeak:'TOWN_FROSTPEAK', ashveil:'TOWN_ASHVEIL',
  valdheim:'TOWN_VALDHEIM', nifurvik:'TOWN_NIFURVIK', iskald:'TOWN_ISKALD',
  neria:'TOWN_NERIA', dorua:'TOWN_DORUA', sarpe:'TOWN_SARPE', nebra:'TOWN_NEBRA', kalvo:'TOWN_KALVO',
 }).find(([k])=>k===q.fromTownId);
 const backNode = townNode ? townNode[1] : 'TOWN_KHAZAN';
 showSaveToast(` 討伐完了！+${_rewardDisplay}GP　信頼度+2`);
 if(q.isTutorial){
  // チュートリアルの討伐完了：老NPCと共に、そのままチュートリアルを終える
  PC.party = [];
  updateHUD();
  renderChoices([{label:'▶ 続ける', go:'TUTORIAL_FAREWELL_AFTER_HUNT'}]);
  return;
 }
 if(q.isCompanionHunt){
  // 同行者募集の完了：一時パーティを解散し、リーダーの別れの台詞を添える
  story.innerHTML += `<div style="margin-top:8px;padding:10px;background:#0a0d08;border:1px solid #4a6a34;border-radius:4px">
   <div style="color:#c8e0a8;font-size:var(--font-sm)">${q.leaderPersonality.farewell}</div>
   <div style="color:#c8b8a0;font-size:calc(var(--font-sm) - 1px);margin-top:4px">${q.leader.name}たちと別れ、再びひとりになった。</div>
  </div>`;
  PC.party = [];
  updateHUD();
 }
 renderChoices([{label:'← 町に戻る', go: backNode}]);
}

// 洞穴討伐を依頼ボードから受注
function acceptHuntQuest(i){
 if(!PC.quests) PC.quests=[];
 if(PC.quests.filter(q=>q.status==='active').length>=5){
  alert('依頼は同時に5件までです！'); return;
 }
 const board = _tavernBoard[PC.town];
 const q = board && board[i];
 if(!q||q.type!=='hunt'){ alert('依頼データが見つかりません'); return; }
 PC.quests.push(q);
 board.splice(i, 1);
 showSaveToast(` 討伐依頼を受けました：${q.caveName}の${q.monsterName}`);
 _refreshTavernBoard(PC.town);
}

// 討伐同行者募集を受ける（この時点ではまだ出発しない。掲示板の「出発する」ボタンから開始する）
function acceptCompanionHuntQuest(i){
 if(!PC.quests) PC.quests=[];
 if((PC.party||[]).length > 0){
  showSaveToast('自分のパーティを率いている間は同行できません');
  return;
 }
 if(PC.quests.filter(q=>q.status==='active').length>=5){
  alert('依頼は同時に5件までです！'); return;
 }
 const board = _tavernBoard[PC.town];
 const q = board && board[i];
 if(!q || !q.isCompanionHunt){ alert('依頼データが見つかりません'); return; }
 board.splice(i, 1);
 PC.quests.push(q);
 showSaveToast(` 同行者募集を受けました：${q.caveName}の${q.monsterName}`);
 _refreshTavernBoard(PC.town);
}

// 討伐同行者募集を実際に開始する（掲示板の「出発する」ボタンから呼ぶ）
function startCompanionHuntQuest(questId){
 const q = (PC.quests||[]).find(qq=>qq.id===questId);
 if(!q || !q.isCompanionHunt){ return; }
 if((PC.party||[]).length > 0){
  showSaveToast('自分のパーティを率いている間は同行できません');
  return;
 }
 q._started = true;
 // リーダー・同行者を一時的にパーティへ加える（このクエストの間だけ）
 q.leader._isTemporaryCompanion = true;
 q.companion._isTemporaryCompanion = true;
 PC.party = [q.leader, q.companion];
 updateHUD();

 const story = document.getElementById('story');
 story.innerHTML = `<div style="border:1px solid #4a6a34;border-radius:4px;padding:12px;background:#0a0d08">
  <div style="color:#f0ece0;font-size:var(--font-base);margin-bottom:8px"> ${q.leader.name}の一団に同行する</div>
  <div style="color:#c8b8a0;font-size:var(--font-sm);margin-bottom:6px">${q.leaderPersonality.greet}</div>
  <div style="color:#c8b8a0;font-size:calc(var(--font-sm) - 1px)">目標：<span style="color:#f4ede0">${q.monsterName}</span>（${q.caveName}）</div>
 </div>`;
 renderChoices([
  {label:' 出発する', fn:()=>{ startHuntQuest(q.id); }},
 ]);
 scrollToTop();
}

// 松明切れ等で一度ダンジョンを出た同行討伐に、再びダンジョンへ戻る
function resumeCompanionHuntQuest(questId){
 const q = (PC.quests||[]).find(qq=>qq.id===questId);
 if(!q || !q.isCompanionHunt || !q._started){ return; }
 if(!q.ydDungeon){ showSaveToast('依頼データが見つかりません'); return; }
 // パーティが（何らかの理由で）解散されていたら組み直す
 if((PC.party||[]).length === 0){
  q.leader._isTemporaryCompanion = true;
  q.companion._isTemporaryCompanion = true;
  PC.party = [q.leader, q.companion];
  updateHUD();
 }
 const torches = countTorches();
 const storyEl = document.getElementById('story');
 const torchMsg = torches > 0
  ? `<span style="color:#f0ece0"> 松明を ${torches}本 持っている。</span>`
  : `<span style="color:#e0d0d0"> 松明を持っていない！暗闇の中を進むことになる。</span>`;
 const total = q.ydDungeon.targetCount || 0;
 const killed = q.ydDungeon.killedKeys
  ? q.ydDungeon.killedKeys.filter(k=>PC[k]).length : 0;
 storyEl.innerHTML = `
  <div style="border:1px solid #4a6a34;border-radius:4px;padding:12px;background:#0a0d08">
   <div style="color:#f0ece0;font-size:var(--font-base);margin-bottom:8px"> ${q.leader.name}の一団と共にダンジョンへ戻る：${q.caveName}</div>
   <div style="color:#c8b8a0;font-size:calc(var(--font-sm) - 1px);margin-bottom:6px">目標：<span style="color:#f4ede0">${q.monsterName}</span>
    　討伐：<span style="color:${killed>=total?'var(--gold2)':'var(--dim)'}">${killed}/${total}体</span></div>
   <div style="font-size:var(--font-sm)">${torchMsg}</div>
  </div>`;
 renderChoices([
  { label:' 再突入する', fn:()=>{
   PC._yeldunDungeon = q.ydDungeon;
   initTorch();
   ydGoNode(q.ydDungeon.floors[1].entryNodeId, 1);
  }},
  { label:'← 酒場に戻る', fn:()=>{ go(currentNodeId); } },
 ]);
 scrollToTop();
}

// 同行配達依頼を受注する（この時点ではまだ出発しない）
function acceptCompanionDeliveryQuest(i){
 if(!PC.quests) PC.quests=[];
 if((PC.party||[]).length > 0){
  showSaveToast('自分のパーティを率いている間は同行できません');
  return;
 }
 if(PC.quests.filter(q=>q.status==='active').length>=5){
  alert('依頼は同時に5件までです！'); return;
 }
 const board = _tavernBoard[PC.town];
 const q = board && board[i];
 if(!q || !q.isCompanionDelivery){ alert('依頼データが見つかりません'); return; }
 board.splice(i, 1);
 PC.quests.push(q);
 const destName = (TOWNS[q.toTownId]||{}).name || q.toTownId;
 showSaveToast(` 同行配達依頼を受けました：${destName}まで`);
 _refreshTavernBoard(PC.town);
}

// 同行配達依頼の「今の区間」の旅を開始する。到着時、最終目的地かどうかで処理を分岐する
function startCompanionDeliveryLeg(questId){
 const q = (PC.quests||[]).find(qq=>qq.id===questId);
 if(!q){ return; }
 if(!q._started){
  // 掲示板の「出発する」ボタンから最初に呼ばれた場合：まずパーティに加える
  if((PC.party||[]).length > 0){
   showSaveToast('自分のパーティを率いている間は同行できません');
   return;
  }
  q._started = true;
  q.leader._isTemporaryCompanion = true;
 q.companion._isTemporaryCompanion = true;
 PC.party = [q.leader, q.companion];
  updateHUD();
 }
 const fromId = q.route[q.legIndex];
 const toId = q.route[q.legIndex+1];
 if(!toId){ return; } // 既に最終目的地（呼び出し側のバグ避け）
 const route = getRoute(fromId, toId);
 if(!route){ return; }
 const days = route.days.walk!=null ? route.days.walk : route.days.coach;
 const isFinalLeg = (q.legIndex+1) === q.route.length-1;

 const from = TOWNS[fromId], to = TOWNS[toId];
 PC.town = toId;
 updateHUD();
 drawScene('travel');
 showTravelImage('walk', fromId, toId);
 const storyEl = document.getElementById('story');
 if(storyEl) storyEl.innerHTML = '';
 const tpw = document.getElementById('travel-progress-wrap');
 if(tpw){
  tpw.style.display = '';
  document.getElementById('travel-progress-bar').style.width = '0%';
  document.getElementById('travel-progress-dot').style.left = '0%';
  document.getElementById('travel-latest').textContent = '';
  document.getElementById('travel-progress-label').innerHTML =
   ` 徒歩　<span style="color:#f0ece0">${from.name}</span> → <span style="color:#f0ece0">${to.name}</span>　<span id="travel-day-count" style="color:#e0d8c8">0/${days}日</span>`;
 }
 renderChoices([]);
 advanceDaysAnimated(days, ()=>{
  if(isFinalLeg){
   _finishCompanionDelivery(q);
  } else {
   q.legIndex++;
   q.isPausedAt = toId;
   const leaderName = q.leaderPersonality ? q.leader.name : 'リーダー';
   PC.party = []; // 一時的に解散し、経由町では自由行動
   updateHUD();
   // 必ず一泊（時刻を朝にリセットし、1日消費）
   GAME_TIME.totalDays++;
   GAME_TIME.hour = 6;
   updateTimebar();
   checkAging();
   // go()呼び出し前に_pendingMsgへ積んでおく（町ノードのtxtの前に確実に表示される）
   PC._pendingMsg = (PC._pendingMsg||'') + `<div style="border:1px solid #345a6a;border-radius:4px;padding:10px;background:#080a0d;margin-bottom:10px">
    <span style="color:#a8d0e0">${to.name}に到着した。${leaderName}たちは宿を取り、一晩休むことにしたようだ。</span><br>
    <span style="color:#c8b8a0;font-size:calc(var(--font-sm) - 1px)">明日以降、この町の酒場に行けば旅を再開できる。</span>
   </div>`;
   go('TOWN_'+toId.toUpperCase());
  }
 });
 // advanceDaysAnimatedが旅ログ欄を作った直後に出発メッセージを追加する
 travelLog(`<span style="color:#b8a890">徒歩で <span style="color:#f0ece0">${from.name}</span> → <span style="color:#f0ece0">${to.name}</span> へ出発。所要: ${days}日　費用: 0GP</span>`);
 // advanceDaysAnimatedはcrossRegionをfalse固定で初期化するため、地方またぎ移動なら正しく上書きする
 // （travelStateは上のadvanceDaysAnimated呼び出し内で同期的に作成済みなのでここで安全に設定できる）
 if(travelState) travelState.crossRegion = getRegionKey(fromId) !== getRegionKey(toId);
}

// 同行配達依頼の完了処理（最終目的地に到着した時に呼ぶ）
function _finishCompanionDelivery(q){
 const partyCount = 1 + (PC.party||[]).filter(n=>n.con>0).length;
 const share = Math.floor(Math.floor(q.reward / partyCount) / 2);
 gainGP(share, PC);
 q.status = 'completed';
 PC.quests = (PC.quests||[]).filter(qq=>qq.id !== q.id);
 PC.party = [];
 updateHUD();
 const leaderName = q.leader.name;
 PC._pendingMsg = (PC._pendingMsg||'') + `<div style="border:1px solid #345a6a;border-radius:4px;padding:10px;background:#080a0d;margin-bottom:10px">
  <span style="color:#a8d0e0">目的地に到着した。無事に荷物を届け終えた${leaderName}が礼を言う。</span><br>
  <span style="color:#c8b8a0">「${q.leaderPersonality.farewell}」</span><br>
  <span style="color:#e8e4d8">報酬 ${share}GP を受け取った。</span>
 </div>`;
 go('TOWN_'+q.toTownId.toUpperCase());
}

// 経由町の酒場で、保留中の同行配達依頼を再開する選択肢を返す（酒場ノードから呼ぶ）
function getCompanionDeliveryResumeChoices(townId){
 const paused = (PC.quests||[]).filter(q=>q.type==='companionDelivery' && q.status==='active' && q.isPausedAt===townId);
 return paused.map(q=>{
  const destName = (TOWNS[q.toTownId]||{}).name || q.toTownId;
  const nextTownId = q.route[q.legIndex+1];
  const nextName = (TOWNS[nextTownId]||{}).name || nextTownId;
  return {
   label:` 旅を再開する：${destName}へ（次は${nextName}）`,
   fn:()=>{
    q.isPausedAt = null;
    q.leader._isTemporaryCompanion = true;
 q.companion._isTemporaryCompanion = true;
 PC.party = [q.leader, q.companion];
    updateHUD();
    startCompanionDeliveryLeg(q.id);
   },
  };
 });
}

// 保留中の同行配達依頼を、酒場に戻らず他の町へ移動しようとした際に自動失敗させる
function checkCompanionDeliveryAbandon(){
 const paused = (PC.quests||[]).filter(q=>q.type==='companionDelivery' && q.status==='active' && q.isPausedAt);
 paused.forEach(q=>{
  if(q.isPausedAt !== PC.town){
   q.status = 'completed'; // 失敗として扱い、依頼一覧から除去
   PC.quests = (PC.quests||[]).filter(qq=>qq.id !== q.id);
   showSaveToast(`${q.leader.name}たちとはぐれてしまった……同行配達は失敗に終わった`);
  }
 });
}

// 受注中の討伐クエストを実行できる町ノードから呼ぶ
function getActiveHuntChoices(townId){
 const hunts = (PC.quests||[]).filter(q=>q.type==='hunt' && q.status==='active' && q.fromTownId===townId);
 return hunts.map(q=>{
  const total  = q.rooms?.reduce((s,r)=>s+r.count,0)||0;
  const killed = q.ydDungeon?.killedKeys?.filter(k=>PC[k]).length||0;
  const prog   = q.ydDungeon ? ` （${killed}/${total}体討伐済み）` : '';
  return {
  label:` 討伐へ出発：${q.caveName}（${q.monsterName}${prog}）`,
  fn:()=>startHuntQuest(q.id),
  };
 });
}

function calcQuestReward(fromId, toId){
 const walk = calcMinTravelDays(fromId, toId) || 12;
 // 報酬は従来の2/3（端数切り捨て）
 let base;
 if(walk <= 20) base = 3  + Math.floor(Math.random()*8);  // 3〜10GP
 else if(walk <= 50) base = 13 + Math.floor(Math.random()*14); // 13〜26GP
 else base = 33 + Math.floor(Math.random()*34);                // 33〜66GP（地方またぎ遠距離）
 // 地方状態システム：物流途絶度に応じた割増（最大1.3倍）
 const mult = regionConditionRewardMult(getRegionKey(fromId), 'logi');
 return Math.floor(base * mult);
}

// 護衛クエスト報酬：配達報酬の1.15倍
function calcEscortReward(fromId, toId){
 const base = 5 + Math.floor(Math.random()*11); // 5〜15GP固定
 // 地方状態システム：物流途絶度に応じた割増（最大1.3倍）
 const mult = regionConditionRewardMult(getRegionKey(fromId), 'logi');
 return Math.floor(base * mult);
}

const ESCORT_TYPES = [
 { type:'merchant',  label:'商人',       titleFn:(name)=>`商人の${name}` },
 { type:'trader',    label:'行商人',     titleFn:(name)=>`行商人の${name}` },
 { type:'official',  label:'役人',       titleFn:(name)=>`${name}書記官` },
 { type:'messenger', label:'神殿の使者', titleFn:(name)=>`神殿使者の${name}` },
];

function generateEscortQuest(fromTownId){
 const regionTowns = getRegionTowns(fromTownId);
 const otherTowns = regionTowns.filter(id=>id!==fromTownId);
 const reachable = otherTowns.filter(id=>calcMinTravelDays(fromTownId,id)!=null);
 if(!reachable.length) return null;
 const toTownId = reachable[Math.floor(Math.random()*reachable.length)];
 const etype = ESCORT_TYPES[Math.floor(Math.random()*ESCORT_TYPES.length)];
 const clientName = pickNPC();
 const escort = { id: Date.now()+Math.random(), type:'escort', status:'active',
  fromTownId, toTownId,
  escortType: etype.type,
  escortLabel: etype.label,
  escortName: etype.titleFn(clientName),
  clientName,
  reward: calcEscortReward(fromTownId, toTownId),
  deadlineDays: calcQuestDeadline(fromTownId, toTownId),
  issuedDay: GAME_TIME.totalDays,
  crossRegion: false,
 };
 return escort;
}

// 期限計算：徒歩日数×往復×余裕係数
function calcQuestDeadline(fromId, toId){
 const walk = calcMinTravelDays(fromId, toId) || 12;
 // 往復+2割の余裕（切り上げ5日単位）
 const raw = Math.ceil(walk * 2 * 1.2);
 return Math.ceil(raw / 5) * 5;
}

// 地方またぎ宅配クエスト生成
function generateCrossRegionDeliveryQuest(fromTownId){
 // 別地方の町を候補に
 const myRegion = getRegionKey(fromTownId);
 const otherTowns = Object.keys(TOWNS).filter(id=>{
  return id !== fromTownId && getRegionKey(id) !== myRegion && calcMinTravelDays(fromTownId,id) != null;
 });
 if(!otherTowns.length) return null;
 const toTownId = otherTowns[Math.floor(Math.random()*otherTowns.length)];
 const destType = DELIVERY_DEST_TYPES[Math.floor(Math.random()*DELIVERY_DEST_TYPES.length)];
 const item = DELIVERY_ITEMS[Math.floor(Math.random()*DELIVERY_ITEMS.length)];
 const clientName = pickNPC();
 const receiverName = pickNPC([clientName]);
 const reward = calcQuestReward(fromTownId, toTownId);
 const deadlineDays = calcQuestDeadline(fromTownId, toTownId);
 return {
  id: Date.now() + Math.random(),
  type: 'delivery',
  fromTownId, toTownId,
  destType: destType.key, destLabel: destType.label, destIcon: destType.icon,
  item, clientName, receiverName,
  reward, deadlineDays,
  issuedDay: GAME_TIME.totalDays,
  status: 'active',
  crossRegion: true,
 };
}

// 買い付けクエスト生成（他地方の特産品を買って持ち帰る）
function generatePurchaseQuest(fromTownId){
 const myRegion = getRegionKey(fromTownId);
 // 他地方のspecialtyをランダムに選ぶ
 const otherRegions = Object.keys(REGION_SPECIALTIES).filter(r => r !== myRegion);
 if(!otherRegions.length) return null;
 const targetRegion = otherRegions[Math.floor(Math.random()*otherRegions.length)];
 const specialties = REGION_SPECIALTIES[targetRegion];
 const spec = specialties[Math.floor(Math.random()*specialties.length)];
 const regionTowns = REGIONS[targetRegion] || [];
 const reachable = regionTowns.filter(id => calcMinTravelDays(fromTownId,id) != null);
 if(!reachable.length) return null;
 const clientName = pickNPC();
 const walk = Math.min(...reachable.map(id=>calcMinWalkDays(fromTownId,id)||999));
 const deadlineDays = Math.ceil(walk * 2 * 1.3 / 5) * 5;
 // 持ち込み価格：依頼元地方と産地地方の距離で決まる（calcSpecialtySellPriceと同じ計算）
 const dist = getRegionDistance(targetRegion, myRegion);
 const deliveryPrice = Math.round(spec.baseCost * (1 + dist));
 // 報酬：持ち込み価格の約6.7%（従来10%の2/3）
 const reward = Math.round(deliveryPrice * 0.067);
 return {
  id: Date.now() + Math.random(),
  type: 'purchase',
  fromTownId,
  targetRegion,
  specName: spec.name,
  specIcon: spec.icon,
  specBaseCost: spec.baseCost,
  deliveryPrice, // 持ち込み価格（距離補正済み）
  clientName,
  reward,
  deadlineDays,
  issuedDay: GAME_TIME.totalDays,
  status: 'active',
  crossRegion: true,
 };
}

// 同地方内宅配クエスト生成
function generateQuest(fromTownId){
 const regionTowns = getRegionTowns(fromTownId);
 const otherTowns = regionTowns.filter(id=>id!==fromTownId);
 const reachable = otherTowns.filter(id=>calcMinTravelDays(fromTownId,id)!=null);
 const candidates = reachable.length > 0 ? reachable : Object.keys(TOWNS).filter(id=>id!==fromTownId && getRegionKey(id)===getRegionKey(fromTownId));
 const toTownId = candidates[Math.floor(Math.random()*candidates.length)];
 const destType = DELIVERY_DEST_TYPES[Math.floor(Math.random()*DELIVERY_DEST_TYPES.length)];
 const item = DELIVERY_ITEMS[Math.floor(Math.random()*DELIVERY_ITEMS.length)];
 const clientName = pickNPC();
 const receiverName = pickNPC([clientName]);
 const reward = calcQuestReward(fromTownId, toTownId);
 const deadlineDays = calcQuestDeadline(fromTownId, toTownId);
 return {
  id: Date.now() + Math.random(),
  type: 'delivery',
  fromTownId, toTownId,
  destType: destType.key, destLabel: destType.label, destIcon: destType.icon,
  item, clientName, receiverName,
  reward, deadlineDays,
  issuedDay: GAME_TIME.totalDays,
  status: 'active',
  crossRegion: false,
 };
}

// 期限チェック（毎日更新で呼ぶ）
function checkQuestDeadlines(){
 if(!PC.quests) return;
 const failed = [];
 PC.quests.forEach(q=>{
 if(q.status!=='active') return;
 const elapsed = GAME_TIME.totalDays - q.issuedDay;
 if(elapsed > q.deadlineDays){ q.status='failed'; failed.push(q); }
 });
 PC.quests = PC.quests.filter(q=>q.status==='active');
 failed.forEach(q=>{
  if(q.type === 'hunt'){
   showQuestFailToast(` 討伐期限切れ：${q.caveName||'洞穴'}（${q.clientName}から）`);
  } else if(q.type === 'purchase'){
   showQuestFailToast(` 期限切れ：${q.specName}の買い付け（${q.clientName}から）`);
  } else if(q.type === 'escort'){
   // 護衛失敗：依頼元にペナルティフラグ
   const pen = (q.reward||0) * 10;
   PC._questPenalties = PC._questPenalties || {};
   PC._questPenalties[q.fromTownId] = PC._questPenalties[q.fromTownId] || 0;
   PC._questPenalties[q.fromTownId] += pen;
   changeAlignment(-5, -5); // 護衛失敗：悪+5/混沌+5
   showQuestFailToast(` 護衛失敗：${q.escortName}の護衛（期限切れ）罰金${pen}GP`);
  } else {
   // 配達失敗：依頼元にペナルティフラグ
   const pen = (q.reward||0) * 10;
   PC._questPenalties = PC._questPenalties || {};
   PC._questPenalties[q.fromTownId] = PC._questPenalties[q.fromTownId] || 0;
   PC._questPenalties[q.fromTownId] += pen;
   changeAlignment(-3, -3); // 配達失敗：悪+3/混沌+3
   changeTrust(q.toTownId||PC.town, -2);
   showQuestFailToast(` 期限切れ：${q.item||'荷物'}（${(TOWNS[q.toTownId]||{name:q.toTownId||'?'}).name}宛）罰金${pen}GP`);
  }
 });
}

function showQuestFailToast(msg){
 let el=document.getElementById('quest-fail-toast');
 if(!el){
 el=document.createElement('div'); el.id='quest-fail-toast';
 el.style.cssText='position:fixed;bottom:70px;left:50%;transform:translateX(-50%);background:#2a0000;border:2px solid #cc2222;color:#e0d0d0;font-family:system-ui,sans-serif;font-size:calc(var(--font-sm) - 2px);padding:10px 18px;border-radius:4px;z-index:9999;pointer-events:none;transition:opacity .4s;text-align:center;max-width:90vw';
 document.body.appendChild(el);
 }
 el.innerHTML=msg; el.style.opacity='1';
 clearTimeout(el._t); el._t=setTimeout(()=>{ el.style.opacity='0'; },4000);
}

// 配達完了チェック（届け先の街の対応する店に入ったとき呼ぶ）
// returns: 完了したクエスト or null
// 街に到着したとき全配達依頼をチェック（go関数から呼ぶ）
function checkAllDeliveries(townId){
 if(!PC.quests) return [];
 const completed = [];
 PC.quests.forEach(q=>{
  if(q.status !== 'active') return;
  if(q.type === 'purchase'){
   // 買い付け：依頼元の町に戻り、かつ対象特産品を持っている
   if(q.fromTownId === townId){
    const inv = PC.invSpecialties || [];
    const idx = inv.findIndex(s => s.name === q.specName);
    if(idx >= 0){
     inv.splice(idx, 1); // 特産品を消費
     q.status = 'completed';
     completed.push(q);
     recordRegionQuest(q.fromTownId, 'purchase');
    }
   }
  } else if(q.type === 'escort'){
   // 護衛：目的地に到着で完了
   if(q.toTownId === townId){
    q.status = 'completed';
    completed.push(q);
    recordRegionQuest(q.fromTownId, 'escort');
   }
  } else {
   // 宅配（密売配達含む）：目的地の町に着いた
   if(q.toTownId === townId){
    q.status = 'completed';
    completed.push(q);
    recordRegionQuest(q.fromTownId, q.type==='contraband' ? 'contraband' : (q.crossRegion ? 'delivery_cross' : 'delivery_local'));
   }
  }
 });
 if(!completed.length) return [];
 completed.forEach(q=>{
  if(q.type === 'purchase'){
   // 持ち込み価格（距離補正済み）＋報酬を支払い
   const deliveryPrice = q.deliveryPrice || q.specBaseCost;
   const total = deliveryPrice + q.reward;
   q._deliveryPrice = deliveryPrice; // popDeliveryMsg用に保存
   gainGPAll(total);
   gainAPAll(10);
  } else if(q.type === 'escort'){
   gainGPAll(q.reward);
   changeTrust(q.toTownId||PC.town, 1, 'delivery');
   gainAPAll(8);
  } else if(q.type === 'contraband'){
   gainGPAll(q.reward);
   changeWanted(q.toTownId||PC.town, 0.5);
   changeAlignment(-3, -3);
   gainAPAll(5);
  } else {
   gainGPAll(q.reward);
   changeTrust(q.toTownId||PC.town, 0.5, 'delivery'); // 宅配依頼完了で信頼度+0.5（上限49）
   gainAPAll(5);
  }
 });
 PC.quests = PC.quests.filter(q=>q.status==='active');
 updateHUD();
 PC._lastDeliveries = completed;
 return completed;
}

function popDeliveryMsg(){
 const list = PC._lastDeliveries || [];
 PC._lastDeliveries = [];
 if(!list.length) return '';
 return '<br>' + list.map(q=>{
  if(q.type === 'purchase'){
   const delPrice = q._deliveryPrice || q.deliveryPrice || q.specBaseCost;
   const total = delPrice + q.reward;
   return `<span style="color:#e8e4d8"> ${q.clientName}に「${q.specName}」を納品した！<br>　持ち込み価格${delPrice}GP + 手数料${q.reward}GP = <b>${total}GP</b>　経験値+10</span>`;
  }
  if(q.type === 'escort'){
   const escortThanks = [
    `「いやあ、助かったよ！ありがとうな」${q.escortName}は軽く手を振った。`,
    `「あなたに頼んで正解だった。また会えたら一杯奢らせてくれ」${q.escortName}はにっこり笑った。`,
    `「思ったより気楽な旅だったな。ありがとう」${q.escortName}は肩の荷が下りたように伸びをした。`,
    `「無事着いてよかった！ありがとうね」${q.escortName}は軽やかに言った。`,
    `「退屈しない旅だったよ。感謝する」${q.escortName}は笑いながら軽く会釈した。`,
   ];
   const thanksLine = escortThanks[Math.floor(Math.random()*escortThanks.length)];
   return `<span style="color:#e8e4d8"> ${q.escortName}を${(TOWNS[q.toTownId]||{name:q.toTownId}).name}へ無事に護衛した！<br>　報酬: ${q.reward}GP　経験値+8</span><br><span style="color:#c8b8a0;font-size:calc(var(--font-sm) - 1px)">${thanksLine}</span>`;
  }
  if(q.type === 'contraband'){
   return `<span style="color:#e8e4d8"> ${q.receiverName}に「${q.item}」を密かに届けた……<br>　報酬: ${q.reward}GP　${(TOWNS[q.toTownId]||{name:q.toTownId}).name}の手配度+0.5　経験値+5</span>`;
  }
  return `<span style="color:#e8e4d8"> ${q.receiverName}に「${q.item}」を届けた！<br>　報酬: ${q.reward}GP　経験値+5</span>`;
 }).join('<br>');
}

