// 町メニューに現在の時間帯を表示する（街区・裏路地探索で進んだGAME_TIME.hourをそのまま反映する。保持のみで進行はさせない）
function popTimeOfDayMsg(townId){
 const ph = villagePhase(getGameHour());
 const regionKey = townId ? getRegionKey(townId) : null;
 const weather = regionKey ? getTodayWeather(regionKey) : null;
 const weatherPart = weather ? `、${WEATHER_LABELS[weather] || weather}` : '';
 return `<br><span style="color:#a89880;font-size:calc(var(--font-sm) - 1px)">現在：${ph.label}${weatherPart}</span>`;
}

// 酒場のクエスト掲示板HTML生成
// 依頼の大分類（見やすさのため掲示板でグループ分けする用）
function _questCategory(type){
 if(type==='hunt' || type==='bounty' || type==='heroquest') return 'combat';
 if(type==='assassination' || type==='kidnapping') return 'shadow';
 return 'delivery'; // escort, delivery(local/cross), purchase, contraband
}
const _QUEST_CATEGORY_LABEL = { delivery:'配送系', combat:'討伐・戦闘系', shadow:'裏の依頼' };
const _QUEST_CATEGORY_ORDER = ['delivery','combat','shadow'];

// 依頼掲示板のカテゴリ見出し開閉状態（デフォルトは全て展開）
if(!window._questBoardOpenState) window._questBoardOpenState = {};
function _setQuestBoardOpen(key, isOpen){
 window._questBoardOpenState[key] = isOpen;
}
// 拠点メニューの開閉状態（デフォルトは折りたたみ）
if(!window._propMenuOpenState) window._propMenuOpenState = {};
function _propMenuSetOpen(key, isOpen){
 window._propMenuOpenState[key] = isOpen;
}
function _questBoardIsOpen(key){
 return window._questBoardOpenState[key] !== false;
}
function _questCategoryHeader(key, label){
 const isOpen = _questBoardIsOpen(key);
 return `<details ${isOpen?'open':''} ontoggle="_setQuestBoardOpen('${key}', this.open)" style="margin-bottom:4px">
  <summary style="cursor:pointer;color:#a89880;font-size:calc(var(--font-sm) - 1px);padding:4px 0;user-select:none">◆ ${label}</summary>
  <div style="padding-left:2px">`;
}

function renderQuestBoard(townId, board){
 if(!PC.quests) PC.quests=[];
 const active = PC.quests.filter(q=>q.status==='active');
 const canTake = active.length < 5;
 const LIMIT = 5;
 const cantTakeMsg = `（受注上限${LIMIT}件）`;

 // 地方状態システム：治安悪化度・住民流出度に応じた酒場の情景描写（側経路変数に格納し、各酒場ノードの固定説明文直後に挿入される）
 _tavernFlavorHtml = tavernRegionConditionFlavor(townId);

 let html = `<span class="gold" style="font-size:var(--font-base)"> 依頼掲示板</span><br><br>`;
 html += '@@QBTABS@@';   // タブ（最後に、各タブの件数と表示中のタブが決まってから差し込む）

 // 受注中（タブ：受注中）
 if(active.length>0){
  html += `<div class="qb-panel" data-tab="active"><span class="dim" style="font-size:var(--font-sm)">── 受注中（${active.length}/${LIMIT}件）──</span><br>`;
  const sortedActive = [...active].sort((a,b)=>
   _QUEST_CATEGORY_ORDER.indexOf(_questCategory(a.type)) - _QUEST_CATEGORY_ORDER.indexOf(_questCategory(b.type))
  );
  let _lastCat = null;
  sortedActive.forEach(q=>{
   const _cat = _questCategory(q.type);
   if(_cat !== _lastCat){
    if(_lastCat !== null) html += '</div></details>';
    html += _questCategoryHeader(`active_${_cat}`, _QUEST_CATEGORY_LABEL[_cat]);
    _lastCat = _cat;
   }
   const remain = q.deadlineDays - (GAME_TIME.totalDays - q.issuedDay);
   const urgColor = remain<=5?'#e0d0d0':remain<=15?'#e0d8d0':'#d8d0c0';
   const crossBadge = q.crossRegion ? `<span style="font-size:calc(var(--font-sm) - 2px);color:#c8b8a0;margin-left:4px"> 地方またぎ</span>` : '';
   if(q.type === 'escort'){
    const toName = (TOWNS[q.toTownId]||{name:q.toTownId}).name;
    html += `<div style="background:var(--ink);border:1px solid #484848;border-radius:3px;padding:8px;margin:5px 0;font-size:var(--font-sm)">
     <span style="color:#e0d8c8"> 護衛依頼</span>　${q.escortName}（${q.escortLabel}）<br>
    護衛先：<span style="color:#ece8e0">${toName}</span>　報酬: <span style="color:#f0ece0">${q.reward}GP</span>　残り<span style="color:${urgColor}">${remain}日</span>
    <div style="font-size:calc(var(--font-sm) - 2px);color:#c8b8a0;margin-top:4px">→ <b>${toName}</b>へ移動することで完了</div>
    </div>`;
   } else if(q.type === 'heroquest'){
    const isHere = q.fromTownId === townId;
    html += `<div style="background:#0e0e0e;border:1px solid #484848;border-radius:3px;padding:8px;margin:5px 0;font-size:var(--font-sm)">
     <span style="color:#f0ece0"> 英雄依頼</span>　${q.title}<br>
    依頼主：${q.clientName}　報酬: <span style="color:#f0ece0">${q.reward}GP</span>
    ${isHere ? `<button onclick="startHeroQuest(${JSON.stringify(q.id)})" style="margin-top:5px;width:100%;background:#150f06;border:1px solid #606060;color:#f0ece0;font-family:system-ui,sans-serif;font-size:calc(var(--font-sm) - 2px);padding:7px;cursor:pointer;border-radius:3px"> 出発する</button>` : `<div style="font-size:calc(var(--font-sm) - 2px);color:#c8b8a0;margin-top:4px">（依頼元：${(TOWNS[q.fromTownId]||{name:q.fromTownId}).name}で出発）</div>`}
    </div>`;
   } else if(q.isCompanionHunt){
    const totalCount = q.rooms.reduce((s,r)=>s+r.count,0);
    const isHere = q.fromTownId === townId;
    const notStarted = !q._started;
    const isOutside = q._started && !PC._yeldunDungeon; // 出発済みだが今はダンジョンの外にいる（松明切れ等で撤退した場合）
    let actionHtml;
    if(isHere && notStarted){
     actionHtml = `<button onclick="startCompanionHuntQuest(${JSON.stringify(q.id)})" style="margin-top:5px;width:100%;background:#150f06;border:1px solid #6a8a44;color:#e8e0d0;font-family:system-ui,sans-serif;font-size:calc(var(--font-sm) - 2px);padding:7px;cursor:pointer;border-radius:3px"> 出発する</button>`;
    } else if(isOutside){
     actionHtml = `<button onclick="resumeCompanionHuntQuest(${JSON.stringify(q.id)})" style="margin-top:5px;width:100%;background:#150f06;border:1px solid #6a8a44;color:#e8e0d0;font-family:system-ui,sans-serif;font-size:calc(var(--font-sm) - 2px);padding:7px;cursor:pointer;border-radius:3px"> ダンジョンに戻る</button>`;
    } else if(notStarted){
     actionHtml = `<div style="font-size:calc(var(--font-sm) - 2px);color:#c8b8a0;margin-top:4px">（依頼元：${(TOWNS[q.fromTownId]||{name:q.fromTownId}).name}で出発）</div>`;
    } else {
     actionHtml = `<div style="font-size:calc(var(--font-sm) - 2px);color:#c8b8a0;margin-top:4px">（討伐に向かっている）</div>`;
    }
    html += `<div style="background:#0a0d08;border:1px solid #4a6a34;border-radius:3px;padding:8px;margin:5px 0;font-size:var(--font-sm)">
     <span style="color:#c8e0a8">同行者募集</span>　${q.caveName}の<span style="color:var(--white)">${q.monsterName} ×${totalCount}</span><br>
    リーダー：${q.leader.name}　報酬: <span style="color:#f0ece0">${q.reward}GP</span>（山分け）
    ${actionHtml}
    </div>`;
   } else if(q.isCompanionDelivery){
    const destName = (TOWNS[q.toTownId]||{name:q.toTownId}).name;
    const isHere = q.fromTownId === townId;
    const notStarted = !q._started;
    html += `<div style="background:#080a0d;border:1px solid #345a6a;border-radius:3px;padding:8px;margin:5px 0;font-size:var(--font-sm)">
     <span style="color:#a8d0e0">同行配達依頼</span>　<span style="color:var(--white)">${destName}</span>まで<br>
    リーダー：${q.leader.name}　報酬: <span style="color:#f0ece0">${q.reward}GP</span>（山分け）
    ${(isHere && notStarted) ? `<button onclick="startCompanionDeliveryLeg(${JSON.stringify(q.id)})" style="margin-top:5px;width:100%;background:#150f06;border:1px solid #4a7a8a;color:#e8e0d0;font-family:system-ui,sans-serif;font-size:calc(var(--font-sm) - 2px);padding:7px;cursor:pointer;border-radius:3px"> 出発する</button>` : notStarted ? `<div style="font-size:calc(var(--font-sm) - 2px);color:#c8b8a0;margin-top:4px">（依頼元：${(TOWNS[q.fromTownId]||{name:q.fromTownId}).name}で出発）</div>` : `<div style="font-size:calc(var(--font-sm) - 2px);color:#c8b8a0;margin-top:4px">（道中）</div>`}
    </div>`;
   } else if(q.type === 'hunt'){
    const totalCount = q.rooms.reduce((s,r)=>s+r.count,0);
    const isHere = q.fromTownId === townId;
    html += `<div style="background:#0a1008;border:1px solid #585858;border-radius:3px;padding:8px;margin:5px 0;font-size:var(--font-sm)">
     <span style="color:#e8e0d0">討伐依頼</span>　${q.caveName}の<span style="color:var(--white)">${q.monsterName} ×${totalCount}</span><br>
    依頼主：${q.clientName}　報酬: <span style="color:#f0ece0">${q.reward}GP</span>　残り<span style="color:${urgColor}">${remain}日</span>
    ${isHere ? `<button onclick="startHuntQuest(${JSON.stringify(q.id)})" style="margin-top:5px;width:100%;background:#150f06;border:1px solid #606060;color:#f0ece0;font-family:system-ui,sans-serif;font-size:calc(var(--font-sm) - 2px);padding:7px;cursor:pointer;border-radius:3px"> 出発する</button>` : `<div style="font-size:calc(var(--font-sm) - 2px);color:#c8b8a0;margin-top:4px">（依頼元：${(TOWNS[q.fromTownId]||{name:q.fromTownId}).name}で出発）</div>`}
    </div>`;
   } else if(q.type === 'bounty'){
    const remain = q.deadlineDays - (GAME_TIME.totalDays - q.issuedDay);
    const urgColor = remain<=5?'#e0d0d0':remain<=15?'#e0d8d0':'#d8d0c0';
    const targetTown = q.targetTownId || q.fromTownId;
    const isHere = townId === targetTown;
    const targetTownName = q.targetTownName || (TOWNS[targetTown]||{name:targetTown}).name;
    const crossBadge2 = q.isCrossRegion ? `<span style="color:#c8b8a0;font-size:calc(var(--font-sm)-2px)"> 他地方</span>` : '';
    html += `<div style="background:#0e0e0e;border:1px solid #484848;border-radius:3px;padding:8px;margin:5px 0;font-size:var(--font-sm)">
     <span style="color:#f0ddd8">賞金首討伐</span>　${q.targetName}（${q.targetTitle}）${crossBadge2}<br>
    出没地：<span style="color:#e8e0d0">${targetTownName}</span>　依頼主：${q.clientName}<br>
    報酬: <span style="color:#f0ece0">${q.reward}GP</span>　残り<span style="color:${urgColor}">${remain}日</span>
    ${isHere ? `<div style="font-size:calc(var(--font-sm)-1px);color:#c8b8a0;margin-top:4px">（その他の行動 → 賞金首を探す）</div>` : `<div style="font-size:calc(var(--font-sm)-1px);color:#c8b8a0;margin-top:4px">→ <b>${targetTownName}</b>へ移動して「賞金首を探す」</div>`}
    </div>`;
   } else if(q.type === 'assassination'){
    const remain = q.deadlineDays - (GAME_TIME.totalDays - q.issuedDay);
    const urgColor = remain<=5?'#e0d0d0':remain<=15?'#e0d8d0':'#d8d0c0';
    const targetTown = q.targetTownId || q.fromTownId;
    const isHere = townId === targetTown;
    const targetTownName = q.targetTownName || (TOWNS[targetTown]||{name:targetTown}).name;
    const crossBadge2 = q.isCrossRegion ? `<span style="color:#c8b8a0;font-size:calc(var(--font-sm)-2px)"> 他地方</span>` : '';
    html += `<div style="background:#150808;border:1px solid #5a3030;border-radius:3px;padding:8px;margin:5px 0;font-size:var(--font-sm)">
     <span style="color:#e0a0a0"> 暗殺依頼</span>　${q.targetName}（${q.targetTitle}）${crossBadge2}<br>
    所在地：<span style="color:#e8e0d0">${targetTownName}</span>　依頼主：${q.clientName}<br>
    報酬: <span style="color:#f0ece0">${q.reward}GP</span>　残り<span style="color:${urgColor}">${remain}日</span>
    ${isHere ? `<div style="font-size:calc(var(--font-sm)-1px);color:#c8b8a0;margin-top:4px">（その他の行動 → 暗殺対象を追う）</div>` : `<div style="font-size:calc(var(--font-sm)-1px);color:#c8b8a0;margin-top:4px">→ <b>${targetTownName}</b>へ移動して「暗殺対象を追う」</div>`}
    </div>`;
   } else if(q.type === 'kidnapping'){
    const remain = q.deadlineDays - (GAME_TIME.totalDays - q.issuedDay);
    const urgColor = remain<=5?'#e0d0d0':remain<=15?'#e0d8d0':'#d8d0c0';
    const targetTown = q.targetTownId || q.fromTownId;
    const isHere = townId === targetTown;
    const targetTownName = q.targetTownName || (TOWNS[targetTown]||{name:targetTown}).name;
    const crossBadge2 = q.isCrossRegion ? `<span style="color:#c8b8a0;font-size:calc(var(--font-sm)-2px)"> 他地方</span>` : '';
    html += `<div style="background:#150808;border:1px solid #5a3030;border-radius:3px;padding:8px;margin:5px 0;font-size:var(--font-sm)">
     <span style="color:#e0a0a0"> 誘拐依頼</span>　${q.targetName}（${q.targetTitle}）${crossBadge2}<br>
    所在地：<span style="color:#e8e0d0">${targetTownName}</span>　依頼主：${q.clientName}<br>
    報酬: <span style="color:#f0ece0">${q.reward}GP</span>　残り<span style="color:${urgColor}">${remain}日</span>
    ${isHere ? `<div style="font-size:calc(var(--font-sm)-1px);color:#c8b8a0;margin-top:4px">（その他の行動 → 誘拐対象を追う）</div>` : `<div style="font-size:calc(var(--font-sm)-1px);color:#c8b8a0;margin-top:4px">→ <b>${targetTownName}</b>へ移動して「誘拐対象を追う」</div>`}
    </div>`;
   } else if(q.type === 'contraband'){
    html += `<div style="background:#100c08;border:1px solid #585848;border-radius:3px;padding:8px;margin:5px 0;font-size:var(--font-sm)">
    <span style="color:#c8b090"> 裏取引の配達</span>　<span style="color:#ece8e0">${(TOWNS[q.toTownId]||{name:q.toTownId||'?'}).name}</span>へ<br>
    「${q.item||'荷物'}」→<span style="color:#f0ece0">${q.receiverName||'?'}</span>宛　<span style="color:#f0ece0">${q.reward}GP</span>　残り<span style="color:${urgColor}">${remain}日</span>
    </div>`;
   } else if(q.type === 'purchase'){
    const regionName = {khazan_region:'カザーヌ地方',elmaria_region:'エルマリア地方',zahara_region:'ザハラ地方',draklim_region:'ドラクリム地方',valdheim_region:'ヴァルドヘイム地方',marea_region:'マレア地方'}[q.targetRegion]||q.targetRegion;
    html += `<div style="background:var(--info-bg);border:1px solid #585858;border-radius:3px;padding:8px;margin:5px 0;font-size:var(--font-sm)">
    ${q.specIcon} <span style="color:var(--white)">${regionName}</span>の特産品買い付け${crossBadge}<br>
    「${q.specName}」を購入して${(TOWNS[q.fromTownId]||{name:q.fromTownId}).name}に持ち帰る<br>
    持ち込み価格 約${q.deliveryPrice||q.specBaseCost}GP + 手数料<span style="color:#f0ece0">${q.reward}GP</span>　残り<span style="color:${urgColor}">${remain}日</span>
    </div>`;
   } else {
    html += `<div style="background:var(--info-bg);border:1px solid #484848;border-radius:3px;padding:8px;margin:5px 0;font-size:var(--font-sm)">
    ${q.destIcon||''} <span style="color:#ece8e0">${(TOWNS[q.toTownId]||{name:q.toTownId||'?'}).name}</span>の${q.destLabel||'配達'}${crossBadge}<br>
    「${q.item||'荷物'}」→<span style="color:#f0ece0">${q.receiverName||'?'}</span>宛　<span style="color:#f0ece0">${q.reward}GP</span>　残り<span style="color:${urgColor}">${remain}日</span>
    </div>`;
   }
  });
  if(_lastCat !== null) html += '</div></details>';
  html += '</div>';
 }

// 新規依頼（掲示板）
 const _newHdr = `<span class="dim" style="font-size:var(--font-sm)">── 新規依頼（${active.length}/${LIMIT}件受注中）──</span><br>`;
 const _panelOpen = key => `<div class="qb-panel" data-tab="${key}">${_newHdr}`;

 // 地方内・地方またぎで分けて表示（hunt/purchaseは別セクション）
 const localQuests = board.filter(q=>q.type==='delivery' && !q.crossRegion);
 const crossQuests = board.filter(q=>q.crossRegion);
 const escortQuests = board.filter(q=>q.type==='escort');
 const contrabandQuests = board.filter(q=>q.type==='contraband');
 const huntQuests = board.filter(q=>q.type==='hunt' && !q.isCompanionHunt);
 const companionHuntQuests = board.filter(q=>q.isCompanionHunt);
 const companionDeliveryQuests = board.filter(q=>q.isCompanionDelivery);
 const bountyQuests = board.filter(q=>q.type==='bounty');
 const assassinationQuests = board.filter(q=>q.type==='assassination');
 const kidnappingQuests = board.filter(q=>q.type==='kidnapping');

 if(!PC._huntCooldown) PC._huntCooldown = {};
 const _rd = getCurrentDate();
 const _rdKey = _rd.year * 12 + _rd.month;
 const _huntOnCooldown = (PC._huntCooldown[townId]||0) >= _rdKey;

 // ◆ 配送系 ──────────────────────
 const _hasDelivery = localQuests.length || escortQuests.length || crossQuests.length || contrabandQuests.length || companionDeliveryQuests.length;
 if(_hasDelivery){
  html += _panelOpen('delivery');
 }

 if(localQuests.length){
  html += `<span class="dim" style="font-size:calc(var(--font-sm) - 1px)">▸ 地方内</span><br>`;
  localQuests.forEach((q,_)=>{
   const i = board.indexOf(q);
   const btn = canTake
    ? `<button onclick="acceptQuest(${i})" style="margin-top:5px;width:100%;background:#0e1006;border:1px solid #606060;color:#f0ece0;font-family:system-ui,sans-serif;font-size:calc(var(--font-sm) - 2px);padding:7px;cursor:pointer;border-radius:3px"> 受ける</button>`
    : `<div style="margin-top:5px;font-size:calc(var(--font-sm) - 2px);color:#c8b8a0">${cantTakeMsg}</div>`;
   const destTown = TOWNS[q.toTownId]||{name:q.toTownId};
   html += `<div style="background:var(--ink);border:1px solid #484848;border-radius:3px;padding:9px;margin:5px 0;font-size:var(--font-sm)">
   <span style="color:#f0ece0">${q.clientName}</span>の依頼　${q.destIcon||''} <span style="color:#ece8e0">${destTown.name||'?'}</span>の${q.destLabel||'配達'}へ<br>
   「${q.item||'荷物'}」→<span style="color:#f0ece0">${q.receiverName||'?'}</span>宛　報酬: <span style="color:#f0ece0">${q.reward}GP</span>　期限: ${q.deadlineDays}日以内
   ${btn}</div>`;
  });
 }

 // 護衛依頼
 if(escortQuests.length){
  html += `<span style="color:#e0d8c8;font-size:calc(var(--font-sm) - 1px)">▸ 護衛依頼</span><br>`;
  escortQuests.forEach(q=>{
   const btn = canTake
    ? `<button onclick="acceptQuestById(${JSON.stringify(q.id)})" style="margin-top:5px;width:100%;background:var(--ink);border:1px solid #484848;color:#e0d8c8;font-family:system-ui,sans-serif;font-size:calc(var(--font-sm) - 2px);padding:7px;cursor:pointer;border-radius:3px"> 護衛を引き受ける</button>`
    : `<div style="margin-top:5px;font-size:calc(var(--font-sm) - 2px);color:#c8b8a0">${cantTakeMsg}</div>`;
   const toName = (TOWNS[q.toTownId]||{name:q.toTownId}).name;
   const walk = calcMinTravelDays(townId, q.toTownId) || '?';
   html += `<div style="background:var(--ink);border:1px solid #484848;border-radius:3px;padding:9px;margin:5px 0;font-size:var(--font-sm)">
   <span style="color:#e0d8c8"> ${q.escortLabel}の護衛</span>　${q.escortName}<br>
   目的地：<span style="color:#ece8e0">${toName}</span>　徒歩約${walk}日　報酬: <span style="color:#f0ece0">${q.reward}GP</span>　期限: ${q.deadlineDays}日以内
   ${btn}</div>`;
  });
 }

 if(crossQuests.length){
  html += `<span style="color:#c8b8a0;font-size:calc(var(--font-sm) - 1px)">▸ 他地方への依頼</span><br>`;
  crossQuests.forEach((q,_)=>{
   const i = board.indexOf(q);
   const btn = canTake
    ? `<button onclick="acceptQuest(${i})" style="margin-top:5px;width:100%;background:var(--ink);border:1px solid #585858;color:#f0ece0;font-family:system-ui,sans-serif;font-size:calc(var(--font-sm) - 2px);padding:7px;cursor:pointer;border-radius:3px">${q.type==='purchase'?' 買い付けを引き受ける':' 受ける'}</button>`
    : `<div style="margin-top:5px;font-size:calc(var(--font-sm) - 2px);color:#c8b8a0">${cantTakeMsg}</div>`;
   if(q.type === 'purchase'){
    const regionName = {khazan_region:'カザーヌ地方',elmaria_region:'エルマリア地方',zahara_region:'ザハラ地方',draklim_region:'ドラクリム地方',valdheim_region:'ヴァルドヘイム地方',marea_region:'マレア地方'}[q.targetRegion]||q.targetRegion;
    html += `<div style="background:#130e08;border:1px solid #484848;border-radius:3px;padding:9px;margin:5px 0;font-size:var(--font-sm)">
    <span style="color:#c8b8a0"> 買い付け依頼</span>　<span style="color:#f0ece0">${q.clientName}</span>から<br>
    ${q.specIcon} <span style="color:var(--white)">${regionName}</span>の「<b>${q.specName}</b>」を買ってきてほしい<br>
    持ち込み価格: 約<span style="color:#f0ece0">${q.deliveryPrice||q.specBaseCost}GP</span> + 手数料<span style="color:#f0ece0">${q.reward}GP</span>　期限: ${q.deadlineDays}日以内
    ${btn}</div>`;
   } else {
    const destTown = TOWNS[q.toTownId]||{name:q.toTownId};
    html += `<div style="background:#130e08;border:1px solid #484848;border-radius:3px;padding:9px;margin:5px 0;font-size:var(--font-sm)">
    <span style="color:#c8b8a0"> 地方またぎ配達</span>　<span style="color:#f0ece0">${q.clientName}</span>から<br>
    ${q.destIcon} <span style="color:#ece8e0">${destTown.name}</span>の${q.destLabel}へ「${q.item}」→<span style="color:#f0ece0">${q.receiverName}</span>宛<br>
    報酬: <span style="color:#f0ece0">${q.reward}GP</span>　期限: ${q.deadlineDays}日以内
    ${btn}</div>`;
   }
  });
 }

 if(contrabandQuests.length){
  html += `<span style="color:#c8b090;font-size:calc(var(--font-sm) - 1px)">▸ 裏の依頼（密売配達）</span><br>`;
  contrabandQuests.forEach(q=>{
   const i = board.indexOf(q);
   const btn = canTake
    ? `<button onclick="acceptQuest(${i})" style="margin-top:5px;width:100%;background:#100c08;border:1px solid #6a6040;color:#c8b090;font-family:system-ui,sans-serif;font-size:calc(var(--font-sm) - 2px);padding:7px;cursor:pointer;border-radius:3px"> 引き受ける</button>`
    : `<div style="margin-top:5px;font-size:calc(var(--font-sm) - 2px);color:#c8b8a0">${cantTakeMsg}</div>`;
   const destTown = TOWNS[q.toTownId]||{name:q.toTownId};
   html += `<div style="background:#100c08;border:1px solid #585848;border-radius:3px;padding:9px;margin:5px 0;font-size:var(--font-sm)">
   <span style="color:#c8b090"> 密売配達</span>　<span style="color:#f0ece0">${q.clientName}</span>の依頼　<span style="color:#ece8e0">${destTown.name||'?'}</span>へ<br>
   「${q.item||'荷物'}」→<span style="color:#f0ece0">${q.receiverName||'?'}</span>宛　報酬: <span style="color:#f0ece0">${q.reward}GP</span>　期限: ${q.deadlineDays}日以内
   ${btn}</div>`;
  });
 }
 if(companionDeliveryQuests.length){
  html += `<span style="color:#e8e0d0;font-size:calc(var(--font-sm) - 1px)">▸ 同行配達依頼</span><br>`;
  companionDeliveryQuests.forEach(q=>{
   const i = board.indexOf(q);
   const destName = (TOWNS[q.toTownId]||{}).name || q.toTownId;
   const btn = canTake
    ? `<button onclick="acceptCompanionDeliveryQuest(${i})" style="margin-top:5px;width:100%;background:var(--coal);border:1px solid #4a7a8a;color:#e8e0d0;font-family:system-ui,sans-serif;font-size:calc(var(--font-sm) - 2px);padding:7px;cursor:pointer;border-radius:3px"> 同行する</button>`
    : `<div style="margin-top:5px;font-size:calc(var(--font-sm) - 2px);color:#c8b8a0">${cantTakeMsg}</div>`;
   html += `<div style="background:#080a0d;border:1px solid #345a6a;border-radius:3px;padding:9px;margin:5px 0;font-size:var(--font-sm)">
   <span style="color:#a8d0e0"> 同行配達依頼</span>　<span style="color:#f0ece0">${q.leader.name}</span>が仲間を探している<br>
   <span style="color:var(--white)"><b>${destName}</b></span>までの荷物運びに同行してほしいそうだ（経由${q.route.length-2>0?q.route.length-2:0}町）<br>
   <span style="color:#d0c8b8;font-size:calc(var(--font-sm) - 1px)">報酬: <span style="color:#f0ece0">${q.reward}GP</span>（山分け）</span>
   ${btn}</div>`;
  });
 }

 if(_hasDelivery) html += '</div>';

 // ◆ 討伐・戦闘系 ──────────────────────
 const _hasCombat = _huntOnCooldown || huntQuests.length || bountyQuests.length || companionHuntQuests.length;
 if(_hasCombat){
  html += _panelOpen('combat');
 }

 if(_huntOnCooldown){
  html += `<div style="background:#0a0808;border:1px solid #332211;border-radius:3px;padding:8px;margin:5px 0;font-size:calc(var(--font-sm) - 1px);color:#c0b098">
    現在討伐依頼はありません。
  </div>`;
 }
 if(huntQuests.length){
  html += `<span style="color:#e8e0d0;font-size:calc(var(--font-sm) - 1px)">▸ 討伐依頼</span><br>`;
  huntQuests.forEach(q=>{
   const i = board.indexOf(q);
   const totalCount = q.rooms.reduce((s,r)=>s+r.count,0);
   const btn = canTake
    ? `<button onclick="acceptQuest(${i})" style="margin-top:5px;width:100%;background:var(--coal);border:1px solid #aa4400;color:#e8e0d0;font-family:system-ui,sans-serif;font-size:calc(var(--font-sm) - 2px);padding:7px;cursor:pointer;border-radius:3px"> 引き受ける</button>`
    : `<div style="margin-top:5px;font-size:calc(var(--font-sm) - 2px);color:#c8b8a0">${cantTakeMsg}</div>`;
   html += `<div style="background:#0d0800;border:1px solid var(--mud);border-radius:3px;padding:9px;margin:5px 0;font-size:var(--font-sm)">
   <span style="color:#e8e0d0"> 討伐依頼</span>　<span style="color:#f0ece0">${q.clientName}</span>から<br>
   ${q.caveName}に棲み着いた<span style="color:var(--white)"><b>${q.monsterName} ×${totalCount}</b></span>を討伐してほしい<br>
   <span style="color:#d0c8b8;font-size:calc(var(--font-sm) - 1px)">総CR：${q.totalMR}</span>　報酬: <span style="color:#f0ece0">${q.reward}GP</span> + <span style="color:#ece8d8">信頼度+2</span>　期限: ${q.deadlineDays}日以内
   ${btn}</div>`;
  });
 }

 if(companionHuntQuests.length){
  html += `<span style="color:#e8e0d0;font-size:calc(var(--font-sm) - 1px)">▸ 同行者募集</span><br>`;
  companionHuntQuests.forEach(q=>{
   const i = board.indexOf(q);
   const totalCount = q.rooms.reduce((s,r)=>s+r.count,0);
   const btn = canTake
    ? `<button onclick="acceptQuest(${i})" style="margin-top:5px;width:100%;background:var(--coal);border:1px solid #6a8a44;color:#e8e0d0;font-family:system-ui,sans-serif;font-size:calc(var(--font-sm) - 2px);padding:7px;cursor:pointer;border-radius:3px"> 同行する</button>`
    : `<div style="margin-top:5px;font-size:calc(var(--font-sm) - 2px);color:#c8b8a0">${cantTakeMsg}</div>`;
   html += `<div style="background:#0a0d08;border:1px solid #4a6a34;border-radius:3px;padding:9px;margin:5px 0;font-size:var(--font-sm)">
   <span style="color:#c8e0a8"> 同行者募集</span>　<span style="color:#f0ece0">${q.leader.name}</span>が仲間を探している<br>
   ${q.caveName}に棲み着いた<span style="color:var(--white)"><b>${q.monsterName} ×${totalCount}</b></span>の討伐に同行してほしいそうだ<br>
   <span style="color:#d0c8b8;font-size:calc(var(--font-sm) - 1px)">総CR：${q.totalMR}</span>　報酬: <span style="color:#f0ece0">${q.reward}GP</span>（山分け）　期限: ${q.deadlineDays}日以内
   ${btn}</div>`;
  });
 }

 if(bountyQuests.length){
  html += `<span style="color:#f0ddd8;font-size:calc(var(--font-sm) - 1px)">▸ 賞金首討伐依頼</span><br>`;
  bountyQuests.forEach(q=>{
   const i = board.indexOf(q);
   const btn = canTake
    ? `<button onclick="acceptBountyQuest(${i},'${townId}')" style="margin-top:5px;width:100%;background:#1a0400;border:1px solid #cc2200;color:#f0ddd8;font-family:system-ui,sans-serif;font-size:calc(var(--font-sm) - 2px);padding:7px;cursor:pointer;border-radius:3px"> 引き受ける</button>`
    : `<div style="margin-top:5px;font-size:calc(var(--font-sm) - 2px);color:#c8b8a0">${cantTakeMsg}</div>`;
   const _tName = q.targetTownName || (TOWNS[q.targetTownId||q.fromTownId]||{name:'不明'}).name;
   const _cross = q.isCrossRegion ? `<span style="color:#c8b8a0;font-size:calc(var(--font-sm)-2px)">  他地方</span>` : '';
   html += `<div style="background:#0d0400;border:1px solid #551100;border-radius:3px;padding:9px;margin:5px 0;font-size:var(--font-sm)">
   <span style="color:#f0ddd8"> 賞金首討伐</span>${_cross}　<span style="color:#f0ece0">${q.clientName}</span>から<br>
   <b style="color:#e8e0d0">${q.targetName}</b>（${q.targetTitle}・Lv${q.targetLevel}）を討伐してほしい<br>
   出没地：<span style="color:#e8e0d0">${_tName}</span><br>
   報酬: <span style="color:#f0ece0">${q.reward}GP</span> + <span style="color:#ece8d8">信頼度+5</span>　期限: ${q.deadlineDays}日以内
   ${btn}</div>`;
  });
 }
 if(_hasCombat) html += '</div>';

 // ◆ 裏の依頼 ──────────────────────
 const _hasShadow = assassinationQuests.length || kidnappingQuests.length;
 if(_hasShadow){
  html += _panelOpen('shadow');
 }

 if(assassinationQuests.length){
  html += `<span style="color:#e0a0a0;font-size:calc(var(--font-sm) - 1px)">▸ 暗殺依頼</span><br>`;
  assassinationQuests.forEach(q=>{
   const i = board.indexOf(q);
   const btn = canTake
    ? `<button onclick="acceptAssassinationQuest(${i},'${townId}')" style="margin-top:5px;width:100%;background:#150808;border:1px solid #7a3030;color:#e0a0a0;font-family:system-ui,sans-serif;font-size:calc(var(--font-sm) - 2px);padding:7px;cursor:pointer;border-radius:3px"> 引き受ける</button>`
    : `<div style="margin-top:5px;font-size:calc(var(--font-sm) - 2px);color:#c8b8a0">${cantTakeMsg}</div>`;
   const _tName = q.targetTownName || (TOWNS[q.targetTownId||q.fromTownId]||{name:'不明'}).name;
   const _cross = q.isCrossRegion ? `<span style="color:#c8b8a0;font-size:calc(var(--font-sm)-2px)">  他地方</span>` : '';
   html += `<div style="background:#150808;border:1px solid #5a3030;border-radius:3px;padding:9px;margin:5px 0;font-size:var(--font-sm)">
   <span style="color:#e0a0a0"> 暗殺依頼</span>${_cross}　<span style="color:#f0ece0">${q.clientName}</span>から<br>
   <b style="color:#e8e0d0">${q.targetName}</b>（${q.targetTitle}・Lv${q.targetLevel}）を始末してほしい<br>
   所在地：<span style="color:#e8e0d0">${_tName}</span><br>
   報酬: <span style="color:#f0ece0">${q.reward}GP</span> + <span style="color:#ece8d8">手配度+5</span>　期限: ${q.deadlineDays}日以内
   ${btn}</div>`;
  });
 }

 if(kidnappingQuests.length){
  html += `<span style="color:#e0a0a0;font-size:calc(var(--font-sm) - 1px)">▸ 誘拐依頼</span><br>`;
  kidnappingQuests.forEach(q=>{
   const i = board.indexOf(q);
   const btn = canTake
    ? `<button onclick="acceptKidnappingQuest(${i},'${townId}')" style="margin-top:5px;width:100%;background:#150808;border:1px solid #7a3030;color:#e0a0a0;font-family:system-ui,sans-serif;font-size:calc(var(--font-sm) - 2px);padding:7px;cursor:pointer;border-radius:3px"> 引き受ける</button>`
    : `<div style="margin-top:5px;font-size:calc(var(--font-sm) - 2px);color:#c8b8a0">${cantTakeMsg}</div>`;
   const _tName = q.targetTownName || (TOWNS[q.targetTownId||q.fromTownId]||{name:'不明'}).name;
   const _cross = q.isCrossRegion ? `<span style="color:#c8b8a0;font-size:calc(var(--font-sm)-2px)">  他地方</span>` : '';
   html += `<div style="background:#150808;border:1px solid #5a3030;border-radius:3px;padding:9px;margin:5px 0;font-size:var(--font-sm)">
   <span style="color:#e0a0a0"> 誘拐依頼</span>${_cross}　<span style="color:#f0ece0">${q.clientName}</span>から<br>
   <b style="color:#e8e0d0">${q.targetName}</b>（${q.targetTitle}）をさらってほしい<br>
   所在地：<span style="color:#e8e0d0">${_tName}</span><br>
   報酬: <span style="color:#f0ece0">${q.reward}GP</span> + <span style="color:#ece8d8">手配度+3</span>　期限: ${q.deadlineDays}日以内
   ${btn}</div>`;
  });
 }
 if(_hasShadow) html += '</div>';

 // ── タブの組み立て ──
 const _tabs = [
  {k:'active',   label:'受注中',       n:active.length, on:active.length>0},
  {k:'delivery', label:'配送系',       n:localQuests.length+escortQuests.length+crossQuests.length+contrabandQuests.length+companionDeliveryQuests.length, on:!!_hasDelivery},
  {k:'combat',   label:'討伐・戦闘系', n:huntQuests.length+companionHuntQuests.length+bountyQuests.length, on:!!_hasCombat},
  {k:'shadow',   label:'裏の依頼',     n:assassinationQuests.length+kidnappingQuests.length, on:!!_hasShadow},
 ].filter(t=>t.on);
 if(!_tabs.length) return html.replace('@@QBTABS@@', '');
 let _cur = window._questBoardTab;
 if(!_tabs.some(t=>t.k===_cur)){
  // 表示していたタブが無くなった（そのタブの最後の依頼を受けた等）ときは、「受注中」ではなく他の依頼タブを出す。
  // 依頼タブが1つも残っていない場合だけ「受注中」を出す
  const _pref = ['delivery','combat','shadow'];
  const _next = _pref.map(k=>_tabs.find(t=>t.k===k)).find(Boolean);
  _cur = (_next || _tabs[0]).k;
 }
 window._questBoardTab = _cur;   // 表示中のタブを覚えておく（再描画しても同じタブのまま）
 const _tabBar = `<div class="qb-tabbar" style="display:flex;flex-wrap:wrap;gap:4px;margin:0 0 8px">`
  + _tabs.map(t=>`<button type="button" class="qb-tab" data-tab="${t.k}" onclick="_questBoardSetTab('${t.k}')" style="${_questTabStyle(t.k===_cur)}">${t.label}${t.n ? `（${t.n}）` : ''}</button>`).join('')
  + `</div>`;
 // 表示中以外のパネルは隠しておく
 html = html.replace(/<div class="qb-panel" data-tab="(\w+)">/g, (m,k)=>k===_cur ? m : `<div class="qb-panel" data-tab="${k}" style="display:none">`);
 return html.replace('@@QBTABS@@', _tabBar);
}

function _questTabStyle(on){
 return `flex:1 1 auto;min-width:0;background:${on?'#2a2418':'#0e0e0e'};border:1px solid ${on?'#c8b070':'#484848'};color:${on?'#f0ece0':'#a89880'};font-family:system-ui,sans-serif;font-size:calc(var(--font-sm) - 1px);padding:7px 6px;cursor:pointer;border-radius:3px`;
}
function _questBoardSetTab(k){
 window._questBoardTab = k;
 document.querySelectorAll('.qb-panel').forEach(p=>{ p.style.display = (p.dataset.tab === k) ? '' : 'none'; });
 document.querySelectorAll('.qb-tab').forEach(b=>{ b.setAttribute('style', _questTabStyle(b.dataset.tab === k)); });
}

// 酒場ごとに掲示板boardをキャッシュ（txt/choicesで同一boardを共有）
const _tavernBoard = {};

function getTavernBoard(townId){
 const cached = _tavernBoard[townId];
 if(cached && cached.length > 0 && cached[0].issuedDay === GAME_TIME.totalDays){
  return cached;
 }
 const board = [];
 // 同地方内宅配 3件
 for(let i=0;i<3;i++) board.push(generateQuest(townId));
 // 護衛依頼 1件（受注済みがなければ）
 const hasActiveEscort = (PC.quests||[]).some(q=>q.type==='escort' && q.status==='active');
 if(!hasActiveEscort){
  const eq = generateEscortQuest(townId);
  if(eq) board.push(eq);
 }
 // 地方またぎ 2件（宅配か買い付けをランダムに）
 for(let i=0;i<2;i++){
  const q = Math.random()<0.5
   ? generateCrossRegionDeliveryQuest(townId)
   : generatePurchaseQuest(townId);
  if(q) board.push(q);
  else board.push(generateQuest(townId)); // フォールバック
 }
 // 討伐依頼 1件（クールダウン中・受注中は追加しない）
 if(!PC._huntCooldown) PC._huntCooldown = {};
 const _hd = getCurrentDate();
 const _curMonthKey = _hd.year * 12 + _hd.month;
 const hasActiveHunt = (PC.quests||[]).some(q=>q.type==='hunt' && q.status==='active' && q.fromTownId===townId);
 if(!hasActiveHunt && (PC._huntCooldown[townId] || 0) < _curMonthKey){
  board.push(generateHuntQuest(townId));
 }
 // 討伐同行者募集 1件（PCが自パーティを持たない場合のみ・討伐クールダウンを共有）
 if((PC.party||[]).length === 0 && !hasActiveHunt && (PC._huntCooldown[townId] || 0) < _curMonthKey && Math.random() < 0.5){
  board.push(generateCompanionHuntQuest(townId));
 }
 // 同行配達依頼 1件（PCが自パーティを持たず、この町を拠点とする配達依頼が受注中でない場合のみ）
 {
  const hasActiveDelivery = (PC.quests||[]).some(q=>q.type==='companionDelivery' && q.status==='active');
  if((PC.party||[]).length === 0 && !hasActiveDelivery && Math.random() < 0.4){
   const dq = generateCompanionDeliveryQuest(townId);
   if(dq) board.push(dq);
  }
 }
 // 賞金首依頼（中心都市のみ・クールダウン中でなく受注中でなければ1件）
 if(BOUNTY_CITIES.includes(townId)){
  if(!PC._bountyCooldown) PC._bountyCooldown = {};
  const hasBounty = (PC.quests||[]).some(q=>q.type==='bounty' && q.status==='active' && q.fromTownId===townId);
  const bountyOnCooldown = (PC._bountyCooldown[townId]||0) >= _curMonthKey;
  if(!hasBounty && !bountyOnCooldown) board.push(generateBountyQuest(townId));
 }
 // 暗殺依頼（受注中でなければ1件）
 {
  const hasAssassination = (PC.quests||[]).some(q=>q.type==='assassination' && q.status==='active' && q.fromTownId===townId);
  if(!hasAssassination) board.push(generateAssassinationQuest(townId));
 }
 // 誘拐依頼（受注中でなければ1件）
 {
  const hasKidnapping = (PC.quests||[]).some(q=>q.type==='kidnapping' && q.status==='active' && q.fromTownId===townId);
  if(!hasKidnapping) board.push(generateKidnappingQuest(townId));
 }
 // 麻薬・盗品の配達 1件
 board.push(generateContrabandQuest(townId));
 _tavernBoard[townId] = board;
 return board;
}

// 酒場を離れたらキャッシュをクリア
function clearTavernBoard(townId){
 delete _tavernBoard[townId];
}

function acceptQuestById(qid){
 if(!PC.quests) PC.quests=[];
 if(PC.quests.filter(q=>q.status==='active').length>=5){
  alert('依頼は同時に5件までです！'); return;
 }
 const board = _tavernBoard[PC.town];
 if(!board) return;
 const idx = board.findIndex(q=>q.id===qid);
 if(idx<0){ alert('依頼データが見つかりません'); return; }
 const q = board[idx];
 PC.quests.push(q);
 board.splice(idx, 1);
 // 護衛依頼は補充しない（受注済み含め1件まで）
 const toName = (TOWNS[q.toTownId]||{name:q.toTownId}).name;
 showSaveToast(` 護衛依頼を受けました：${q.escortName}（${toName}まで）`);
 _refreshTavernBoard(PC.town);
}

function acceptQuest(i){
 if(!PC.quests) PC.quests=[];
 if(PC.quests.filter(q=>q.status==='active').length>=5){
  alert('依頼は同時に5件までです！'); return;
 }
 const board = _tavernBoard[PC.town];
 const q = board && board[i];
 if(!q){ alert('依頼データが見つかりません'); return; }
 // 討伐同行者募集は専用ハンドラへ（通常の討伐ハンドラより先にチェック）
 if(q.isCompanionHunt){ acceptCompanionHuntQuest(i); return; }
 // 討伐クエストは専用ハンドラへ
 if(q.type==='hunt'){ acceptHuntQuest(i); return; }
 PC.quests.push(q);
 board.splice(i, 1);
 // 補充
 let replacement = null;
 if(q.type === 'escort'){
  replacement = generateEscortQuest(PC.town);
 } else if(q.type === 'contraband'){
  replacement = generateContrabandQuest(PC.town);
 } else if(q.crossRegion){
  replacement = Math.random()<0.5 ? generateCrossRegionDeliveryQuest(PC.town) : generatePurchaseQuest(PC.town);
 } else {
  replacement = generateQuest(PC.town);
 }
 if(replacement) board.push(replacement);
 const label = q.type==='purchase' ? `「${q.specName}」買い付け`
             : q.type==='escort'   ? `${q.escortName}の護衛（${(TOWNS[q.toTownId]||{name:q.toTownId}).name}まで）`
             : q.type==='contraband' ? `「${q.item}」の裏取引`
             : `「${q.item}」配達`;
 showSaveToast(` 依頼を受けました：${label}`);
 _refreshTavernBoard(PC.town);
}

function acceptBountyQuest(i, townId){
 if(!PC.quests) PC.quests=[];
 if(PC.quests.filter(q=>q.status==='active').length>=5){
  alert('依頼は同時に5件までです！'); return;
 }
 const board = _tavernBoard[townId||PC.town];
 const q = board && board[i];
 if(!q||q.type!=='bounty'){ alert('依頼データが見つかりません'); return; }
 q.status='active'; q.issuedDay=GAME_TIME.totalDays;
 PC.quests.push(q);
 board.splice(i,1);
 showSaveToast(` 賞金首討伐を引き受けた：${q.targetName}`);
 _refreshTavernBoard(townId||PC.town);
}

function acceptAssassinationQuest(i, townId){
 if(!PC.quests) PC.quests=[];
 if(PC.quests.filter(q=>q.status==='active').length>=5){
  alert('依頼は同時に5件までです！'); return;
 }
 const board = _tavernBoard[townId||PC.town];
 const q = board && board[i];
 if(!q||q.type!=='assassination'){ alert('依頼データが見つかりません'); return; }
 q.status='active'; q.issuedDay=GAME_TIME.totalDays;
 PC.quests.push(q);
 board.splice(i,1);
 showSaveToast(` 暗殺依頼を引き受けた：${q.targetName}`);
 _refreshTavernBoard(townId||PC.town);
}

function acceptKidnappingQuest(i, townId){
 if(!PC.quests) PC.quests=[];
 if(PC.quests.filter(q=>q.status==='active').length>=5){
  alert('依頼は同時に5件までです！'); return;
 }
 const board = _tavernBoard[townId||PC.town];
 const q = board && board[i];
 if(!q||q.type!=='kidnapping'){ alert('依頼データが見つかりません'); return; }
 q.status='active'; q.issuedDay=GAME_TIME.totalDays;
 PC.quests.push(q);
 board.splice(i,1);
 showSaveToast(` 誘拐依頼を引き受けた：${q.targetName}`);
 _refreshTavernBoard(townId||PC.town);
}

// 掲示板のみをスクロール位置を保ったまま再描画
function _refreshTavernBoard(townId){
 const sa = document.getElementById('scroll-area');
 const scrollY = sa ? sa.scrollTop : 0;
 const node = NODES[currentNodeId];
 if(node){
  const txt = typeof node.txt === 'function' ? node.txt() : node.txt;
  document.getElementById('story').innerHTML = txt || '';
  const ch = typeof node.choices === 'function' ? node.choices() : node.choices;
  renderChoices(ch || []);
 }
 updateHUD();
 if(sa) sa.scrollTop = scrollY;
}

function reportBountyQuestFromBoard(townId){
 const done = reportBountyQuest(townId);
 if(done){ go(currentNodeId); }
 else { showSaveToast('討伐が完了していません'); }
}

function getQuestBoardChoices(backNode){
 const townId = backNode.replace(/^TOWN_/, '').toLowerCase();
 const resumeChoices = getCompanionDeliveryResumeChoices(townId);
 const tutorialResumeChoices = getTutorialDeliveryResumeChoice(townId);
 const tutorialHomecomingChoices = getTutorialHomecomingResumeChoice(townId);
 return [...tutorialResumeChoices, ...tutorialHomecomingChoices, ...resumeChoices, {label:'← 戻る', go: backNode}];
}

function getRoute(fromId, toId){
 const key1 = `${fromId}_${toId}`;
 const key2 = `${toId}_${fromId}`;
 return ROUTES[key1] || ROUTES[key2] || null;
}

// ══════════════════════════════════════════
// 世界的大地震システム
// 30〜100年に一度、ランダムな地方（ただし前回発生した地方とPCが現在いる地方は除く）で
// 大地震が発生する。震源となった町へ通じる陸上ルート（徒歩・乗合馬車。船は対象外）の
// 移動日数が一時的に増加し、年月とともに段階的に平常へ回復していく。
// 発生時の演出は無く、プレイヤーは酒場の噂を通じてのみ気づくことができる。
// ══════════════════════════════════════════

// 大地震システムの初期化（初回のみ・次回発生予定日をランダムに設定）
function initWorldEarthquake(){
 if(!PC._worldEarthquake){
  PC._worldEarthquake = {
   nextDueDay: GAME_TIME.totalDays + (30 + Math.floor(Math.random()*71)) * DAYS_PER_YEAR, // 30〜100年後
   lastRegionKey: null,
   current: null, // { regionKey, townId, dayOccurred }
  };
 }
}

// 発生予定日を過ぎていれば大地震を発生させる（何度呼び出しても安全＝冪等。旅立ち時・酒場で話す時に呼ばれる）
function checkWorldEarthquake(){
 if(!PC._worldEarthquake) initWorldEarthquake();
 const eq = PC._worldEarthquake;
 if(GAME_TIME.totalDays < eq.nextDueDay) return;

 // 発生対象地方を選ぶ：前回発生した地方と、PCが現在いる地方を除外する
 const pcRegionKey = getRegionKey(PC.town);
 const allRegionKeys = Object.keys(REGIONS);
 let pool = allRegionKeys.filter(k => k !== eq.lastRegionKey && k !== pcRegionKey);
 if(pool.length === 0) pool = allRegionKeys.filter(k => k !== pcRegionKey);
 if(pool.length === 0) pool = allRegionKeys;
 const regionKey = pool[Math.floor(Math.random()*pool.length)];

 // 震源となる町を地方内からランダムに選ぶ
 const towns = REGIONS[regionKey] || [];
 const townId = towns.length > 0 ? towns[Math.floor(Math.random()*towns.length)] : null;

 eq.current = { regionKey, townId, dayOccurred: GAME_TIME.totalDays };
 eq.lastRegionKey = regionKey;
 eq.nextDueDay = GAME_TIME.totalDays + (30 + Math.floor(Math.random()*71)) * DAYS_PER_YEAR;

 // 地方状態システム：被災地方に一度きりの衝撃（物流途絶度・住民流出度）を与える（マレア地方等スコープ外なら無視）
 if(typeof REGION_CONDITION_SCOPE !== 'undefined' && REGION_CONDITION_SCOPE.includes(regionKey)){
  ensureRegionCondition();
  const clamp = v => Math.max(0, Math.min(100, v));
  const c = PC._regionCondition[regionKey];
  c.logi   = clamp(c.logi   + 15);
  c.exodus = clamp(c.exodus + 8);
 }
}

// fromId⇔toId間のルートが、直近の大地震の震源町に接続する陸上ルートであれば、
// 発生からの経過年数に応じた移動日数倍率を返す（対象外・平常時は1.0）
function worldEarthquakeRouteMultiplier(fromId, toId){
 const eq = PC._worldEarthquake;
 if(!eq || !eq.current || !eq.current.townId) return 1.0;
 const cur = eq.current;
 if(fromId !== cur.townId && toId !== cur.townId) return 1.0;
 const years = Math.floor((GAME_TIME.totalDays - cur.dayOccurred) / DAYS_PER_YEAR);
 if(years <= 1) return 1.5;
 if(years <= 3) return 1.4;
 if(years <= 5) return 1.3;
 if(years <= 7) return 1.2;
 if(years <= 9) return 1.1;
 return 1.0;
}

// 大地震の噂：どの町でも聞ける一般的な噂（発生からの経過年数で内容の言い回しが変化する）
function getWorldEarthquakeRumor(){
 const eq = PC._worldEarthquake;
 if(!eq || !eq.current || !eq.current.townId) return null;
 const cur = eq.current;
 const years = Math.floor((GAME_TIME.totalDays - cur.dayOccurred) / DAYS_PER_YEAR);
 const regionName = (HERO_REGIONS[cur.regionKey]||{}).name || '';
 const quakeYear = daysToDate(cur.dayOccurred).year;
 if(years <= 0){
  return `「${regionName}で大きな地震があったらしい」`;
 } else if(years <= 50){
  return `「${quakeYear}年にあった${regionName}の地震は大変だった」`;
 } else if(years <= 75){
  return `「うちの爺さん、${regionName}での${quakeYear}年の地震を体験したんだ。酷かったらしい。」`;
 } else {
  return `「昔${regionName}で大地震があってな……」`;
 }
}

// 大地震の噂：震源となった町限定・発生後1年間だけ聞ける「復旧作業」の噂
const WORLD_EARTHQUAKE_RECOVERY_RUMORS = [
 '「まだあちこちで倒壊した建物の後片付けが続いている。落ち着くまでもう少しかかりそうだ」',
 '「地震で崩れた道の修復に、みんな総出で当たっているそうだ」',
 '「井戸や水路が地震でやられて、水の確保にも苦労しているらしい」',
 '「余震にはまだ気をつけたほうがいい。時々小さく揺れることがあるからな」',
 '「商人たちも品物が届かず困っているとか。街道の復旧が待たれる」',
];
function getWorldEarthquakeRecoveryRumor(townId){
 const eq = PC._worldEarthquake;
 if(!eq || !eq.current || !eq.current.townId) return null;
 const cur = eq.current;
 if(townId !== cur.townId) return null;
 const years = (GAME_TIME.totalDays - cur.dayOccurred) / DAYS_PER_YEAR;
 if(years >= 1) return null;
 return WORLD_EARTHQUAKE_RECOVERY_RUMORS[Math.floor(Math.random()*WORLD_EARTHQUAKE_RECOVERY_RUMORS.length)];
}

// 大地震の噂：被災地方内のどの町でも聞ける、震源の町が一番揺れたという噂（発生後1年間のみ）
const WORLD_EARTHQUAKE_REGION_DAMAGE_RUMORS = [
 (t) => `「この間の大地震、${t}が一番大きく揺れたようだ。あの町までの道はいま散々だよ」`,
 (t) => `「${t}のあたりが一番ひどい揺れだったらしい。今は近づかない方がいいって話だ」`,
 (t) => `「聞いた話じゃ、${t}が今回の地震で一番揺れたって。あそこへの道は当分荒れたままだろうな」`,
];
function getWorldEarthquakeRegionDamageRumor(townId){
 const eq = PC._worldEarthquake;
 if(!eq || !eq.current || !eq.current.townId) return null;
 const cur = eq.current;
 const years = (GAME_TIME.totalDays - cur.dayOccurred) / DAYS_PER_YEAR;
 if(years >= 1) return null;
 if(getRegionKey(townId) !== cur.regionKey) return null;
 const townName = (TOWNS[cur.townId]||{}).name || cur.townId;
 const idx = Math.floor(Math.random()*WORLD_EARTHQUAKE_REGION_DAMAGE_RUMORS.length);
 return WORLD_EARTHQUAKE_REGION_DAMAGE_RUMORS[idx](townName);
}

// 大地震の噂の発生確率（発生から3ヶ月間はブースト。それ以降は平常の低確率）
function _worldEarthquakeRumorChance(){
 const eq = PC._worldEarthquake;
 if(!eq || !eq.current) return 0.05;
 const daysSince = GAME_TIME.totalDays - eq.current.dayOccurred;
 return daysSince <= 90 ? 0.20 : 0.05;
}

// 大地震の震源町では、発生後1年間は食料価格が2倍になる（foodPrice()から呼ばれる。現在地がPC.town前提）
function worldEarthquakeFoodPriceMultiplier(){
 const eq = PC._worldEarthquake;
 if(!eq || !eq.current || !eq.current.townId) return 1.0;
 if(PC.town !== eq.current.townId) return 1.0;
 const years = (GAME_TIME.totalDays - eq.current.dayOccurred) / DAYS_PER_YEAR;
 if(years >= 1) return 1.0;
 return 2.0;
}

// ══════════════════════════════════════════
// ポートアルゴン沖の隆起島
// 世界のどこかで大地震が発生するたびに（震源地方を問わず）ポートアルゴン沖（船で3日）に
// 島が隆起し、発生から5年間だけ上陸できる。5年経つといつの間にか再び沈下し、上陸できなくなる。
// 現時点ではダンジョン等のコンテンツは無く、将来の実装に備えた足場のみ。
// ══════════════════════════════════════════
const PORT_ARGON_ISLAND_TRAVEL_DAYS = 3;

// 島が現在浮上しているかどうか（直近の大地震発生から5年未満なら真。震源地方は問わない）
function isPortArgonIslandUp(){
 const eq = PC._worldEarthquake;
 if(!eq || !eq.current) return false;
 const years = (GAME_TIME.totalDays - eq.current.dayOccurred) / DAYS_PER_YEAR;
 return years < 5;
}

// 大地震の噂：ポートアルゴン沖に島が隆起したという噂（どの町でも聞ける。島が浮上している間のみ）
const PORT_ARGON_ISLAND_RUMORS = [
 '「ポートアルゴン沖に島ができたそうだ」',
 '「ポートアルゴン沖にできた島には何やら遺跡があるらしい」',
];
function getPortArgonIslandRumor(){
 if(!isPortArgonIslandUp()) return null;
 return PORT_ARGON_ISLAND_RUMORS[Math.floor(Math.random()*PORT_ARGON_ISLAND_RUMORS.length)];
}
// この噂の発生確率は他の地震関連の噂の半分にする
function _portArgonIslandRumorChance(){
 return _worldEarthquakeRumorChance() / 2;
}

function _portArgonIslandShowTravelUI(fromLabel, toLabel){
 drawScene('travel');
 showTravelImage('ship', 'port_argon', 'port_argon');
 const storyEl = document.getElementById('story');
 if(storyEl) storyEl.innerHTML = '';
 const tpw = document.getElementById('travel-progress-wrap');
 if(tpw){
  tpw.style.display = '';
  document.getElementById('travel-progress-bar').style.width = '0%';
  document.getElementById('travel-progress-dot').style.left = '0%';
  document.getElementById('travel-latest').textContent = '';
  document.getElementById('travel-progress-label').innerHTML =
   ` 船　<span style="color:#f0ece0">${fromLabel}</span> → <span style="color:#f0ece0">${toLabel}</span>　<span id="travel-day-count" style="color:#e0d8c8">0/${PORT_ARGON_ISLAND_TRAVEL_DAYS}日</span>`;
 }
 renderChoices([]);
}

// ポートアルゴン → 隆起島（往路）
function startPortArgonIslandJourney(){
 checkCompanionDeliveryAbandon();
 hideDungeonImage();
 _portArgonIslandShowTravelUI('ポートアルゴン', '隆起した島');
 advanceDaysAnimated(PORT_ARGON_ISLAND_TRAVEL_DAYS, ()=>{
  go('PORT_ARGON_ISLAND');
 });
 if(travelState){ travelState.method = 'ship'; travelState.crossRegion = false; travelState.arriveLabel = ' 島に上陸する'; travelState.destLabel = '隆起した島'; }
 travelLog(`<span style="color:#b8a890"> 船で <span style="color:#f0ece0">ポートアルゴン</span> → <span style="color:#f0ece0">隆起した島</span> へ出発。所要: ${PORT_ARGON_ISLAND_TRAVEL_DAYS}日</span>`);
}

// 隆起島 → ポートアルゴン（復路）
function startPortArgonIslandReturnJourney(){
 hideDungeonImage();
 _portArgonIslandShowTravelUI('隆起した島', 'ポートアルゴン');
 advanceDaysAnimated(PORT_ARGON_ISLAND_TRAVEL_DAYS, ()=>{
  go('TOWN_PORT_ARGON');
 });
 if(travelState){ travelState.method = 'ship'; travelState.crossRegion = false; travelState.destLabel = 'ポートアルゴン'; }
 travelLog(`<span style="color:#b8a890"> 船で <span style="color:#f0ece0">隆起した島</span> → <span style="color:#f0ece0">ポートアルゴン</span> へ出発。所要: ${PORT_ARGON_ISLAND_TRAVEL_DAYS}日</span>`);
}

// 移動実行
function travelTo(toId, method){
 if(isGuardLockedOut(PC.town)){
  showGuardLockoutMenu(PC.town, toId, method);
  return 'locked';
 }
 // 旅芸人の一座との護衛契約中に一人で別の町へ旅立つ場合は、契約を辞めるか確認する
 if(troupeTravelGate(toId, method)) return 'locked';
 const route = getRoute(PC.town, toId);
 if(!route) return false;
 // 冬期遮断チェック
 if(isRouteWinterBlocked(PC.town, toId)){
  alert(' 冬期のため、このルートは雪で遮断されています。春（4月）まで通行できません。');
  return false;
 }
 checkWorldEarthquake();
 let days = route.days[method];
 const cost = route.cost[method];
 if(days == null) return false;
 // 徒歩移動時、重量オーバーなら移動日数が2倍かかる（乗合馬車・船は影響なし）
 let overweightDoubled = false;
 if(method === 'walk'){
  const wp = checkWeightPenalty();
  if(wp.over){ days = days * 2; overweightDoubled = true; }
 }
 // 大地震の影響（震源町に接続する陸上ルートのみ。船は対象外）
 let earthquakeAffected = false;
 if(method !== 'ship'){
  const eqMult = worldEarthquakeRouteMultiplier(PC.town, toId);
  if(eqMult > 1.0){ days = Math.ceil(days * eqMult); earthquakeAffected = true; }
 }
 if(cost > 0 && totalCP() < cost*100){ alert('所持金が足りない！'); return 'nogold'; }

 const from = TOWNS[PC.town];
 const to = TOWNS[toId];
 const methodLabel = {walk:' 徒歩', coach:' 乗合馬車', ship:' 船'}[method];

 const fromTownId = PC.town; // PC.town更新前に保持
 if(cost>0) payPrice(cost);
 PC.town = toId;
 updateHUD();
 checkCompanionDeliveryAbandon(); // 保留中の同行配達を放置して旅立った場合は自動失敗させる

 // 移動シーンに切り替えてカウントアップ開始
 // 出発地か目的地のどちらかがエルマリア地方なら緑テーマ
 const ELMARIA_TOWNS = new Set(['elsia','verda','rimholm','marakai']);
 const ZAHARA_TOWNS = new Set(['al_rashid','oasis_fort','saroon','duna']);
 const VALDHEIM_TOWNS2 = new Set(['valdheim','nifurvik','iskald']);
 if(VALDHEIM_TOWNS2.has(PC.town) || VALDHEIM_TOWNS2.has(toId)){
 document.documentElement.style.setProperty('--bg','#0d0a07');
 document.documentElement.style.setProperty('--screen','#130f0a');
 } else if(ELMARIA_TOWNS.has(PC.town) || ELMARIA_TOWNS.has(toId)){
 document.documentElement.style.setProperty('--bg','#0d0a07');
 document.documentElement.style.setProperty('--screen','#130f0a');
 } else if(ZAHARA_TOWNS.has(PC.town) || ZAHARA_TOWNS.has(toId)){
 document.documentElement.style.setProperty('--bg','#0d0a07');
 document.documentElement.style.setProperty('--screen','#130f0a');
 } else {
 document.documentElement.style.setProperty('--bg','#0d0a07');
 document.documentElement.style.setProperty('--screen','#130f0a');
 }
 drawScene('travel');
 showTravelImage(method, fromTownId, toId);
 const storyEl = document.getElementById('story');
 if(storyEl) storyEl.innerHTML = '';
 // プログレスバーを独立DOM要素として表示・初期化
 const tpw = document.getElementById('travel-progress-wrap');
 if(tpw){
  tpw.style.display = '';
  document.getElementById('travel-progress-bar').style.width = '0%';
  document.getElementById('travel-progress-dot').style.left = '0%';
  document.getElementById('travel-latest').textContent = '';
  document.getElementById('travel-progress-label').innerHTML =
   `${methodLabel}　<span style="color:#f0ece0">${from.name}</span> → <span style="color:#f0ece0">${to.name}</span>　<span id="travel-day-count" style="color:#e0d8c8">0/${days}日</span>${overweightDoubled?'　<span style="color:#e0a060;font-size:calc(var(--font-sm) - 2px)">（重量オーバーのため2倍）</span>':''}${earthquakeAffected?'　<span style="color:#e0a060;font-size:calc(var(--font-sm) - 2px)">（道が荒れており時間がかかる）</span>':''}`;
 }
 renderChoices([]);

 // 極北地方が絡む移動かつ冬期なら凍傷蓄積フラグを設定
 const VALDHEIM_TOWNS = new Set(['valdheim','nifurvik','iskald']);
 const isValdheimRoute = VALDHEIM_TOWNS.has(toId) || VALDHEIM_TOWNS.has(PC.town);
 advanceDaysAnimated(days, ()=>{
  // 到着時凍傷チェック（極北ルートかつ冬期で防寒装備なし）
  if(isValdheimRoute && isWinter()){
   const hasClothing = PC.equippedClothing;
   const hasBoots = PC.equippedBoots;
   if(!hasClothing || !hasBoots){
    // 5日ごとに1段階：移動日数÷5回分進行
    const stages = Math.floor(days / 5);
    for(let i=0;i<stages;i++) progressFrostbite();
    const missing = [];
    if(!hasClothing) missing.push('防寒着');
    if(!hasBoots) missing.push('防寒ブーツ');
    if(stages > 0){
     const storyEl = document.getElementById('story');
     if(storyEl) storyEl.innerHTML += `<br><div style="border:1px solid #484848;border-radius:3px;padding:8px;background:var(--ink);margin-top:8px"><span style="color:#ece8e0"> 凍傷警告：${missing.join('・')}なしで極北を移動した。凍傷が${stages}段階進行した。（現在：${FROSTBITE_EFFECTS[getFrostbiteLevel()].label}）</span></div>`;
    }
   }
  }
  go('TOWN_'+toId.toUpperCase());
 });
 if(travelState) travelState.method = method;
 if(travelState) travelState.crossRegion = getRegionKey(fromTownId) !== getRegionKey(toId);
 if(travelState){ travelState.fromId = fromTownId; travelState.toId = toId; } // 荒野へ入る・戻るときに使う
 travelLog(`<span style="color:#b8a890">${methodLabel}で <span style="color:#f0ece0">${from.name}</span> → <span style="color:#f0ece0">${to.name}</span> へ出発。所要: ${days}日　費用: ${cost||0}GP</span>`);
 return true;
}

// 移動メニューのノード生成
function makeTravelChoices(fromId){
 _migrateFiefDataIfNeeded();
 checkWorldEarthquake();
 const MAREA_VILLAGES = ['dorua','sarpe','nebra'];
 const others = Object.keys(TOWNS).filter(id => id !== fromId);
 const choices = [];
 const _wpOver = checkWeightPenalty().over;
 others.forEach(toId => {
 const t = TOWNS[toId];
 const route = getRoute(fromId, toId);
 if(!route) return;
  if(route.isIsland) return; // 旧島間航路は専用メニューから
  if(MAREA_VILLAGES.includes(toId)) return; // マレア地方の村は専用メニューから
 const _eqMult = worldEarthquakeRouteMultiplier(fromId, toId);
 // 徒歩
 if(route.days.walk != null){
 let walkDays = _wpOver ? route.days.walk*2 : route.days.walk;
 if(_eqMult > 1.0) walkDays = Math.ceil(walkDays * _eqMult);
 choices.push({
 label:` ${t.name}へ 徒歩（${walkDays}日${_wpOver?'・重量オーバー':''}）`,
 fn:()=>travelTo(toId,'walk'), go:'__travel__'
 });
 }
 // 乗合馬車
 if(route.days.coach != null){
 let coachDays = route.days.coach;
 if(_eqMult > 1.0) coachDays = Math.ceil(coachDays * _eqMult);
 choices.push({
 label:` ${t.name}へ 乗合馬車（${coachDays}日・${route.cost.coach}GP）`,
 fn:()=>travelTo(toId,'coach'), go:'__travel__'
 });
 }
 // 船（ルートに船がある場合）
 if(route.hasShip && route.days.ship != null){
 choices.push({
 label:` ${t.name}へ 船（${route.days.ship}日・${route.cost.ship}GP）`,
 fn:()=>travelTo(toId,'ship'), go:'__travel__'
 });
 }
 });
 // 領地：免状の基点となった町ごとに、それぞれ旅の選択肢として表示する（複数の領地があればその数だけ並ぶ）
 (PC._fiefCharters||[]).filter(c=>c.anchorTownId === fromId).forEach(charter=>{
  const days = charter.anchorDays || 0;
  const stageLabel = !charter.cleared ? '（討伐）' : !charter.improved ? '（整備）' : '';
  const fiefLabel = PC.properties?.[charter.fiefId]?.fiefName || '領地';
  choices.push({
   label:` ${fiefLabel}へ 徒歩${stageLabel}（${days}日）`,
   fn:()=>travelToFiefAny(fromId), go:'__travel__'
  });
 });
 choices.push({label:'← 戻る', go:'TOWN_'+fromId.toUpperCase()});
 return choices;
}

// ── マレア諸島：島間航路メニュー ──
function makeIslandRouteChoices(fromId){
 return makeMareaRouteChoices(fromId);
}

function makeMareaRouteChoices(fromId){
 checkWorldEarthquake();
 const MAREA_TOWNS = ['neria','dorua','sarpe','nebra'];
 const choices = [];
 const _wpOver = checkWeightPenalty().over;
 MAREA_TOWNS.filter(id=>id!==fromId).forEach(toId=>{
  const route = getRoute(fromId, toId);
  if(!route || !route.days.walk) return;
  const t = TOWNS[toId];
  let days = _wpOver ? route.days.walk*2 : route.days.walk;
  const _eqMult = worldEarthquakeRouteMultiplier(fromId, toId);
  if(_eqMult > 1.0) days = Math.ceil(days * _eqMult);
  choices.push({
   label:` ${t.name}へ 徒歩（${days}日${_wpOver?'・重量オーバー':''}）`,
   fn:()=>travelTo(toId,'walk'), go:'__travel__'
  });
 });
 choices.push({label:'← 戻る', go:'TOWN_'+fromId.toUpperCase()});
 return choices;
}

function updateTimebar(){
 const el = document.getElementById('timebar');
 if(!el) return;
 const d = getCurrentDate();
 const age = calcAge();
 PC.age = age;
 const lifespan = PC.lifespan || (AGING_PARAMS[PC.race] || AGING_PARAMS.human).lifespan;
 const lifePct = Math.min(100, (age / lifespan) * 100);
 const lifeColor = lifePct < 50 ? 'var(--nature2)' : lifePct < 75 ? '#ffcc33' : 'var(--danger)';
 el.innerHTML =
 `<span style="color:#f0ece0">${formatDate(d)}</span>`;
 const hdrDate = document.getElementById('hdr-date');
 if(hdrDate) hdrDate.textContent = formatDate(d);
 if(window.innerWidth >= 860) updateMiniHUD();
}

function advanceDays(days){
 if(!days || days <= 0) return null;
 GAME_TIME.totalDays += days;
 // 一緒に行動している期間 → 信頼度増加（1日あたり+0.5、端数はランダム）
 if((PC.party||[]).length > 0){
  (PC.party||[]).forEach(npc=>{
   const gain = days * 0.5;
   const base = Math.floor(gain);
   const frac = gain - base;
   npc.trust = Math.min(100, (npc.trust??0) + base + (Math.random()<frac?1:0));
  });
 }
 const aged = checkAging();
 updateTimebar();
 return aged;
}

