// 海上エンカウント判定（陸上8%の2/3 ≈ 5.3%）
function rollSeaEncounter(){
 // 地方状態システム：出発地（PC.town）の治安悪化度に応じた倍率（最大2.0倍）。陸上と同じ倍率を適用
 const mult = regionConditionEncounterMult(getRegionKey(PC.town));
 return Math.random() < 0.03 * mult;
}

// 海上遅延イベント判定（陸上合計約5%の2/3 ≈ 3.3%）
function rollSeaDelayEvent(){
 return Math.random() < 0.033;
}

function pickSeaEnemy(){
 // 大ダコ・巨大海蛇は出現率低め（各15%）、海賊・幽霊船は各35%
 const r = Math.random();
 if(r < 0.35) return SEA_ENEMIES[0]; // 海賊
 if(r < 0.70) return SEA_ENEMIES[1]; // 幽霊船
 if(r < 0.85) return SEA_ENEMIES[2]; // 大ダコ
 return SEA_ENEMIES[3]; // 巨大海蛇
}

function startSeaEncounter(enemy){
 const ts = travelState;
 travelLog(`<span style="color:#f0ddd8"> ${ts.daysDone}日目：${enemy.desc}</span>`);
 if(enemy.isHuman && enemy.id === 'pirates'){
  // 海賊は交渉可能
  const choices = document.getElementById('choices');
  choices.innerHTML = '';
  const fight = document.createElement('button'); fight.className='choice-btn';
  fight.textContent = ' 戦う';
  fight.onclick = ()=>{
   choices.innerHTML = '';
   startCombat({
    enemies: enemy.enemies,
    canFlee: true, isHuman: true,
    win:'__noop__', lose:'DEAD',
    onWin:()=>{
     document.getElementById('cbt-area').classList.add('hidden'); document.getElementById('scroll-area').classList.remove('in-combat');
     document.getElementById('text-win').style.display='';
     cbtState=null;
     const gp = 20 + Math.floor(Math.random()*31);
     gainGPAll(gp); updateHUD();
     travelLog(`<span style="color:#f0ece0"> 海賊を撃退した！略奪品 +${gp}GP</span>`);
     setTimeout(()=>travelTick(), ts.interval);
    }
   });
  };
  const pay = document.createElement('button'); pay.className='choice-btn';
  pay.textContent = ' 身代金を払う（50GP）';
  pay.onclick = ()=>{
   choices.innerHTML = '';
   if(totalCP() >= 5000){
    payPrice(50); updateHUD();
    travelLog(`<span style="color:#c0b098"> 50GPを払い見逃してもらった。</span>`);
   } else {
    travelLog(`<span style="color:#e0d0d0"> 金がない！海賊が激怒した！</span>`);
    startCombat({
     enemies: enemy.enemies, canFlee:true, isHuman:true,
     win:'__noop__', lose:'DEAD',
     onWin:()=>{ document.getElementById('cbt-area').classList.add('hidden'); document.getElementById('scroll-area').classList.remove('in-combat'); document.getElementById('text-win').style.display=''; cbtState=null; setTimeout(()=>travelTick(),ts.interval); }
    }); return;
   }
   setTimeout(()=>travelTick(), ts.interval);
  };
  const flee = document.createElement('button'); flee.className='choice-btn';
  flee.textContent = ' 全速逃走（素早さ Lv2 能力値テスト）';
  flee.onclick = ()=>{
   choices.innerHTML = '';
   setupSavingRoll({
    attr:'spd', level:2,
    onSuccess:()=>{
     changeAlignment(0, -0.5); // 逃亡：混沌+0.5
     setTimeout(()=>travelTick(), ts.interval);
    },
    onFail:()=>{
     startCombat({
      enemies: enemy.enemies, canFlee:false, isHuman:true,
      win:'__noop__', lose:'DEAD',
      onWin:()=>{ document.getElementById('cbt-area').classList.add('hidden'); document.getElementById('scroll-area').classList.remove('in-combat'); document.getElementById('text-win').style.display=''; cbtState=null; setTimeout(()=>travelTick(),ts.interval); }
     });
    },
   });
  };
  choices.appendChild(fight);
  choices.appendChild(pay);
  choices.appendChild(flee);
 } else {
  // モンスター系：戦うか逃げるか
  const choices = document.getElementById('choices');
  choices.innerHTML = '';
  const fight = document.createElement('button'); fight.className='choice-btn';
  fight.textContent = ' 戦う';
  fight.onclick = ()=>{
   choices.innerHTML = '';
   startCombat({
    enemies: enemy.enemies,
    canFlee: true, isHuman: false,
    win:'__noop__', lose:'DEAD',
    onWin:()=>{
     document.getElementById('cbt-area').classList.add('hidden'); document.getElementById('scroll-area').classList.remove('in-combat');
     document.getElementById('text-win').style.display='';
     cbtState=null;
     travelLog(`<span style="color:#f0ece0"> ${enemy.name}を撃退した！</span>`);
     setTimeout(()=>travelTick(), ts.interval);
    }
   });
  };
  const flee = document.createElement('button'); flee.className='choice-btn';
  flee.textContent = ' 全速逃走（素早さ Lv2 能力値テスト）';
  flee.onclick = ()=>{
   choices.innerHTML = '';
   setupSavingRoll({
    attr:'spd', level:2,
    onSuccess:()=>{
     changeAlignment(0, -0.5); // 逃亡：混沌+0.5
     setTimeout(()=>travelTick(), ts.interval);
    },
    onFail:()=>{
     startCombat({
      enemies: enemy.enemies, canFlee:false, isHuman:false,
      win:'__noop__', lose:'DEAD',
      onWin:()=>{
       const countTxt2 = enemy.count > 1 ? `×${enemy.count}` : '';
       travelLog(`<span style="color:#f0ece0"> ${ts.daysDone}日目：${enemy.name}${countTxt2}を倒した！ 経験値+${enemy.mr}</span>`);
       document.getElementById('cbt-area').classList.add('hidden'); document.getElementById('scroll-area').classList.remove('in-combat'); document.getElementById('text-win').style.display=''; cbtState=null; setTimeout(()=>travelTick(),ts.interval);
      }
     });
    },
   });
  };
  choices.appendChild(fight);
  choices.appendChild(flee);
 }
}

function applySeaDelayEvent(){
 const ts = travelState;
 const ev = SEA_DELAY_EVENTS[Math.floor(Math.random()*SEA_DELAY_EVENTS.length)];
 const delay = ev.minDays + Math.floor(Math.random()*(ev.maxDays - ev.minDays + 1));
 ts.totalDays += delay;
 // 停滞日数分だけ時間を進める
 for(let i=0;i<delay;i++){ GAME_TIME.totalDays++; }
 updateTimebar();
 travelLog(`<span style="color:var(--white)"> ${ts.daysDone}日目：【${ev.title}】${ev.desc}<br><span style="color:var(--white)"> ${delay}日間の遅延（合計${ts.totalDays}日の旅程になった）</span></span>`);
}

