// 移動中エンカウント状態
let travelState = null; // { totalDays, daysDone, destId, onDone, events }

function rollTravelEncounter(){
 // 地方状態システム：出発地（PC.town）の治安悪化度に応じた倍率（最大2.0倍）
 // 荒野の移動中は、いるマスの地形に応じた地方の倍率を使う
 let mult = regionConditionEncounterMult((travelState && travelState._wildRegion) || getRegionKey(PC.town));
 // 旅芸人の護衛契約中は、一座が目立つぶん襲われやすい
 if(travelState && travelState._troupeLeg) mult *= TROUPE_ENC_MULT;
 return Math.random() < 0.08 * mult;
}

function pickTravelEnemy(){
 // 荒野の移動中は、いるマスの地形に応じた地方のエンカウントテーブルを使う（街道のマスは従来どおり）
 const regionKey = (travelState && travelState._wildRegion) || getRegionKey(PC.town);
 const pool = TRAVEL_ENEMIES.concat(REGION_TRAVEL_ENEMIES[regionKey] || []);
 const template = pool[Math.floor(Math.random() * pool.length)];
 const isCross = travelState?.crossRegion || false;
 const _wild9 = !!(travelState && travelState._wildCount9); // 荒野（街道の外）は1〜9体
 const minC = isCross ? 1 : template.minCount;
 const maxC = _wild9 ? 9 : (isCross ? 3 : template.maxCount);
 const count = minC + Math.floor(Math.random() * (maxC - minC + 1));
 const enemies = Array.from({length: count}, () => ({
  name: template.name,
  mr: template.mr,
  curMR: template.mr,
  armor: template.armor,
 }));
 const _d = (travelState && travelState._wildOff && template.desc) ? wildCleanText(template.desc) : template.desc;
 return { ...template, desc:_d, count, enemies };
}

