// ══════════════════════════════════════════
// PC._borderFort = { gauge, lastTickDay, wavesRepelled, lastSortieDay }
// ゲージは0まで落ちず、下限で下げ止まる（陥落なし＝ぎりぎり持ちこたえている表現）
const BORDER_FORT_GAUGE_FLOOR = 10;
const BORDER_FORT_DECAY_PER_DAY = 0.05; // 放置5年(1800日)で100→10まで低下
const BORDER_FORT_SORTIE_COOLDOWN = 7; // 出撃は週1回まで

function initBorderFort(){
 if(!PC._borderFort) PC._borderFort = {
  gauge: 100,
  lastTickDay: GAME_TIME.totalDays,
  wavesRepelled: 0,
  lastSortieDay: null,
 };
}

// 訪問時にまとめて経過分の自然減衰を適用（拠点住人の寿命チェックと同じ「訪問時精算」方式）
function tickBorderFortGauge(){
 initBorderFort();
 const bf = PC._borderFort;
 const days = GAME_TIME.totalDays - (bf.lastTickDay ?? GAME_TIME.totalDays);
 if(days > 0){
  bf.gauge = Math.max(BORDER_FORT_GAUGE_FLOOR, bf.gauge - days * BORDER_FORT_DECAY_PER_DAY);
  bf.lastTickDay = GAME_TIME.totalDays;
 }
}

function borderFortStatusText(){
 const g = PC._borderFort?.gauge ?? 100;
 if(g >= 80) return { label:'砦は堅固に持ちこたえている。', color:'var(--nature2)' };
 if(g >= 40) return { label:'防壁のあちこちが崩れ、補給も滞っている。', color:'#ffcc33' };
 return { label:'包囲され、ぎりぎりの攻防が続いている。', color:'#c05040' };
}

function renderBorderFortGaugeBar(){
 tickBorderFortGauge();
 const g = Math.round(PC._borderFort.gauge);
 const st = borderFortStatusText();
 return `<div style="margin:8px 0">
  <div style="display:flex;justify-content:space-between;font-size:calc(var(--font-sm) - 2px);color:#c0b098;margin-bottom:2px">
   <span>防衛度</span><span>${g}/100</span>
  </div>
  <div style="background:#1a1410;border:1px solid #484848;border-radius:3px;height:8px;overflow:hidden">
   <div style="width:${g}%;height:100%;background:${st.color}"></div>
  </div>
  <div style="color:${st.color};font-size:calc(var(--font-sm) - 1px);margin-top:4px">${st.label}</div>
 </div>`;
}

// ── 迎え撃つ（受け身の防衛戦）：滞在中、高確率で強制発生。勝ってもゲージはごくわずかしか回復しない ──
function checkKalvoSiege(){
 if(PC.town !== 'kalvo') return false;
 if(travelState || cbtState) return false; // 旅行中・戦闘中は対象外
 initBorderFort();
 if(Math.random() >= 0.5) return false; // 滞在中は5割
 startKalvoSiege();
 return true;
}

function startKalvoSiege(){
 const waveCount = 3 + Math.floor(Math.random()*3); // 3〜5体
 const waves = Array.from({length: waveCount}, () => pickMareaEnemy());
 const story = document.getElementById('story');
 if(story){
  story.innerHTML = `<div style="border:1px solid var(--danger, #a04030);border-radius:4px;padding:12px;background:#1a0a06">
   <div style="color:#e08060;font-size:var(--font-base);margin-bottom:8px"> 混沌の軍勢、来襲！</div>
   <div style="color:#e8d8d0;font-size:calc(var(--font-sm) - 1px)">警鐘が絶え間なく鳴り続けている。奥地から溢れ出た混沌の軍勢が、防壁の外に押し寄せてきた。次々と${waveCount}体の脅威が襲いかかってくる！</div>
  </div>`;
 }
 renderChoices([{label:' 迎え撃つ！', fn:()=>{
  renderChoices([]);
  _kalvoSiegeNextWave(waves, 0);
 }}]);
}

function _kalvoSiegeNextWave(waves, idx){
 if(idx >= waves.length){
  initBorderFort();
  PC._borderFort.gauge = Math.min(100, PC._borderFort.gauge + (1 + Math.floor(Math.random()*2))); // +1〜2のみ
  PC._borderFort.wavesRepelled = (PC._borderFort.wavesRepelled||0) + waves.length;
  const story = document.getElementById('story');
  if(story){
   story.innerHTML = `<div style="color:#f0ece0"> 波状攻撃を全て打ち払った！だが、これしきでは奥地の軍勢は揺るがない。</div>`;
  }
  showSaveToast(' 迎撃成功……防衛度 微増');
  changeTrust('kalvo', 5);
  updateHUD();
  renderChoices([{label:'▶ OK', fn:()=>{ renderChoices([]); go('TOWN_KALVO'); }}]);
  return;
 }
 const enemy = waves[idx];
 const story = document.getElementById('story');
 if(story){
  story.innerHTML = `<div style="color:#e8d8d0"> [${idx+1}/${waves.length}体目] ${enemy.desc}</div>`;
 }
 _startKalvoSiegeCombat(enemy, waves, idx);
}

function _startKalvoSiegeCombat(enemy, waves, idx){
 const onDefeated = ()=>{ _kalvoSiegeNextWave(waves, idx+1); };
 if(enemy.kind === 'npc'){
  startCombatNPC({
   enemies: enemy.npcs,
   canFlee: false, // 砦防衛戦のため撤退不可
   win: '__noop__',
   lose: 'DEAD',
   onWin: ()=>{
    document.getElementById('cbt-area').classList.add('hidden');
    document.getElementById('scroll-area').classList.remove('in-combat');
    document.getElementById('text-win').style.display = '';
    cbtState = null;
    updateHUD();
    onDefeated();
   },
  });
  return;
 }
 startCombat({
  name: enemy.name,
  mr: enemy.mr,
  armor: enemy.armor||0,
  magicOnly: !!enemy.magicOnly,
  canFlee: false,
  win: '__noop__',
  lose: 'DEAD',
  onWin: ()=>{
   document.getElementById('cbt-area').classList.add('hidden');
   document.getElementById('scroll-area').classList.remove('in-combat');
   document.getElementById('text-win').style.display = '';
   cbtState = null;
   updateHUD();
   onDefeated();
  },
 });
}

// ── 打って出る（出撃戦）：週1回、酒場で部隊を募る。複数体（1〜6体）×2〜6波 ──
function canBorderFortSortie(){
 initBorderFort();
 const last = PC._borderFort.lastSortieDay;
 return last == null || (GAME_TIME.totalDays - last) >= BORDER_FORT_SORTIE_COOLDOWN;
}

// 複数体をまとめて1回の戦闘にする版（出撃戦専用）
function pickMareaEnemyGroup(count){
 const t = MAREA_ENEMIES[Math.floor(Math.random()*MAREA_ENEMIES.length)];
 if(t.kind === 'npc'){
  const npcs = Array.from({length:count}, ()=>{
   const level = t.levelMin + Math.floor(Math.random()*(t.levelMax-t.levelMin+1));
   const npc = generateNPC(level);
   npc.name = t.name;
   npc.bountyTitle = t.name;
   return npc;
  });
  return { kind:'npc', name:t.name, desc:t.desc, count, npcs };
 }
 return {
  kind:'flat', name:t.name, desc:t.desc, count,
  enemies: Array.from({length:count}, ()=>({name:t.name, mr:t.mr, armor:t.armor||0, magicOnly:!!t.magicOnly})),
 };
}

function startBorderFortSortie(){
 if(!canBorderFortSortie()){ showSaveToast('出撃部隊はまだ編成できない（週1回まで）'); return; }
 const waveCount = 2 + Math.floor(Math.random()*5); // 2〜6波（従来1〜3波の2倍）
 const waves = Array.from({length: waveCount}, () => {
  const n = 1 + Math.floor(Math.random()*6); // 1〜6体
  return pickMareaEnemyGroup(n);
 });
 initBorderFort();
 PC._borderFort.lastSortieDay = GAME_TIME.totalDays; // 出撃した時点で消費（結果に関わらず週1回まで）
 const story = document.getElementById('story');
 if(story){
  story.innerHTML = `<div style="border:1px solid var(--danger, #a04030);border-radius:4px;padding:12px;background:#1a0a06">
   <div style="color:#e08060;font-size:var(--font-base);margin-bottom:8px"> 出撃</div>
   <div style="color:#e8d8d0;font-size:calc(var(--font-sm) - 1px)">出撃部隊を率い、奥地の混沌の軍勢へ自ら打って出る。守るだけでは押し返せない——今日こそ、こちらから叩く。</div>
  </div>`;
 }
 renderChoices([{label:' 出撃する！', fn:()=>{
  renderChoices([]);
  _borderFortSortieNextWave(waves, 0);
 }}]);
}

function _borderFortSortieNextWave(waves, idx){
 if(idx >= waves.length){
  initBorderFort();
  PC._borderFort.gauge = Math.min(100, PC._borderFort.gauge + 5);
  const story = document.getElementById('story');
  if(story){
   story.innerHTML = `<div style="color:#f0ece0"> 混沌の軍勢の一角を打ち崩した！奥地への圧力が、わずかに弱まった。</div>`;
  }
  showSaveToast(' 出撃成功……防衛度+5');
  changeTrust('kalvo', 10);
  updateHUD();
  renderChoices([{label:'▶ OK', fn:()=>{ renderChoices([]); go('TOWN_KALVO'); }}]);
  return;
 }
 const group = waves[idx];
 const story = document.getElementById('story');
 if(story){
  story.innerHTML = `<div style="color:#e8d8d0"> [${idx+1}/${waves.length}波目・${group.count}体] ${group.desc}</div>`;
 }
 _startBorderFortSortieCombat(group, waves, idx);
}

// 出撃の敗北＝死亡ではなく撤退扱い（ゲージ現状維持）。九死に一生の判定は通常通り先に行われる。
// 実際の演出は KALVO_SORTIE_RETREAT ノード側で行う（lose:先はコールバックではなくノードIDである必要があるため）

function _startBorderFortSortieCombat(group, waves, idx){
 const onDefeated = ()=>{ _borderFortSortieNextWave(waves, idx+1); };
 if(group.kind === 'npc'){
  startCombatNPC({
   enemies: group.npcs,
   canFlee: false, // 出撃部隊のため中途撤退はできない（敗北＝撤退扱いで処理）
   win: '__noop__',
   lose: 'KALVO_SORTIE_RETREAT', // 敗北＝死亡ではなく撤退ノードへ（ゲージ現状維持）
   onWin: ()=>{
    document.getElementById('cbt-area').classList.add('hidden');
    document.getElementById('scroll-area').classList.remove('in-combat');
    document.getElementById('text-win').style.display = '';
    cbtState = null;
    updateHUD();
    onDefeated();
   },
  });
  return;
 }
 startCombat({
  enemies: group.enemies,
  canFlee: false,
  win: '__noop__',
  lose: 'KALVO_SORTIE_RETREAT',
  onWin: ()=>{
   document.getElementById('cbt-area').classList.add('hidden');
   document.getElementById('scroll-area').classList.remove('in-combat');
   document.getElementById('text-win').style.display = '';
   cbtState = null;
   updateHUD();
   onDefeated();
  },
 });
}

