// ══════════════════════════════════════════
//  町の天候フレーバーシステム
//  地方・季節ごとの確率でその日の天候を決め（同じ日は同じ結果）、
//  天候×時間帯（朝/昼/夜）に応じた一文を町のメイン画面に表示する
// ══════════════════════════════════════════

// 文字列と日数からその日固有の疑似乱数（0-1）を作る。Math.random()と違い同じ入力なら常に同じ値を返す
function seededRandom(seedStr){
 let h = 0;
 for(let i=0;i<seedStr.length;i++){
  h = Math.imul(h ^ seedStr.charCodeAt(i), 2654435761);
 }
 // 追加の攪拌（mulberry32相当）：単純な多項式ハッシュだけだと連番の入力（日数など）で偏りが出るため
 h = h ^ (h >>> 15);
 h = Math.imul(h ^ (h >>> 16), 0x45d9f3b);
 h = Math.imul(h ^ (h >>> 16), 0x45d9f3b);
 h = h ^ (h >>> 16);
 return (h >>> 0) / 4294967296;
}

// villagePhaseの6区分（未明/朝/昼/午後/夜/深夜）を、天候表示用の3区分（朝/昼/夜）にまとめる
function getTownTimeOfDay(){
 const phase = villagePhase(getGameHour()).key;
 if(phase === 'dawn' || phase === 'morning') return 'morning';
 if(phase === 'noon' || phase === 'afternoon') return 'noon';
 return 'night'; // night, midnight
}

