// その日の天候を、地方・季節ごとの確率から決定的に選ぶ（同じ日・同じ地方なら常に同じ結果）
// マレア地方専用：季節も規則性もない異常気象タイプ（混沌の勢力に蝕まれた土地のため）
const MAREA_WEATHER_TYPES = ['calm', 'scorching_wave', 'cold_wave', 'chaos_storm', 'corrosive_wind'];

function getTodayWeather(regionKey){
 if(regionKey === 'marea_region'){
  // 通常の地方と違い季節に紐づかず、時間帯（朝/昼/夜）が変わるたびに天候も切り替わる＝1日の中でも規則なく変化し続ける
  const idx = Math.floor(seededRandom('marea_weather_' + GAME_TIME.totalDays + '_' + getTownTimeOfDay()) * MAREA_WEATHER_TYPES.length);
  return MAREA_WEATHER_TYPES[idx];
 }
 const table = REGION_WEATHER_TABLE[regionKey]?.[getSeasonKey()];
 if(!table || !table.length) return null;
 const seed = seededRandom(regionKey + '_weather_' + GAME_TIME.totalDays);
 const totalWeight = table.reduce((s,t)=>s+t.weight, 0);
 let roll = seed * totalWeight;
 for(const t of table){
  if(roll < t.weight) return t.type;
  roll -= t.weight;
 }
 return table[0].type;
}

// 町のメイン画面に表示する天候フレーバー行を返す（未整備の地方は空文字＝何も表示しない）
function popWeatherMsg(townId){
 const regionKey = getRegionKey(townId);
 const weather = regionKey ? getTodayWeather(regionKey) : null;
 if(!weather) return '';
 const timeKey = getTownTimeOfDay();
 const pool = TOWN_WEATHER_FLAVOR[regionKey]?.[weather]?.[timeKey];
 if(!pool || !pool.length) return '';
 // 天候・時間帯・日付を種にして選ぶ（同じ日の同じ時間帯なら常に同じ文章）
 const idx = Math.floor(seededRandom(regionKey + '_' + weather + '_' + timeKey + '_' + GAME_TIME.totalDays) * pool.length);
 return `<span style="color:#a89880">${pool[idx]}</span><br>` + popRegionConditionFlavor(townId);
}

