// 地方状態システム（§7-a-2）：他地方の噂。距離差なし・粗い情報（地方名＋深刻度のみ）
const REGION_CONDITION_WORLD_RUMOR = {
 2: [ (name)=>`「${name}の方じゃ、最近どうも物騒らしい」`,
      (name)=>`「${name}では物資がうまく回っていないという話だ」`,
      (name)=>`「${name}から人が流れてきているらしい。向こうは大変みたいだ」` ],
 3: [ (name)=>`「${name}は今かなり荒れていると聞く。できれば近づきたくないね」`,
      (name)=>`「${name}の方は危機的な状況らしい。商人も行きたがらないとか」`,
      (name)=>`「${name}から逃げてきたという旅人に会った。相当ひどい有様だそうだ」` ],
};
function getRegionConditionWorldRumor(townId){
 const myRegion = getRegionKey(townId);
 ensureRegionCondition();
 const candidates = [];
 REGION_CONDITION_SCOPE.forEach(regionKey=>{
  if(regionKey === myRegion) return;
  const c = PC._regionCondition[regionKey];
  const worst = Math.max(c.logi, c.unrest, c.exodus);
  const stage = regionConditionStageIndex(worst);
  if(stage >= 2) candidates.push({ regionKey, stage });
 });
 if(!candidates.length) return null;
 const pick_ = candidates[Math.floor(Math.random()*candidates.length)];
 const regionName = (HERO_REGIONS[pick_.regionKey]||{}).name || pick_.regionKey;
 const pool = REGION_CONDITION_WORLD_RUMOR[pick_.stage];
 const line = pool[Math.floor(Math.random()*pool.length)];
 return line(regionName);
}

