// onSuccess: 成功時の処理。ログに出すメッセージ文字列を返す（GP付与などはここで行う）
// failType: 'combat'（戦闘になる）/ 'damage'（負傷する）/ 'nothing'（特に何も起きない）
// failEnemyTemplate: failType==='combat' の場合の敵情報
// failDamage: failType==='damage' の場合のダメージ量を返す関数（省略時は2〜4）
