// 世界の裏設定に触れる、レア度高の遺物。カザーヌ地方のダンジョンでのみ、極低確率で見つかる。
const LORE_RELIC_ITEM = {
 name: '見慣れぬ文字の石片',
 icon: '',
 desc: 'どの言語にも当てはまらない文字が刻まれている。所々に、円が幾つも重なったような図像も見える。',
 weight: 5,
 baseCost: 300,
};

// カザーヌ地方のダンジョンでのみ呼ぶ想定の判定関数。trueなら遺物が見つかったことにして加える。
function tryFindLoreRelic(){
 if(Math.random() >= 0.02) return false; // 2%
 PC.invSpecialties = PC.invSpecialties || [];
 PC.invSpecialties.push({ name:LORE_RELIC_ITEM.name, icon:LORE_RELIC_ITEM.icon, regionKey:'khazan_region', baseCost:LORE_RELIC_ITEM.baseCost, weight:LORE_RELIC_ITEM.weight, boughtAt:0 });
 return true;
}

