function pickTravelRumor(){
 const tag = PC.background?.motiveTag;
 const pool = tag && MOTIVE_RUMORS[tag];
 if(pool && Math.random() < 0.25){
  return pick(pool)(PC.background);
 }
 if(Math.random() < 0.12){
  return pick(LORE_HINT_ROAD_RUMORS);
 }
 return pick(TRAVEL_ROAD_RUMORS);
}

// 移動中：人間系エンカウントの話術オプション
// 進行中（出発済み・経由町で足止め中でない）の同行配達依頼を返す
function _getActiveCompanionDeliveryQuest(){
 return (PC.quests||[]).find(q=>
  q.type==='companionDelivery' && q.status==='active' && q._started && !q.isPausedAt
 ) || null;
}

function startTravelTalk(enemy, ts){
 drawScene('travel');
 document.getElementById('dice-area').classList.add('hidden');

 // travel-log-wrapがなければ作成
 const storyEl = document.getElementById('story');
 if(storyEl && !document.getElementById('travel-log-wrap')){
  storyEl.innerHTML += `<div id="travel-log-wrap" style="border-top:1px solid var(--panel2);margin-top:8px;padding-top:8px;font-size:var(--font-base)"><div id="travel-events"></div></div>`;
 }

 travelLog(`<div style="padding:6px;background:var(--panel);border:1px solid var(--bark);border-radius:3px"><span style="color:#b8a890"> ${enemy.name}に遭遇！</span><br><span style="color:#b8a890;font-size:var(--font-sm)">${enemy.talkDesc||enemy.desc}</span></div>`);

 const srLevel = 2;
 const target = srLevel * 5 + 15;

 // 同行配達依頼で移動中なら、プレイヤーに選ばせず、リーダーが個性に応じて対応を決める
 const _deliveryQ = _getActiveCompanionDeliveryQuest();
 if(_deliveryQ){
  const leaderName = _deliveryQ.leader.name;
  const personaName = _deliveryQ.leaderPersonality.name;
  // 個性ごとに、戦う／話術／逃げるの傾向を重み付け
  const WEIGHTS = {
   '豪快':   {fight:0.6, talk:0.3, flee:0.1},
   '熱血':   {fight:0.6, talk:0.3, flee:0.1},
   '寡黙':   {fight:0.5, talk:0.3, flee:0.2},
   '慎重':   {fight:0.15,talk:0.55,flee:0.3},
   '陽気':   {fight:0.2, talk:0.6, flee:0.2},
   '皮肉屋': {fight:0.25,talk:0.6, flee:0.15},
  };
  const w = WEIGHTS[personaName] || {fight:0.34, talk:0.33, flee:0.33};
  const r = Math.random();
  const decision = r < w.fight ? 'fight' : (r < w.fight+w.talk ? 'talk' : 'flee');
  const decisionLines = {
   fight: `「相手にする必要はない、蹴散らすぞ！」`,
   talk:  `「待て、まずは話をつけよう」`,
   flee:  `「まずい、ここは逃げるぞ！」`,
  };
  travelLog(`<span style="color:#c8b8a0">リーダーの${leaderName}が判断を下した。${decisionLines[decision]}</span>`);
  renderChoices([{label:'▶ 続ける', fn:()=>{
   renderChoices([]);
   if(decision === 'fight'){
    document.getElementById('cbt-area').classList.add('hidden'); document.getElementById('scroll-area').classList.remove('in-combat');
    document.getElementById('text-win').style.display = '';
    document.getElementById('dice-area').classList.add('hidden');
    cbtState = null;
    startTravelCombat(enemy);
   } else if(decision === 'talk'){
    document.getElementById('cbt-area').classList.add('hidden'); document.getElementById('scroll-area').classList.remove('in-combat');
    document.getElementById('text-win').style.display = '';
    cbtState = null;
    setupSavingRollFor(_deliveryQ.leader, {
     attr: 'chr', level: srLevel,
     onSuccess: () => {
      travelLog(`<span style="color:#e8e4d8"> ${leaderName}がうまく言いくるめた！ ${enemy.name}は立ち去っていった。</span>`);
      renderChoices([{label:'▶ 旅を続ける', fn:()=>{
       document.getElementById('dice-area').classList.add('hidden');
       document.getElementById('text-win').style.display='';
       renderChoices([]);
       ts._resumeWithoutIncrement = true;
       setTimeout(_travelTickSched(), ts.interval);
      }}]);
     },
     onFail: () => {
      travelLog(`<span class="red"> 交渉決裂…${enemy.name}は怒りをあらわにした！</span>`);
      renderChoices([{label:'▶ 戦う', fn:()=>{
       document.getElementById('dice-area').classList.add('hidden');
       document.getElementById('text-win').style.display='';
       setTimeout(() => startTravelCombat(enemy), 200);
      }}]);
     },
    });
   } else { // flee
    document.getElementById('cbt-area').classList.add('hidden'); document.getElementById('scroll-area').classList.remove('in-combat');
    document.getElementById('text-win').style.display = '';
    document.getElementById('dice-area').classList.add('hidden');
    cbtState = null;
    setupSavingRollFor(_deliveryQ.leader, {
     attr: 'spd', level: 1,
     onSuccess: () => {
      travelLog(`<span style="color:#e8e4d8"> ${leaderName}の判断で無事に切り抜けた！</span>`);
      renderChoices([{label:'▶ 旅を続ける', fn:()=>{
       renderChoices([]);
       document.getElementById('dice-area').classList.add('hidden');
       document.getElementById('text-win').style.display='';
       ts._resumeWithoutIncrement = true;
       setTimeout(_travelTickSched(), ts.interval);
      }}]);
     },
     onFail: () => {
      const dmg = Math.max(1, Math.floor(enemy.mr / 10));
      PC.con = Math.max(0, PC.con - dmg);
      updateHUD();
      travelLog(`<span class="red"> 逃げ切れず、背中に一撃を受けた！（体力-${dmg}）</span>`);
      if(PC.con <= 0){ setTimeout(()=>go('DEAD'), 800); return; }
      renderChoices([{label:'▶ 戦う', fn:()=>{
       document.getElementById('dice-area').classList.add('hidden');
       document.getElementById('text-win').style.display='';
       setTimeout(() => startTravelCombat(enemy), 200);
      }}]);
     },
    });
   }
  }}]);
  return;
 }

 const choices = document.getElementById('choices');
 if(choices){
 choices.innerHTML = '';

 // 話術ボタン
 const talkBtn = document.createElement('button');
 talkBtn.className = 'choice-btn';
 talkBtn.innerHTML = ` 話術で切り抜ける（魅力 Lv${srLevel} 能力値テスト　目標${target}）`;
 talkBtn.onclick = () => {
 choices.innerHTML = '';
 document.getElementById('cbt-area').classList.add('hidden'); document.getElementById('scroll-area').classList.remove('in-combat');
 document.getElementById('text-win').style.display = '';
 cbtState = null;
 travelLog(`<span style="color:#b8a890"> ${enemy.name}を話術で説得しようとする…</span>`);
 setupSavingRoll({
  attr: 'chr',
  level: srLevel,
  onSuccess: () => {
   travelLog(`<span style="color:#e8e4d8"> うまく言いくるめた！ ${enemy.name}は立ち去っていった。</span>`);
   renderChoices([{label:'▶ 旅を続ける', fn:()=>{
    document.getElementById('dice-area').classList.add('hidden');
    document.getElementById('text-win').style.display='';
    renderChoices([]);
    ts._resumeWithoutIncrement = true;
    setTimeout(_travelTickSched(), ts.interval);
   }}]);
  },
  onFail: () => {
   travelLog(`<span class="red"> 説得失敗…${enemy.name}は怒りをあらわにした！</span>`);
   renderChoices([{label:'▶ 戦う', fn:()=>{
    document.getElementById('dice-area').classList.add('hidden');
    document.getElementById('text-win').style.display='';
    setTimeout(() => startTravelCombat(enemy), 200);
   }}]);
  },
 });
 };
 choices.appendChild(talkBtn);

 // 戦闘ボタン
 const fightBtn = document.createElement('button');
 fightBtn.className = 'choice-btn';
 fightBtn.innerHTML = ` 戦う`;
 fightBtn.onclick = () => {
 choices.innerHTML = '';
 document.getElementById('cbt-area').classList.add('hidden'); document.getElementById('scroll-area').classList.remove('in-combat');
 document.getElementById('text-win').style.display = '';
 document.getElementById('dice-area').classList.add('hidden');
 cbtState = null;
 startTravelCombat(enemy);
 };
 choices.appendChild(fightBtn);

 // 逃げるボタン（戦闘開始してすぐ逃走フローへ）
 const fleeBtn = document.createElement('button');
 fleeBtn.className = 'choice-btn';
 fleeBtn.style.cssText = 'border-color:#d8d0c0;color:#f0ece0;background:#1a1a1a';
 fleeBtn.innerHTML = ` 逃げる（素早さ Lv1 能力値テスト）`;
 fleeBtn.onclick = () => {
 choices.innerHTML = '';
 // UI状態をリセット（前の戦闘後の残留を解消）
 document.getElementById('cbt-area').classList.add('hidden'); document.getElementById('scroll-area').classList.remove('in-combat');
 document.getElementById('text-win').style.display = '';
 document.getElementById('dice-area').classList.add('hidden');
 cbtState = null;
 // 逃走SR直接処理（startTravelCombatを経由せず）
 const srLevel = 1;
 const target = srLevel * 5 + 15;
 const storyEl = document.getElementById('story');
 travelLog(`<span style="color:#b8a890"> ${enemy.name}から逃げようとする…</span>`);
 setupSavingRoll({
 attr: 'spd',
 level: srLevel,
 onSuccess: () => {
 const dmg = Math.max(1, Math.floor(enemy.mr / 10));
 PC.con = Math.max(0, PC.con - dmg);
 updateHUD();
 travelLog(`<span style="color:#e8e4d8"> 逃走成功！（背中に攻撃 体力-${dmg}）</span>`);
 changeAlignment(0, -0.5); // 逃亡：混沌+0.5
 if(PC.con <= 0){ setTimeout(()=>go('DEAD'), 800); return; }
 renderChoices([{label:'▶ 旅を続ける', fn:()=>{
  renderChoices([]);
  document.getElementById('dice-area').classList.add('hidden');
  document.getElementById('text-win').style.display='';
  ts._resumeWithoutIncrement = true;
  setTimeout(_travelTickSched(), ts.interval);
 }}]);
 },
 onFail: () => {
 travelLog(`<span class="red"> 逃走失敗！戦うしかない！</span>`);
 renderChoices([{label:'▶ OK', fn:()=>{
  document.getElementById('dice-area').classList.add('hidden');
  document.getElementById('text-win').style.display='';
  setTimeout(() => startTravelCombat(enemy), 200);
 }}]);
 },
 });
 };
 choices.appendChild(fleeBtn);
 }
}

function startTravelCombat(enemy){
 renderChoices([]);
 drawScene('combat');
 document.getElementById('dice-area').classList.add('hidden');
 hideMagicArea();
 if(window.innerWidth < 860) document.getElementById('inv-panel').classList.add('hidden');

 const ts = travelState;
 const remainDays = ts.totalDays - ts.daysDone;
 const isCoach = ts.method === 'coach';

 // 乗合馬車演出：同乗者が逃げ出すメッセージをログに追記
 if(isCoach){
 travelLog(`<span style="color:#c0b098"> 馬車が急停止！乗客たちは悲鳴を上げて逃げ出した！</span>`);
 }

 // 同行配達依頼で移動中なら、リーダーが個性に応じた台詞で戦闘に入る
 const _deliveryQ2 = _getActiveCompanionDeliveryQuest();
 if(_deliveryQ2){
  const fieldLines = _deliveryQ2.leaderPersonality.field;
  const line = Array.isArray(fieldLines) ? fieldLines[Math.floor(Math.random()*fieldLines.length)] : fieldLines;
  travelLog(`<span style="color:#c8b8a0">${_deliveryQ2.leader.name}が声を張り上げた。${line}</span>`);
 }

 startCombat({
 name: enemy.count > 1 ? `${enemy.name}×${enemy.count}` : enemy.name,
 enemies: enemy.enemies,
 armor:enemy.armor,
 isWarrior: false,
 canFlee: true,
 win: '__noop__',
 lose: 'DEAD',
 _isTravelCombat: true,
 onWin: ()=>{
  // travel-log-wrapを退避（text-win表示でstoryがリセットされる前に）
  const savedLog = document.getElementById('travel-log-wrap');
  const savedLogHTML = savedLog ? savedLog.outerHTML : '';
  document.getElementById('cbt-area').classList.add('hidden');
  document.getElementById('scroll-area').classList.remove('in-combat');
  document.getElementById('text-win').style.display = '';
  cbtState = null;
  drawScene('travel');
  // travel-log-wrapを復元（story内に）
  const storyEl2 = document.getElementById('story');
  if(storyEl2){
   storyEl2.innerHTML = savedLogHTML || `<div id="travel-log-wrap" style="border-top:1px solid var(--panel2);margin-top:8px;padding-top:8px;font-size:var(--font-base)"><div id="travel-events"></div></div>`;
  }
  let rewardMsg = '';
  if(isCoach){
   const reward = 10 + Math.floor(Math.random() * 21);
   gainGPAll(reward);
   rewardMsg = `　謝礼: ${reward}GP`;
  } else {
   const treasureDesc = cbtState?._treasureDesc || '';
   if(treasureDesc) rewardMsg = `　${treasureDesc}`;
  }
  updateHUD();
  const countTxt = enemy.count > 1 ? `×${enemy.count}` : '';
  travelLog(`<span style="color:#f0ece0"> ${ts.daysDone}日目：${enemy.name}${countTxt}を倒した！${rewardMsg}</span>`);
  renderChoices([{
   label:'▶ 旅を続ける',
   fn:()=>{
    renderChoices([]);
    ts._resumeWithoutIncrement = true;
    setTimeout(_travelTickSched(), ts.interval);
   }
  }]);
 },
 });
}

function renderTravelEvents(events){
 if(!events.length) return;
 events.forEach(aged => {
 if(aged.event === 'birthday')
 travelLog(`<span style="color:#f0ece0"> 誕生日！ ${aged.age}歳になった。</span>`);
 else if(aged.event === 'aging')
 travelLog(`<span class="ora"> 加齢（${aged.age}歳）：全能力値 -1</span>`);
 else if(aged.event === 'death')
 travelLog(`<span class="red"> 旅の途中、老衰により倒れた…享年${aged.age}歳。</span>`);
 });
}


// 宿屋休憩の共通処理
function innRest(cost){
 if(totalCP() < cost){ alert('所持金が足りない！'); return; }
 payPrice(cost/100);
 // 宿屋で休むと村の時刻を朝にリセット（ヴェルダ裏路地の時刻連動用）
 GAME_TIME.hour = 6;
 PC.con = Math.min(PC.maxCon, PC.con + Math.floor(PC.maxCon * 0.5));
 // STを最大値まで完全回復（魔法消費分を含む）
 PC.st = PC.maxSt;
 const msgs = [];
 // PC自身の回復メッセージ
 const _conHealed = Math.min(PC.maxCon, PC.con + Math.floor(PC.maxCon * 0.5)) - (PC.con - Math.floor(PC.maxCon * 0.5));
 msgs.push(`体力が回復した（体力+${Math.floor(PC.maxCon * 0.5)}）`);
 // 毒治癒
 if(PC._poisoned){
 PC._poisoned = false;
 msgs.push('毒が癒えた');
 }
 // 飢え回復
 if(PC._hungerDmg > 0){
 PC.st = Math.min(PC._stBase || PC.maxSt, PC.st + PC._hungerDmg);
 PC.con = Math.min(PC._conBase || PC.maxCon, PC.con + PC._hungerDmg);
 PC.dex = Math.min(PC._dexBase || PC.dex + PC._hungerDmg, PC.dex + PC._hungerDmg);
 msgs.push(`飢えが回復（ST/CON/DEX +${PC._hungerDmg}）`);
 PC._hungerDmg = 0;
 PC._stBase = PC._conBase = PC._dexBase = null;
 }
 // パーティNPCのCON・ST回復
 const aliveParty = (PC.party||[]).filter(n=>n.con>0);
 if(aliveParty.length > 0){
 aliveParty.forEach(n=>{
  n.con = Math.min(n.maxCon, n.con + Math.floor(n.maxCon * 0.5));
  // STも最大値まで回復（魔法消費分を含む）
  n.st = n.maxSt || n.st;
 });
 msgs.push(`仲間も回復（${aliveParty.map(n=>n.name).join('、')}）`);
 }
 // 凍傷回復（段階3以上は宿屋でのみ回復）
 const frostLvl = getFrostbiteLevel();
 if(frostLvl > 0 && frostLvl < 5){
  healFrostbite();
  msgs.push(`凍傷が回復（${FROSTBITE_EFFECTS[getFrostbiteLevel()].label}）`);
 }
 if(msgs.length) showSaveToast(' ' + msgs.join('、') + '！');
 const _innBack = currentNodeId;
 showTimePass(1, ()=>{ checkNeriaChaosSiege(); checkKalvoSiege(); fcVisitAfterRest(_innBack, '宿屋'); });
}

// 従来のshowTimePass（休憩・クエスト等、短期間用）
function showTimePass(days, callback){
 if(days <= 0){ if(callback) callback(); return; }
 const aged = advanceDays(days);
 let msg = `<span style="color:#ece8e0">⏳ ${days}日が経過した。</span> ${dateStr()}`;
 if(aged){
 if(aged.event === 'birthday')
 msg += `<br><span style="color:#f0ece0"> 誕生日！ ${aged.age}歳になった。</span>`;
 else if(aged.event === 'aging')
 msg += `<br><span class="ora"> 加齢：強さ・知力・運・魅力・器用さ・素早さ・体力 が各-1</span>`;
 else if(aged.event === 'death')
 msg += `<br><span class="red"> 老衰により死亡…享年${aged.age}歳。</span>`;
 }
 const storyEl = document.getElementById('story');
 if(storyEl)
 storyEl.innerHTML += `<div style="border-top:1px solid var(--panel2);margin-top:8px;padding-top:8px;font-size:calc(var(--font-base) + 1px)">${msg}</div>`;
 if(aged && aged.event === 'death'){ setTimeout(()=>go('DEAD_OLDAGE'),1500); return; }
 if(callback) setTimeout(callback, 700);
}

// ── RACE MODIFIERS ─────────────────────
const RACE_MODS = {
 human: { st:1, iq:1, lk:1, con:1, dex:1, chr:1, spd:1 },
 elf: { st:1, iq:1.5, lk:1, con:0.667,dex:1.5, chr:1, spd:1 },
 dwarf: { st:2, iq:1, lk:1, con:2, dex:1, chr:0.667, spd:1 },
 halfling: { st:0.5, iq:1, lk:1, con:2, dex:1.5, chr:1, spd:1 },
 fairy: { st:0.25,iq:1, lk:1.5, con:0.25, dex:1.5, chr:2, spd:1 },
 leprechaun: { st:0.5, iq:1.5, lk:1.5, con:1, dex:1.5, chr:1, spd:1 },
 // ── モンスター種族（プレイアブル。上級者向け・弱点なしの尖った選択肢） ──
 troll:  { st:3,    iq:1, lk:1, con:3,    dex:1,   chr:1,    spd:1 },
 ogre:   { st:2,    iq:1, lk:1, con:2,    dex:1,   chr:1,    spd:1 },
 orc:    { st:1,    iq:1, lk:1, con:1,    dex:1,   chr:1,    spd:1 },
 goblin: { st:0.75, iq:1, lk:1, con:0.75, dex:1.5, chr:0.75, spd:1 },
};
function applyRace(base, race){
 const m = RACE_MODS[race];
 const res = {};
 Object.keys(m).forEach(k => res[k] = Math.round(base[k] * m[k]));
 return res;
}

