// 地方状態システム：装備屋の品揃え劣化（物流途絶度）／鹵獲品・中古品の出現（治安悪化度）
// ══════════════════════════════════════════
// 物流途絶度の段階に応じて、装備屋の店頭から除外する武器名（段階が進むごとに累積）
// 段階1（不穏）：傑作品・両手の重量級武器・弓・魔法使いの杖を除外
