function drawScene(name){
 const cv=document.getElementById('sc');
 if(!cv)return;
 const c=cv.getContext('2d');
 c.clearRect(0,0,W,H);
 (SCENES[name]||SCENES.dungeon)(c);
}

// ── Title art ──
(function(){
 const cv=document.getElementById('title-cv');
 if(!cv)return;
 const c=cv.getContext('2d');
 SCENES.title(c);
})();


// ──────────────────────────────────────
// CHAR GEN
// ──────────────────────────────────────
let selectedType = 'warrior';
let startGold = 0;

function selectType(t){
 selectedType = t;
 document.getElementById('type-warn-rogue')?.classList.add('hidden');
 document.getElementById('card-warrior').classList.toggle('selected', t==='warrior');
 document.getElementById('card-wizard').classList.toggle('selected', t==='wizard');
 document.getElementById('card-rogue')?.classList.toggle('selected', t==='rogue');
}

function toggleStatEdit(){
 const on = document.getElementById('stat-edit-toggle').checked;
 window._manualStatEdit = on;
 const ids = ['a-st','a-iq','a-lk','a-con','a-dex','a-chr','a-spd'];
 ids.forEach(id=>{
  const el = document.getElementById(id);
  if(el) on ? el.removeAttribute('readonly') : el.setAttribute('readonly','');
 });
 document.getElementById('stat-edit-label').textContent = on ? '手動入力：オン（種族補正後の値を直接入力）' : '手動入力：オフ';
 document.getElementById('stat-edit-label').style.color = on ? '#e8e0d0' : 'var(--dim)';
 document.getElementById('stat-edit-track').style.background = on ? '#4a3200' : '#2a1a0a';
 document.getElementById('stat-edit-track').style.borderColor = on ? '#e8e0d0' : '#554422';
 document.getElementById('stat-edit-thumb').style.left = on ? '22px' : '2px';
 document.getElementById('stat-edit-thumb').style.background = on ? '#ffcc44' : '#665533';
 // 手動入力時は上の入力欄がそのまま最終ステータスになるため見出しを切り替える
 const rlabel = document.getElementById('stat-after-race-label');
 if(rlabel) rlabel.textContent = on ? '◆ 最終ステータス（手動入力のため種族補正は適用されません）' : '◆ 種族補正後ステータス';
 updateAddsPreview();
}

function rollStats(){
 ['a-st','a-iq','a-lk','a-con','a-dex','a-chr','a-spd'].forEach(id=>{
 document.getElementById(id).value = Nd6(3);
 });
 updateAddsPreview();
}

function rollGold(){
 startGold = Nd6(3)*10;
 document.getElementById('gp-result').textContent = startGold;
}

function getBaseStats(){
 return {
 st:+document.getElementById('a-st').value||10,
 iq:+document.getElementById('a-iq').value||10,
 lk:+document.getElementById('a-lk').value||10,
 con:+document.getElementById('a-con').value||10,
 dex:+document.getElementById('a-dex').value||10,
 chr:+document.getElementById('a-chr').value||10,
 spd:+document.getElementById('a-spd').value||10,
 };
}

function updateAddsPreview(){
 const race = document.getElementById('a-race').value;
 const base = getBaseStats();
 // 手動入力時は入力値を「種族補正後」の値としてそのまま扱う（再度の補正はしない）
 const applied = window._manualStatEdit ? base : applyRace(base, race);
 const st = applied.st, lk = applied.lk, dex = applied.dex;
 let adds=0;
 [st,lk,dex].forEach(v=>{if(v>12)adds+=v-12;else if(v<9)adds+=v-9;});
 document.getElementById('prev-adds').textContent=(adds>=0?'+':'')+adds;
 document.getElementById('prev-wt').textContent=st*100;

 // 種族補正後のステータスを全表示
 const preview = document.getElementById('stat-after-race');
 if(preview){
 const labels={st:'強さ',iq:'知力',lk:'運',con:'体力',dex:'器用さ',chr:'魅力',spd:'素早さ'};
 preview.innerHTML = Object.keys(labels).map(k=>{
 const before = base[k], after = applied[k];
 const diff = after - before;
 const color = diff>0?'var(--nature2)':diff<0?'var(--danger)':'var(--mid)';
 const sign = diff>0?'+':'';
 return `<div class="sp-cell">${labels[k]}<span style="color:${diff!==0?color:'var(--gold2)'}">${after}${diff!==0?`<span style="font-size:calc(var(--font-base) + 1px);color:${color}">${sign}${diff}</span>`:''}</span></div>`;
 }).join('');
 }
}

['a-st','a-iq','a-lk','a-con','a-dex','a-chr','a-spd'].forEach(id=>{
 const el=document.getElementById(id);
 if(el) el.addEventListener('input',updateAddsPreview);
});

const RACE_INFO_TEXT = {
 human: '人間: 全能力値 ×1（補正なし）',
 elf: 'エルフ: 知力・器用さ ×3/2、体力 ×2/3',
 dwarf: 'ドワーフ: 強さ・体力 ×2、魅力 ×2/3',
 halfling: 'ハーフリング: 強さ ×1/2、体力 ×2、器用さ ×3/2',
 fairy: 'フェアリー: 強さ・体力 ×1/4、運・器用さ ×3/2、魅力 ×2',
 leprechaun: 'Leprechaun: ST ×1/2、IQ・LK・DEX ×3/2',
 troll: '⚠ トロール: 強さ・体力 ×3。規格外の肉体を持つ上級者向けの種族。弱点による帳尻合わせはなく、ゲームバランスを大きく踏み越える。',
 ogre: '⚠ オーガ: 強さ・体力 ×2。並外れた膂力を持つ、荒々しい種族。トロールに次ぐ強さの上級者向けの選択肢。',
 orc: 'オーク: 全能力値 ×1（人間と同等の水準）。人間社会にも比較的馴染みやすい種族。',
 goblin: 'ゴブリン: 強さ・体力 ×3/4、器用さ ×3/2、魅力 ×3/4。素早く小柄な種族。',
};
function updateRaceInfo(){
 const r=document.getElementById('a-race').value;
 document.getElementById('race-info').textContent=RACE_INFO_TEXT[r];
}

// ── キャラクター作成：身長・体重 ──
// 人間を基準にした範囲（身長125〜210cm・体重35〜170kg）でランダムに決め、種族係数をかけて表示する
const RACE_SIZE_MODS = {
 human:      { height:1,    weight:1 },
 dwarf:      { height:2/3,  weight:7/8 },
 elf:        { height:11/10,weight:1 },
 halfling:   { height:1/2,  weight:1/2 },
 fairy:      { height:1/10, weight:1/200 },
 leprechaun: { height:1/3,  weight:1/4 },
 troll:      { height:2,    weight:4 },
 orc:        { height:1,    weight:1 },
 ogre:       { height:3/2,  weight:2 },
 goblin:     { height:3/4,  weight:3/4 },
};
// 人間基準（身長125〜210cm・体重35〜170kg）でランダムに決め、種族係数をかける共通処理
// PCのキャラ作成・仲間NPCの生成・子どもの仲間入り時に共通で使う
function rollBodySize(race){
 const mod = RACE_SIZE_MODS[race] || RACE_SIZE_MODS.human;
 const hBase = 125 + Math.random()*(210-125);
 const wBase = 35 + Math.random()*(170-35);
 return {
  height: Math.round(hBase*mod.height*10)/10,
  weight: Math.round(wBase*mod.weight*100)/100,
 };
}
function rollHeight(){
 window._pcHeightBase = 125 + Math.random()*(210-125);
 updateSizeDisplay();
}
function rollWeight(){
 window._pcWeightBase = 35 + Math.random()*(170-35);
 updateSizeDisplay();
}
function updateSizeDisplay(){
 const race = document.getElementById('a-race').value;
 const mod = RACE_SIZE_MODS[race] || RACE_SIZE_MODS.human;
 const hEl = document.getElementById('a-height');
 const wEl = document.getElementById('a-weight');
 if(hEl) hEl.value = (window._pcHeightBase!=null) ? (Math.round(window._pcHeightBase*mod.height*10)/10) : '';
 if(wEl) wEl.value = (window._pcWeightBase!=null) ? (Math.round(window._pcWeightBase*mod.weight*100)/100) : '';
}

function startGame(){
 // Gather base stats
 const base={
 st:+document.getElementById('a-st').value||10,
 iq:+document.getElementById('a-iq').value||10,
 lk:+document.getElementById('a-lk').value||10,
 con:+document.getElementById('a-con').value||10,
 dex:+document.getElementById('a-dex').value||10,
 chr:+document.getElementById('a-chr').value||10,
 spd:+document.getElementById('a-spd').value||10,
 };
 const race=document.getElementById('a-race').value;
 // 手動入力時は入力値を「種族補正後」の値としてそのまま扱う（再度の補正はしない）
 const applied = window._manualStatEdit ? base : applyRace(base,race);

 // Wizard check
 const warn=document.getElementById('type-warn');
 if(selectedType==='wizard'&&(applied.iq<10||applied.dex<8)){
 warn.classList.remove('hidden');return;
 }
 warn.classList.add('hidden');


 // Build PC
 PC.name=document.getElementById('a-name').value||'Adventurer';
 PC.race=race;PC.type=selectedType;
 // 身長・体重（未入力なら振っていなかったものとしてこの場でランダムに決定する）
 if(window._pcHeightBase==null) window._pcHeightBase = 125 + Math.random()*(210-125);
 if(window._pcWeightBase==null) window._pcWeightBase = 35 + Math.random()*(170-35);
 const sizeMod = RACE_SIZE_MODS[race] || RACE_SIZE_MODS.human;
 PC.height = Math.round(window._pcHeightBase*sizeMod.height*10)/10;
 PC.weight = Math.round(window._pcWeightBase*sizeMod.weight*100)/100;
 Object.assign(PC,applied);
 PC.maxCon=PC.con;PC.maxSt=PC.st;
 PC.gold=startGold||Nd6(3)*10;
 PC.ap=0;PC.level=1;
 PC.invWeapons=[];PC.invArmors=[];PC.invBoots=false;PC.invBootsName=null;PC._spareFootwear={};PC.invEquip=[];PC.invSpecialties=[];
 PC.equippedWeapons=[];PC.equippedArmors=[];PC.equippedBoots=false;PC.equippedClothing=false;
 PC._torchStock=0; PC._torchTurns=0;
 PC.quests=[]; PC.party=[];
 PC._formerCompanions = []; // 前の代のNPC交友記録は引き継がない
 _fcVisitLastDay = null;
 PC._troupes = {}; PC._troupeContract = null; // 旅芸人の一座は新しい代で作り直し、護衛契約は引き継がない
 PC._tavernThanks = {}; // 前の代の酒場のお礼（受け取り待ち）は引き継がない
 PC.lifeEvents = []; // 前の代のライフイベントは引き継がない
 PC._heroTowns = {}; // 前の代の英雄ステータスは引き継がない
 PC._heroRegions = {};
 PC.food = 0; // 前の代の食料は引き継がない
 rollLanguages(PC); // 知力に応じてモンスター語の習得判定
 PC.spouse = []; // 前の代の配偶者記録は引き継がない
 PC._questPenalties = {}; // 前の代の依頼期限切れ罰金は引き継がない
 PC.spdBase = PC.spd; // 重量ペナルティ計算用の基準SPD

 // 年齢・誕生日の初期化（開始年齢20歳）
 PC.age = 15 + Math.floor(Math.random() * 16); // 15〜30歳
 PC.lifespan = rollLifespan(race);
 PC.alignment_ethics = Math.floor((Math.random()-0.5)*60);
 PC.alignment_order  = Math.floor((Math.random()-0.5)*60);
 // 暦の引き継ぎ：_inheritTimeフラグがあればリセットしない
 if(!PC._inheritTime){
 GAME_TIME.totalDays = 0;
 }
 PC._inheritTime = undefined;
 // 拠点の引き継ぎ（暦を引き継ぐ新規PCの場合のみ）。それ以外は前のキャラクターのデータが残らないよう必ず空にリセットする
 if(PC._inheritedProperties){
  PC.properties = PC._inheritedProperties;
  PC._inheritedProperties = undefined;
 } else {
  PC.properties = {};
 }
 // 混沌・飢饉の引き継ぎ
 if(PC._inheritedChaosNest){
  PC._chaosNest = PC._inheritedChaosNest;
  PC._inheritedChaosNest = undefined;
 }
 if(PC._inheritedFamineYear){
  PC._famineYear = PC._inheritedFamineYear;
  PC._famineHeroName = PC._inheritedFamineHeroName||'';
  PC._inheritedFamineYear = undefined;
  PC._inheritedFamineHeroName = undefined;
 }
 // 英雄ステータス（町・地方）は代々引き継がず、新しいキャラクターが自分で獲得する必要がある
 PC._inheritedHeroRegions = undefined;
 PC._inheritedHeroTowns = undefined;
 // 地方伝説の英雄（歴代）は引き継ぐ。記録のない地方は、50〜80年前に死んだ英雄をランダムに設定する
 PC._regionLegends = PC._inheritedRegionLegends || {};
 PC._inheritedRegionLegends = undefined;
 Object.keys(HERO_REGIONS).forEach(regionKey=>{
  if(!PC._regionLegends[regionKey]){
   const yearsAgo = 50 + Math.floor(Math.random()*31); // 50〜80年前
   PC._regionLegends[regionKey] = { name: pickNPC(), deathDay: GAME_TIME.totalDays - yearsAgo*365 };
  }
 });
 if(PC._inheritedHarvestYear){
  PC._harvestYear = PC._inheritedHarvestYear;
  PC._harvestResult = PC._inheritedHarvestResult;
  PC._foodPriceMult = PC._inheritedFoodPriceMult || 1.0;
  PC._harvestPriceApplied = PC._inheritedHarvestPriceApplied;
  PC._inheritedHarvestYear = undefined;
  PC._inheritedHarvestResult = undefined;
  PC._inheritedFoodPriceMult = undefined;
  PC._inheritedHarvestPriceApplied = undefined;
 }
 // 地方状態システムの引き継ぎ（世界に残る記録。無ければensureRegionCondition()が初回アクセス時に0で初期化する）
 if(PC._inheritedRegionCondition){
  PC._regionCondition = PC._inheritedRegionCondition;
  PC._inheritedRegionCondition = undefined;
 } else {
  PC._regionCondition = undefined;
 }
 // アンビエント圧力も同様に引き継ぐ（無ければensureRegionConditionAmbient()が初回アクセス時にランダム初期化する）
 if(PC._inheritedRegionConditionAmbient){
  PC._regionConditionAmbient = PC._inheritedRegionConditionAmbient;
  PC._inheritedRegionConditionAmbient = undefined;
 } else {
  PC._regionConditionAmbient = undefined;
 }
 // 危機的状況からのPC主導の回復の記録も引き継ぐ（先代以前の功績として残り、未回復の「危機的に達した」フラグも持ち越す）
 if(PC._inheritedRegionWasCrisis){
  PC._regionWasCrisis = PC._inheritedRegionWasCrisis;
  PC._inheritedRegionWasCrisis = undefined;
 } else {
  PC._regionWasCrisis = undefined;
 }
 if(PC._inheritedRegionCrisisRecord){
  PC._regionCrisisRecord = PC._inheritedRegionCrisisRecord;
  PC._inheritedRegionCrisisRecord = undefined;
 } else {
  PC._regionCrisisRecord = undefined;
 }
 // 巣窟ダンジョン（全箇所）の引き継ぎ（無ければ各initXxxDungeon()が初回アクセス時に空の状態で初期化する）
 if(PC._inheritedLairDungeons){
  Object.entries(LAIR_DUNGEON_REG).forEach(([key, def])=>{
   if(PC._inheritedLairDungeons[key]) PC[def.stateProp] = PC._inheritedLairDungeons[key];
  });
  PC._inheritedLairDungeons = undefined;
 }
 PC._regionConditionLastKey = undefined; // 新PCの最初のtickで現在月を基準に取り直す
 const startDate = getCurrentDate();
 const birthMonth = Math.floor(Math.random() * 12) + 1; // 1〜12月
 const birthDay = Math.floor(Math.random() * 30) + 1; // 1〜30日
 PC.birthYear = startDate.year - PC.age;
 PC.birthMonth = birthMonth;
 PC.birthDay = birthDay;

 // 二つ名を付与（手動入力トグルがオンの場合は固定称号）
 const _isManual = !!(window._manualStatEdit);
 PC.epithet = _isManual ? '彼方から来た' : generateEpithet();

 // Wizard starts with all L1 spells
 if(PC.type==='wizard') PC.spells=[...SPELLS_L1];
 else PC.spells=[];

 // 開始街をランダムに決定してPCに記録
 const startTowns = ['khazan','port_argon','stonehiem','elsia','verda','rimholm','marakai','al_rashid','oasis_fort','saroon','duna','yeldun','frostpeak','ashveil'];
 const startTownsOutlying = ['verda','rimholm','marakai','oasis_fort','saroon','ashveil','nifurvik','iskald'];
 const townPool = _isManual ? startTownsOutlying : startTowns;
 PC._startTown = townPool[Math.floor(Math.random() * townPool.length)];
 PC.town = PC._startTown;
 initTrust(PC._startTown);
 PC.wanted = {}; // 前の代の手配度は引き継がない

 // shop-areaをスキップしてゲーム画面へ直接遷移
 document.getElementById('chargen').classList.add('hidden');
 const g = document.getElementById('game');
 g.classList.remove('hidden'); g.style.display = 'flex';
 updateHUD(); updateTimebar();
 window._manualStatEdit = false;
 if(_isManual){
  // 手動入力（彼方から来た）は、その特殊な生い立ちを固定で使う（選択画面は挟まない）
  PC.background = { family:'この世界のどこにも、自分の生まれた場所はない。気がついたときには、見知らぬ土地に立っていた。', motive:'ここに来た意味を知りたい。それだけが、前へ進む理由だ。' };
  go('BACKGROUND_REVEAL');
 } else {
  chooseBackgroundMode();
 }
}

// ──────────────────────────────────────
// SHOP
// ──────────────────────────────────────
let cartWeight=0;

function showShop(){
 document.getElementById('chargen').classList.add('hidden');
 document.getElementById('shop-area').classList.remove('hidden');
 renderShop();
}

function renderShop(){
 document.getElementById('shop-gp').innerHTML=formatMoney();
 document.getElementById('shop-wt').textContent=cartWeight;
 document.getElementById('shop-maxwt').textContent=weightPossible();
 const el=document.getElementById('shop-list');
 el.innerHTML='';

 const sec=(title,items,fn)=>{
 const h=document.createElement('div');
 h.style.cssText='font-size:calc(var(--font-base) + 1px);color:#f0ece0;margin:12px 0 6px';h.textContent=title;el.appendChild(h);
 items.forEach(it=>fn(it,el));
 };

 sec(' WEAPONS',WEAPONS_TABLE,(it,p)=>{
 const canUse=it.stReq<=PC.st&&it.dexReq<=PC.dex&&(PC.type==='warrior'||PC.type==='rogue'||it.dice<=2)&&(!PC._noHeavyWeapon||it.dice<=2)&&(!it.wizard||PC.type==='wizard');
 const div=document.createElement('div');div.className='shop-item';
 div.innerHTML=`<h4>${it.name} ${canUse?'':'<span style="color:#e0d0d0">※要件未満</span>'}</h4>
 <p>${it.dice}D+${it.adds} / 強さ≥${it.stReq} 器用さ≥${it.dexReq} ${it.twoHand?'両手':''}${it.wizard?'　<span style="color:#c8b0e0">魔法使い専用</span>':''}　Wgt:${it.weight}</p>
 <span class="price">${formatItemCost(it.cost)}</span>
 <button class="buy-btn" ${!canUse||totalCP()<it.cost*100||cartWeight+it.weight>weightPossible()?'disabled':''} onclick="buyWeapon(${WEAPONS_TABLE.indexOf(it)})">BUY</button>`;
 p.appendChild(div);
 });

 sec(' ARMOR',ARMOR_TABLE,(it,p)=>{
 const canUse=it.stReq<=PC.st;
 const div=document.createElement('div');div.className='shop-item';
 div.innerHTML=`<h4>${it.name} ${canUse?'':'<span style="color:#e0d0d0">※強さ不足</span>'}</h4>
 <p>防護:${it.hits}${PC.type==='warrior'?`(Warrior2倍→${it.hits*2})`:''}　強さ≥${it.stReq}　重量:${it.weight}</p>
 <span class="price">${formatItemCost(it.cost)}</span>
 <button class="buy-btn" ${!canUse||totalCP()<it.cost*100||cartWeight+it.weight>weightPossible()?'disabled':''} onclick="buyArmor(${ARMOR_TABLE.indexOf(it)})">BUY</button>`;
 p.appendChild(div);
 });

 sec(' EQUIPMENT',EQUIP_TABLE,(it,p)=>{
 if(it.wizard&&PC.type!=='wizard')return;
 const dispWeight = it._isFood ? (it._foodAmt||1)*5 : it.weight;
 const addWeight = it._isFood ? (it._foodAmt||1)*5 : it.weight;
 const effectiveCost = it._isFood ? foodPrice(it.cost) : it.cost;
 const div=document.createElement('div');div.className='shop-item';
 const priceLabel = it._isFood && effectiveCost !== it.cost
  ? `<span class="price" style="color:${effectiveCost>it.cost?'var(--danger)':'var(--nature2)'}">${formatItemCost(effectiveCost)}</span>`
  : `<span class="price">${formatItemCost(effectiveCost)}</span>`;
 div.innerHTML=`<h4>${it._isFood ? ' '+it.name : it.name}</h4>
 <p>${it._isFood ? `食料ポイント+${it._foodAmt||1}　Wgt:${(it._foodAmt||1)*5}` : `Wgt:${dispWeight}`}</p>
 ${priceLabel}
 <button class="buy-btn" ${totalCP()<effectiveCost*100||cartWeight+addWeight>weightPossible()?'disabled':''} onclick="buyEquip(${EQUIP_TABLE.indexOf(it)})">BUY</button>`;
 p.appendChild(div);
 });
}

function buyWeapon(i){
 const it=WEAPONS_TABLE[i];
 if(totalCP()<it.cost*100)return;
 if(it.wizard && PC.type!=='wizard')return;
 payPrice(it.cost);cartWeight+=it.weight;
 PC.invWeapons.push({name:it.name,dice:it.dice,adds:it.adds,twoHand:it.twoHand,stReq:it.stReq||0,dexReq:it.dexReq||0,weight:it.weight||0,...(it.isWizardStaff?{isWizardStaff:true}:{})});
 renderShop();
}
function buyArmor(i){
 const it=ARMOR_TABLE[i];
 if(totalCP()<it.cost*100)return;
 payPrice(it.cost);cartWeight+=it.weight;
 PC.invArmors.push({name:it.name,hits:it.hits,stReq:it.stReq,isShield:it.isShield||false});
 renderShop();
}
function buyEquip(i){
 const it=EQUIP_TABLE[i];
 const effectiveCost = it._isFood ? foodPrice(it.cost) : it.cost;
 if(totalCP()<effectiveCost*100)return;
 payPrice(effectiveCost);
 if(it._isFood){ const amt=it._foodAmt||1; PC._food=(PC._food||0)+amt; cartWeight+=amt*5; }
 else if(it.name==='ブーツ'||it.name==='サンダル'){
  if(PC.invBoots){ addSpareFootwear(PC, it.name); } // すでに1足持っている場合は予備にする
  else { PC.invBoots=true; PC.invBootsName=it.name; PC._bootsWearDays=0; PC._bootsBreakThreshold=null; }
  cartWeight+=it.weight; }
 else if(it.name==='松明'){ PC._torchStock=(PC._torchStock||0)+1; cartWeight+=it.weight; }
 else if(it.name==='防寒着と荷物袋'){ PC.invClothing=true; PC.invClothingName=it.name; cartWeight+=it.weight; }
 else { PC.invEquip.push(it.name); cartWeight+=it.weight; }
 renderShop();
}

